const i18nState = {
    cache: {},
    currentLang: 'tr',
    async init() {
        this.currentLang = await ipcRenderer.invoke('i18n-get-language');
        this.cache = await ipcRenderer.invoke('i18n-get-all');
        document.documentElement.lang = this.currentLang;
        this.translateDom();
    },
    t(key, fallback, params = {}) {
        const value = key.split('.').reduce((acc, part) => (acc && acc[part] !== undefined ? acc[part] : undefined), this.cache);
        const template = typeof value === 'string' && value ? value : fallback;
        return Object.entries(params).reduce((result, [paramKey, paramValue]) => result.replaceAll(`{${paramKey}}`, String(paramValue)), template);
    },
    translateDom() {
        document.querySelectorAll('[data-i18n]').forEach((el) => {
            const key = el.getAttribute('data-i18n');
            const value = this.t(key, '');
            if (value) {
                el.textContent = value;
            }
        });
        document.querySelectorAll('[data-i18n-html]').forEach((el) => {
            const key = el.getAttribute('data-i18n-html');
            const value = this.t(key, '');
            if (value) {
                el.innerHTML = value;
            }
        });
        document.querySelectorAll('[data-i18n-placeholder]').forEach((el) => {
            const key = el.getAttribute('data-i18n-placeholder');
            const value = this.t(key, '');
            if (value) {
                el.setAttribute('placeholder', value);
            }
        });
        document.querySelectorAll('[data-i18n-aria]').forEach((el) => {
            const key = el.getAttribute('data-i18n-aria');
            const value = this.t(key, '');
            if (value) {
                el.setAttribute('aria-label', value);
            }
        });
        const titleEl = document.querySelector('title[data-i18n]');
        if (titleEl) {
            const value = this.t(titleEl.getAttribute('data-i18n'), '');
            if (value) {
                document.title = value;
            }
        }
    }
};

function t(key, fallback, params = {}) {
    return i18nState.t(key, fallback, params);
}

const BROADCAST_ROOM_GLOBAL_SHORTCUT_ACTIONS = {
    broadcastRoomGlobalToggleYouTubeLive: 'Alt+Ctrl+L',
    broadcastRoomGlobalToggleBotRecording: 'Alt+Ctrl+B',
    broadcastRoomGlobalToggleLiveTranslation: 'Alt+Ctrl+T',
    broadcastRoomGlobalReadYouTubeStats: 'Alt+Ctrl+Y'
};
const BROADCAST_ROOM_OWNER_KEY_STORAGE_KEY = 'broadcastRoomOwnerKey';

function getBroadcastRoomOwnerKey() {
    try {
        const existing = String(localStorage.getItem(BROADCAST_ROOM_OWNER_KEY_STORAGE_KEY) || '').trim();
        if (existing) {
            return existing;
        }
        const generated = window.crypto?.randomUUID?.()
            || `owner-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
        localStorage.setItem(BROADCAST_ROOM_OWNER_KEY_STORAGE_KEY, generated);
        return generated;
    } catch (_error) {
        return '';
    }
}

function getStoredUserKeymap() {
    try {
        const rawSettings = localStorage.getItem('korculVideoEditorSettings');
        if (!rawSettings) return {};
        const parsed = JSON.parse(rawSettings);
        return parsed && typeof parsed.userKeymap === 'object' && parsed.userKeymap !== null
            ? parsed.userKeymap
            : {};
    } catch (_error) {
        return {};
    }
}

function loadStoredBoolean(key, fallback = true) {
    try {
        const value = window.localStorage.getItem(key);
        if (value === 'true') return true;
        if (value === 'false') return false;
    } catch (_error) {
        // Ignore storage failures and keep the default.
    }
    return fallback;
}

function saveStoredBoolean(key, value) {
    try {
        window.localStorage.setItem(key, value ? 'true' : 'false');
    } catch (_error) {
        // Ignore storage failures.
    }
}

function normalizeGlobalShortcutAccelerator(accelerator) {
    if (!accelerator) return null;
    return accelerator
        .replace(/\bCommandOrControl\b/g, 'Control')
        .replace(/\bCmdOrCtrl\b/g, 'Control')
        .replace(/\bCtrl\b/g, 'Control')
        .replace(/\bCmd\b/g, 'Command')
        .replace(/\bOption\b/g, 'Alt')
        .replace(/\bMeta\b/g, 'Super');
}

function getBroadcastRoomGlobalShortcutBinding(actionId) {
    const userKeymap = getStoredUserKeymap();
    if (userKeymap[actionId] !== undefined) {
        return userKeymap[actionId] || null;
    }
    return BROADCAST_ROOM_GLOBAL_SHORTCUT_ACTIONS[actionId] || null;
}

function getBroadcastRoomGlobalShortcutActionMap() {
    return Object.entries(BROADCAST_ROOM_GLOBAL_SHORTCUT_ACTIONS).reduce((acc, [actionId]) => {
        const normalized = normalizeGlobalShortcutAccelerator(getBroadcastRoomGlobalShortcutBinding(actionId));
        if (normalized) {
            acc[normalized] = actionId;
        }
        return acc;
    }, {});
}

