function describeSceneBackgroundFile(info = {}) {
    const sizeText = info.width && info.height ? `${info.width}x${info.height}` : '-';
    if (info.type === 'video' && info.duration) {
        return t('broadcast_room.scene_background_video_info', 'Video arka plan: {size}, süre {duration} sn.', {
            size: sizeText,
            duration: Math.round(info.duration)
        });
    }
    return t('broadcast_room.scene_background_image_info', 'Görsel arka plan: {size}.', { size: sizeText });
}

async function prepareSceneBackgroundPathIfNeeded(filePath, info, namespace = 'broadcast_room') {
    if (!info?.needsNormalize) {
        return filePath;
    }

    const warning = info.type === 'video' && info.longVideoWarning
        ? t(`${namespace}.scene_background_long_video_warning`, 'Video 30 saniyeden uzun. Arka plan videosu döngülü oynatılacağı için kısa bir video daha iyi performans verir.')
        : '';
    const message = [
        t(`${namespace}.scene_background_size_warning`, 'Seçilen dosya 1920x1080 önerisine uymuyor. Geçerli boyut: {width}x{height}.', {
            width: info.width || 0,
            height: info.height || 0
        }),
        warning,
        t(`${namespace}.scene_background_convert_question`, 'EVD dosyayı 1920x1080 arka plan kopyasına dönüştürsün mü?')
    ].filter(Boolean).join('\n\n');

    const response = await ipcRenderer.invoke('show-message-box', {
        type: 'question',
        title: t(`${namespace}.scene_background_convert_title`, 'Arka plan boyutu uyumsuz'),
        message,
        buttons: [
            t(`${namespace}.scene_background_convert_button`, 'Dönüştür'),
            t(`${namespace}.scene_background_use_original_button`, 'Özgün dosyayı kullan'),
            t(`${namespace}.scene_background_cancel_button`, 'İptal')
        ],
        defaultId: 0,
        cancelId: 2,
        noLink: true
    });

    if (response.response === 2) {
        return '';
    }
    if (response.response === 1) {
        return filePath;
    }

    setStatus(t(`${namespace}.scene_background_converting`, 'Arka plan 1920x1080 olarak hazırlanıyor...'));
    const prepared = await ipcRenderer.invoke('prepare-scene-background-file', {
        filePath,
        type: info.type
    });
    if (!prepared?.success || !prepared.path) {
        throw new Error(prepared?.error || 'background_prepare_failed');
    }
    return prepared.path;
}

async function applySceneBackgroundToObs() {
    const background = state.sceneBackground || {};
    const sourcePath = background.preparedPath || background.sourcePath || '';
    const response = await ipcRenderer.invoke('obs-set-scene-background', {
        sceneName: BROADCAST_ROOM_SCENE_NAME,
        type: background.type || 'none',
        sourcePath,
        fitMode: background.fitMode || 'cover',
        dimPercent: background.dimPercent || 0,
        logoPath: background.logoPath || '',
        logoPosition: background.logoPosition || 'top-right',
        logoSize: background.logoSize || 'medium'
    });
    if (!response?.success) {
        throw new Error(response?.error || 'background_apply_failed');
    }
    return response;
}

function createSceneBackgroundProfileSnapshot() {
    const background = state.sceneBackground || {};
    return {
        type: background.type || 'none',
        sourcePath: background.sourcePath || '',
        preparedPath: background.preparedPath || '',
        width: Number(background.width || 0),
        height: Number(background.height || 0),
        duration: Number(background.duration || 0),
        fitMode: background.fitMode || 'cover',
        dimPercent: Math.max(0, Math.min(80, Math.round(Number(background.dimPercent || 0)))),
        logoPath: background.logoPath || '',
        logoPosition: background.logoPosition || 'top-right',
        logoSize: background.logoSize || 'medium'
    };
}

function createDefaultSceneBackgroundProfileBackground() {
    return {
        type: 'none',
        sourcePath: '',
        preparedPath: '',
        width: 0,
        height: 0,
        duration: 0,
        fitMode: 'cover',
        dimPercent: 0,
        logoPath: '',
        logoPosition: 'top-right',
        logoSize: 'medium'
    };
}

function loadSceneBackgroundProfiles() {
    try {
        const raw = window.localStorage.getItem(SCENE_BACKGROUND_PROFILE_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : [];
        if (!Array.isArray(parsed)) return [];
        return parsed
            .filter((profile) => profile && typeof profile === 'object')
            .map((profile, index) => ({
                id: String(profile.id || `scene-background-profile-${index + 1}`),
                name: String(profile.name || '').trim() || t('broadcast_room.scene_background_profile_default_name', 'Arka plan profili'),
                background: {
                    ...createDefaultSceneBackgroundProfileBackground(),
                    ...(profile.background || {})
                }
            }));
    } catch (_error) {
        return [];
    }
}

function saveSceneBackgroundProfiles(profiles) {
    window.localStorage.setItem(SCENE_BACKGROUND_PROFILE_STORAGE_KEY, JSON.stringify(Array.isArray(profiles) ? profiles : []));
}

function renderSceneBackgroundProfiles(selectedId = '') {
    if (!els.sceneBackgroundProfileList) return;
    const profiles = loadSceneBackgroundProfiles();
    els.sceneBackgroundProfileList.innerHTML = '';
    if (!profiles.length) {
        const option = document.createElement('option');
        option.value = '';
        option.textContent = t('broadcast_room.scene_background_profile_empty', 'Kayıtlı profil yok');
        els.sceneBackgroundProfileList.appendChild(option);
        els.sceneBackgroundProfileList.disabled = true;
        if (els.btnApplySceneBackgroundProfile) els.btnApplySceneBackgroundProfile.disabled = true;
        if (els.btnDeleteSceneBackgroundProfile) els.btnDeleteSceneBackgroundProfile.disabled = true;
        return;
    }
    els.sceneBackgroundProfileList.disabled = false;
    profiles.forEach((profile) => {
        const option = document.createElement('option');
        option.value = profile.id;
        option.textContent = profile.name;
        option.selected = profile.id === selectedId;
        els.sceneBackgroundProfileList.appendChild(option);
    });
    if (els.btnApplySceneBackgroundProfile) els.btnApplySceneBackgroundProfile.disabled = false;
    if (els.btnDeleteSceneBackgroundProfile) els.btnDeleteSceneBackgroundProfile.disabled = false;
}

function renderSceneBackgroundStatus() {
    const background = state.sceneBackground || {};
    if (els.sceneBackgroundFitMode) els.sceneBackgroundFitMode.value = background.fitMode || 'cover';
    if (els.sceneBackgroundDimPercent) els.sceneBackgroundDimPercent.value = String(background.dimPercent || 0);
    if (els.sceneBackgroundDimValue) els.sceneBackgroundDimValue.textContent = `%${background.dimPercent || 0}`;
    if (els.sceneLogoPosition) els.sceneLogoPosition.value = background.logoPosition || 'top-right';
    if (els.sceneLogoSize) els.sceneLogoSize.value = background.logoSize || 'medium';
    if (!els.sceneBackgroundStatus) return;
    if (!background.sourcePath) {
        els.sceneBackgroundStatus.textContent = background.logoPath
            ? t('broadcast_room.scene_logo_selected_without_background', 'Arka plan seçilmedi. Seçili logo: {name}.', { name: path.basename(background.logoPath) })
            : t('broadcast_room.scene_background_empty', 'Arka plan seçilmedi.');
        return;
    }
    els.sceneBackgroundStatus.textContent = t('broadcast_room.scene_background_selected', 'Seçili arka plan: {name}. {info}', {
        name: path.basename(background.sourcePath),
        info: `${describeSceneBackgroundFile(background)} ${background.logoPath ? t('broadcast_room.scene_logo_selected_suffix', 'Logo: {name}.', { name: path.basename(background.logoPath) }) : ''}`
    });
}

async function saveCurrentSceneBackgroundProfile() {
    const profileName = String(els.sceneBackgroundProfileName?.value || '').trim()
        || t('broadcast_room.scene_background_profile_default_name', 'Arka plan profili');
    const profiles = loadSceneBackgroundProfiles();
    const selectedId = els.sceneBackgroundProfileList?.value || '';
    const existingIndex = profiles.findIndex((profile) => profile.id === selectedId);
    const nextProfile = {
        id: existingIndex >= 0 ? profiles[existingIndex].id : `scene-background-profile-${Date.now()}`,
        name: profileName,
        background: createSceneBackgroundProfileSnapshot()
    };
    if (existingIndex >= 0) {
        profiles[existingIndex] = nextProfile;
    } else {
        profiles.push(nextProfile);
    }
    saveSceneBackgroundProfiles(profiles);
    renderSceneBackgroundProfiles(nextProfile.id);
    if (els.sceneBackgroundProfileName) els.sceneBackgroundProfileName.value = nextProfile.name;
    setStatus(t('broadcast_room.scene_background_profile_saved', 'Arka plan profili kaydedildi: {name}', { name: nextProfile.name }));
}

async function applySelectedSceneBackgroundProfile() {
    const selectedId = els.sceneBackgroundProfileList?.value || '';
    const profile = loadSceneBackgroundProfiles().find((item) => item.id === selectedId);
    if (!profile) {
        setStatus(t('broadcast_room.scene_background_profile_select_required', 'Önce bir arka plan profili seçin.'));
        return;
    }
    state.sceneBackground = {
        ...state.sceneBackground,
        ...profile.background
    };
    if (els.sceneBackgroundProfileName) els.sceneBackgroundProfileName.value = profile.name;
    renderSceneBackgroundStatus();
    await applySceneBackgroundToObs().catch(() => {});
    setStatus(t('broadcast_room.scene_background_profile_applied', 'Arka plan profili uygulandı: {name}', { name: profile.name }));
}

async function deleteSelectedSceneBackgroundProfile() {
    const selectedId = els.sceneBackgroundProfileList?.value || '';
    const profiles = loadSceneBackgroundProfiles();
    const profile = profiles.find((item) => item.id === selectedId);
    if (!profile) {
        setStatus(t('broadcast_room.scene_background_profile_select_required', 'Önce bir arka plan profili seçin.'));
        return;
    }
    saveSceneBackgroundProfiles(profiles.filter((item) => item.id !== selectedId));
    renderSceneBackgroundProfiles();
    if (els.sceneBackgroundProfileName) els.sceneBackgroundProfileName.value = '';
    setStatus(t('broadcast_room.scene_background_profile_deleted', 'Arka plan profili silindi: {name}', { name: profile.name }));
}

async function selectSceneBackgroundFile() {
    const result = await ipcRenderer.invoke('open-file-dialog', {
        title: t('broadcast_room.scene_background_file_dialog_title', 'Arka plan dosyası seç'),
        properties: ['openFile'],
        filters: [
            { name: t('broadcast_room.scene_background_files_filter', 'Arka plan dosyaları'), extensions: ['jpg', 'jpeg', 'png', 'webp', 'bmp', 'mp4', 'webm', 'mov', 'm4v', 'mkv'] }
        ]
    });
    if (result.canceled || !result.filePaths?.[0]) {
        return;
    }

    const filePath = result.filePaths[0];
    const info = await ipcRenderer.invoke('inspect-scene-background-file', filePath);
    if (!info?.success) {
        throw new Error(info?.error || 'background_inspect_failed');
    }
    const preparedPath = await prepareSceneBackgroundPathIfNeeded(filePath, info, 'broadcast_room');
    if (!preparedPath) {
        setStatus(t('broadcast_room.scene_background_cancelled', 'Arka plan seçimi iptal edildi.'));
        return;
    }

    state.sceneBackground = {
        ...state.sceneBackground,
        type: info.type,
        sourcePath: filePath,
        preparedPath,
        width: info.width || 0,
        height: info.height || 0,
        duration: info.duration || 0
    };
    renderSceneBackgroundStatus();

    try {
        await applySceneBackgroundToObs();
        addDiagnosticEvent('scene', t('broadcast_room.status_scene_background_applied', 'Sahne arka planı uygulandı: {name}', {
            name: path.basename(filePath)
        }));
        setStatus(t('broadcast_room.scene_background_applied', 'Sahne arka planı uygulandı.'));
    } catch (error) {
        setStatus(t('broadcast_room.scene_background_saved_pending_obs', 'Arka plan seçildi. OBS bağlantısı hazır olduğunda sahneye uygulanacak.'));
    }
}

async function clearSceneBackground() {
    state.sceneBackground = {
        ...state.sceneBackground,
        type: 'none',
        sourcePath: '',
        preparedPath: '',
        width: 0,
        height: 0,
        duration: 0
    };
    renderSceneBackgroundStatus();
    await applySceneBackgroundToObs().catch(() => {});
    setStatus(t('broadcast_room.scene_background_cleared', 'Sahne arka planı kaldırıldı.'));
}

async function selectSceneLogoFile() {
    const result = await ipcRenderer.invoke('open-file-dialog', {
        title: t('broadcast_room.scene_logo_file_dialog_title', 'Logo dosyası seç'),
        properties: ['openFile'],
        filters: [
            { name: t('broadcast_room.scene_logo_files_filter', 'Logo dosyaları'), extensions: ['png', 'jpg', 'jpeg', 'webp', 'bmp'] }
        ]
    });
    if (result.canceled || !result.filePaths?.[0]) return;
    state.sceneBackground.logoPath = result.filePaths[0];
    renderSceneBackgroundStatus();
    await applySceneBackgroundToObs().catch(() => {});
    setStatus(t('broadcast_room.scene_logo_selected', 'Logo seçildi: {name}', { name: path.basename(state.sceneBackground.logoPath) }));
}

async function clearSceneLogo() {
    state.sceneBackground.logoPath = '';
    renderSceneBackgroundStatus();
    await applySceneBackgroundToObs().catch(() => {});
    setStatus(t('broadcast_room.scene_logo_cleared', 'Logo kaldırıldı.'));
}

async function updateSceneBackgroundPersonalization() {
    state.sceneBackground.fitMode = String(els.sceneBackgroundFitMode?.value || 'cover');
    state.sceneBackground.dimPercent = Math.max(0, Math.min(80, Math.round(Number(els.sceneBackgroundDimPercent?.value || 0))));
    state.sceneBackground.logoPosition = String(els.sceneLogoPosition?.value || 'top-right');
    state.sceneBackground.logoSize = String(els.sceneLogoSize?.value || 'medium');
    renderSceneBackgroundStatus();
    await applySceneBackgroundToObs().catch(() => {});
}

