const GUEST_HIDDEN_ROOM_SECTION_IDS = new Set([
    'scene_layout',
    'scene_background',
    'live_effects'
]);

function announce(message) {
    if (!els.liveRegion) {
        return;
    }
    els.liveRegion.textContent = '';
    requestAnimationFrame(() => {
        els.liveRegion.textContent = message;
    });
}

function setStatus(message) {
    if (els.statusLine) {
        els.statusLine.textContent = message;
    }
    announce(message);
}

function setPassiveStatus(message) {
    if (els.statusLine) {
        els.statusLine.textContent = message;
    }
}

function buildHostActivityStateKey(settings = {}) {
    return JSON.stringify({
        recording: settings.hostRecordingActive === true,
        sharing: settings.hostShareActive === true,
        label: String(settings.hostShareLabel || '')
    });
}

function buildHostActivityAnnouncement(previousSettings = {}, nextSettings = {}) {
    const hostName = String(nextSettings.hostDisplayName || state.roomSettings.hostDisplayName || getDefaultHostDisplayName() || '').trim()
        || t('broadcast_room.host_fallback', 'Host');
    const previousState = {
        recording: previousSettings.hostRecordingActive === true,
        sharing: previousSettings.hostShareActive === true
    };
    const nextState = {
        recording: nextSettings.hostRecordingActive === true,
        sharing: nextSettings.hostShareActive === true
    };
    const recordingStarted = previousState.recording !== true && nextState.recording === true;
    const sharingStarted = previousState.sharing !== true && nextState.sharing === true;
    const recordingStopped = previousState.recording === true && nextState.recording !== true;
    const sharingStopped = previousState.sharing === true && nextState.sharing !== true;

    if (recordingStarted && sharingStarted) {
        return t('broadcast_room.host_activity_recording_and_share_started_by', '{name} kayıt ve paylaşım başlattı.', { name: hostName });
    }
    if (sharingStarted) {
        return t('broadcast_room.host_activity_share_started_by', '{name} paylaşım başlattı.', { name: hostName });
    }
    if (recordingStarted) {
        return t('broadcast_room.host_activity_recording_started_by', '{name} kayıt başlattı.', { name: hostName });
    }
    if (recordingStopped && sharingStopped) {
        return t('broadcast_room.host_activity_recording_and_share_stopped_by', '{name} kaydı ve paylaşımı durdurdu.', { name: hostName });
    }
    if (sharingStopped) {
        return t('broadcast_room.host_activity_share_stopped_by', '{name} paylaşımı durdurdu.', { name: hostName });
    }
    if (recordingStopped) {
        return t('broadcast_room.host_activity_recording_stopped_by', '{name} kaydı durdurdu.', { name: hostName });
    }
    return '';
}

function announceGuestHostActivityChange(previousSettings = {}, nextSettings = {}) {
    if (isLocalRoomHost()) {
        state.lastGuestHostActivityKey = buildHostActivityStateKey(nextSettings);
        return;
    }
    const nextKey = buildHostActivityStateKey(nextSettings);
    if (!state.lastGuestHostActivityKey) {
        state.lastGuestHostActivityKey = nextKey;
        return;
    }
    if (state.lastGuestHostActivityKey === nextKey) {
        return;
    }
    const message = buildHostActivityAnnouncement(previousSettings, nextSettings);
    state.lastGuestHostActivityKey = nextKey;
    if (message) {
        setStatus(message);
        addDiagnosticEvent('room', message);
    }
}

function isTypingField(element) {
    if (!element || typeof element.closest !== 'function') {
        return false;
    }
    return !!element.closest('textarea, [contenteditable="true"], input:not([type="checkbox"]):not([type="radio"]):not([type="button"]):not([type="submit"])');
}

function getRoomSectionDefinition(sectionId) {
    return ROOM_SECTION_DEFINITIONS.find((section) => section.id === sectionId) || null;
}

function getAvailableRoomSections() {
    const isGuestMode = getLocalRoomRole() === 'guest';
    return ROOM_SECTION_DEFINITIONS.filter((section) => !isGuestMode || !GUEST_HIDDEN_ROOM_SECTION_IDS.has(section.id));
}

function getAvailableRoomSectionDefinition(sectionId) {
    return getAvailableRoomSections().find((section) => section.id === sectionId) || null;
}

function getRoomSectionLabel(section) {
    if (section?.id === 'youtube_stream' && getLocalRoomRole() === 'guest') {
        return t('recording_wizard.chat.title', 'Canlı Sohbet');
    }
    return t(section.labelKey, section.fallback);
}

function renderRoomSectionVisibility() {
    const availableSections = getAvailableRoomSections();
    const availableIds = new Set(availableSections.map((section) => section.id));
    document.querySelectorAll('[data-room-section-id]').forEach((sectionEl) => {
        const sectionId = String(sectionEl.getAttribute('data-room-section-id') || '').trim();
        sectionEl.hidden = sectionId ? !availableIds.has(sectionId) : false;
    });
    if (!getAvailableRoomSectionDefinition(state.selectedRoomSectionId)) {
        state.selectedRoomSectionId = availableSections[0]?.id || '';
    }
}

function focusElementOrContainer(target) {
    if (!target) {
        return;
    }
    if (typeof target.focus === 'function') {
        try {
            target.focus();
            return;
        } catch (_error) {
            // continue with container focus
        }
    }
    const previousTabIndex = target.getAttribute('tabindex');
    if (!target.hasAttribute('tabindex')) {
        target.setAttribute('tabindex', '-1');
    }
    target.focus?.();
    if (previousTabIndex === null) {
        const cleanup = () => {
            target.removeAttribute('tabindex');
            target.removeEventListener('blur', cleanup);
        };
        target.addEventListener('blur', cleanup, { once: true });
    }
}

function renderRoomSectionList() {
    if (!els.roomSectionList) {
        return;
    }
    renderRoomSectionVisibility();
    const availableSections = getAvailableRoomSections();
    const optionsMarkup = availableSections.map((section) => (
        `<option value="${escapeHtml(section.id)}">${escapeHtml(getRoomSectionLabel(section))}</option>`
    )).join('');
    if (els.roomSectionList.dataset.renderedOptions !== optionsMarkup) {
        els.roomSectionList.innerHTML = optionsMarkup;
        els.roomSectionList.dataset.renderedOptions = optionsMarkup;
    }
    const selectedId = getAvailableRoomSectionDefinition(state.selectedRoomSectionId)?.id || availableSections[0]?.id || '';
    state.selectedRoomSectionId = selectedId;
    els.roomSectionList.value = selectedId;
}

function updateSelectedRoomSectionFromFocus(target) {
    if (!target || typeof target.closest !== 'function') {
        return;
    }
    const sectionRoot = target.closest('[data-room-section-id]');
    const sectionId = String(sectionRoot?.getAttribute('data-room-section-id') || '').trim();
    if (!sectionId || !getAvailableRoomSectionDefinition(sectionId)) {
        return;
    }
    state.selectedRoomSectionId = sectionId;
    if (els.roomSectionList) {
        els.roomSectionList.value = sectionId;
    }
}

function focusRoomSection(sectionId, { announceFocus = true } = {}) {
    const availableSections = getAvailableRoomSections();
    const section = getAvailableRoomSectionDefinition(sectionId) || availableSections[0] || null;
    if (!section) {
        return;
    }
    state.selectedRoomSectionId = section.id;
    if (els.roomSectionList) {
        els.roomSectionList.value = section.id;
    }
    const focusTarget = document.querySelector(section.focusSelector);
    if (focusTarget) {
        focusElementOrContainer(focusTarget);
    }
    if (announceFocus) {
        setStatus(t('broadcast_room.section_focus_changed', '{name} bölgesine geçildi.', {
            name: getRoomSectionLabel(section)
        }));
    }
}

function focusRoomSectionList() {
    if (!els.roomSectionList) {
        return;
    }
    renderRoomSectionList();
    els.roomSectionList.focus();
    setStatus(t('broadcast_room.section_navigator_focused', 'Bölge listesi odaklandı.'));
}

function cycleRoomSection(direction) {
    const availableSections = getAvailableRoomSections();
    const total = availableSections.length;
    if (!total) {
        return;
    }
    const currentIndex = Math.max(0, availableSections.findIndex((section) => section.id === state.selectedRoomSectionId));
    const nextIndex = (currentIndex + direction + total) % total;
    focusRoomSection(availableSections[nextIndex].id);
}

function updateMediaActionButton(button, isEnabled, enabledLabelKey, enabledFallback, disabledLabelKey, disabledFallback) {
    if (!button) {
        return;
    }
    const enabled = Boolean(isEnabled);
    const label = enabled
        ? t(enabledLabelKey, enabledFallback)
        : t(disabledLabelKey, disabledFallback);
    button.checked = enabled;
    button.textContent = label;
    button.setAttribute('aria-label', label);
    button.removeAttribute('aria-pressed');
}

function updateHostMediaActionButtons() {
    const isMicrophoneOn = typeof els.hostMicrophoneEnabled?.checked === 'boolean' ? els.hostMicrophoneEnabled.checked : true;
    const isCameraOn = typeof els.hostCameraEnabled?.checked === 'boolean' ? els.hostCameraEnabled.checked : true;
    const prefix = getLocalRoomRole() === 'guest' ? 'guest' : 'host';
    updateMediaActionButton(
        els.hostMicrophoneEnabled,
        isMicrophoneOn,
        `broadcast_room.${prefix}_microphone_stop_button`,
        'Sesiniz açık, sesi kapat',
        `broadcast_room.${prefix}_microphone_start_button`,
        'Sesiniz kapalı, sesi aç'
    );
    updateMediaActionButton(
        els.hostCameraEnabled,
        isCameraOn,
        `broadcast_room.${prefix}_camera_stop_button`,
        'Videonuz açık, videoyu durdur',
        `broadcast_room.${prefix}_camera_start_button`,
        'Videonuz kapalı, videoyu başlat'
    );
}

function getLocalMediaToggleStatus(type, enabled) {
    if (type === 'camera') {
        return enabled
            ? t('broadcast_room.status_camera_enabled_self', 'Videonuz açıldı.')
            : t('broadcast_room.status_camera_disabled_self', 'Videonuz kapatıldı.');
    }
    return enabled
        ? t('broadcast_room.status_microphone_enabled_self', 'Sesiniz açıldı.')
        : t('broadcast_room.status_microphone_disabled_self', 'Sesiniz kapatıldı.');
}

async function setLocalCameraEnabled(enabled) {
    if (!els.hostCameraEnabled || els.hostCameraEnabled.disabled) {
        return;
    }
    const previous = !!els.hostCameraEnabled.checked;
    els.hostCameraEnabled.checked = !!enabled;
    updateHostMediaActionButtons();
    try {
        await syncHostLiveKitMedia();
        await updateOwnMediaState({ cameraEnabled: !!els.hostCameraEnabled.checked });
        setStatus(getLocalMediaToggleStatus('camera', !!els.hostCameraEnabled.checked));
    } catch (error) {
        els.hostCameraEnabled.checked = previous;
        updateHostMediaActionButtons();
        setStatus(t('broadcast_room.status_live_media_sync_failed', 'Canlı oda medyası güncellenemedi: {error}', { error: error.message }));
    }
}

async function setLocalMicrophoneEnabled(enabled) {
    if (!els.hostMicrophoneEnabled || els.hostMicrophoneEnabled.disabled) {
        return;
    }
    const previous = !!els.hostMicrophoneEnabled.checked;
    els.hostMicrophoneEnabled.checked = !!enabled;
    updateHostMediaActionButtons();
    try {
        await syncHostLiveKitMedia();
        await updateOwnMediaState({ microphoneEnabled: !!els.hostMicrophoneEnabled.checked });
        setStatus(getLocalMediaToggleStatus('microphone', !!els.hostMicrophoneEnabled.checked));
    } catch (error) {
        els.hostMicrophoneEnabled.checked = previous;
        updateHostMediaActionButtons();
        setStatus(t('broadcast_room.status_live_media_sync_failed', 'Canlı oda medyası güncellenemedi: {error}', { error: error.message }));
    }
}

