                { id: 'top-left', label: t('broadcast_room.slot_top_left', 'Sol üst'), acceptedTypes: ['camera', 'share', 'host-local-share'] },
                { id: 'top-center', label: t('broadcast_room.slot_top_center', 'Üst orta'), acceptedTypes: ['camera', 'share', 'host-local-share'] },
                { id: 'top-right', label: t('broadcast_room.slot_top_right', 'Sağ üst'), acceptedTypes: ['camera', 'share', 'host-local-share'] },
                { id: 'bottom-left', label: t('broadcast_room.slot_bottom_left', 'Sol alt'), acceptedTypes: ['camera', 'share', 'host-local-share'] },
                { id: 'bottom-center', label: t('broadcast_room.slot_bottom_center', 'Alt orta'), acceptedTypes: ['camera', 'share', 'host-local-share'] },
                { id: 'bottom-right', label: t('broadcast_room.slot_bottom_right', 'Sağ alt'), acceptedTypes: ['camera', 'share', 'host-local-share'] }
