function localInputToIso(value) {
    if (!value) return '';
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? '' : date.toISOString();
}

function getSelectedCameraLabel() {
    return state.audioDevices.cameras.find((item) => item.deviceId === state.audioDevices.selectedCameraId)?.label || '';
}

function getSelectedMicrophoneLabel() {
    return state.audioDevices.microphones.find((item) => item.deviceId === state.audioDevices.selectedMicrophoneId)?.label || '';
}

function getHostParticipant() {
    return state.participants.find((participant) => participant.role === 'host') || null;
}

function getSceneSlotLayoutRects(presetId, baseWidth, baseHeight) {
    const width = Math.max(1, Number(baseWidth) || 1920);
    const height = Math.max(1, Number(baseHeight) || 1080);
    const padding = Math.round(Math.min(width, height) * 0.02);
    const halfWidth = Math.floor(width / 2);
    const halfHeight = Math.floor(height / 2);
    const thirdWidth = Math.floor(width / 3);
    const pipWidth = Math.round(width * 0.28);
    const pipHeight = Math.round(height * 0.26);
    const stackedPipHeight = Math.round((height - (padding * 3)) / 2);
    const bottomStripHeight = Math.round(height * 0.24);
    const threePipWidth = Math.round((width - (padding * 4)) / 3);
    const fourPipWidth = Math.round((width - (padding * 5)) / 4);
    const bottomStripY = height - bottomStripHeight - padding;

    const fullRect = { x: 0, y: 0, width, height };
    const rectsByPreset = {
        'single-speaker': {
            main: fullRect
        },
        'two-up': {
            left: { x: 0, y: 0, width: halfWidth, height },
            right: { x: halfWidth, y: 0, width: width - halfWidth, height }
        },
        'four-grid': {
            'top-left': { x: 0, y: 0, width: halfWidth, height: halfHeight },
            'top-right': { x: halfWidth, y: 0, width: width - halfWidth, height: halfHeight },
            'bottom-left': { x: 0, y: halfHeight, width: halfWidth, height: height - halfHeight },
            'bottom-right': { x: halfWidth, y: halfHeight, width: width - halfWidth, height: height - halfHeight }
        },
        'six-gallery': {
            'top-left': { x: 0, y: 0, width: thirdWidth, height: halfHeight },
            'top-center': { x: thirdWidth, y: 0, width: thirdWidth, height: halfHeight },
            'top-right': { x: thirdWidth * 2, y: 0, width: width - (thirdWidth * 2), height: halfHeight },
            'bottom-left': { x: 0, y: halfHeight, width: thirdWidth, height: height - halfHeight },
            'bottom-center': { x: thirdWidth, y: halfHeight, width: thirdWidth, height: height - halfHeight },
            'bottom-right': { x: thirdWidth * 2, y: halfHeight, width: width - (thirdWidth * 2), height: height - halfHeight }
        },
        'screen-plus-speaker': {
            main: fullRect,
            'bottom-right': {
                x: width - pipWidth - padding,
                y: height - pipHeight - padding,
                width: pipWidth,
                height: pipHeight
            }
        },
        'screen-plus-two-speakers': {
            main: fullRect,
            'top-right': {
                x: width - pipWidth - padding,
                y: padding,
                width: pipWidth,
                height: stackedPipHeight
            },
            'bottom-right': {
                x: width - pipWidth - padding,
                y: height - stackedPipHeight - padding,
                width: pipWidth,
                height: stackedPipHeight
            }
        },
        'screen-plus-two-speakers-bottom': {
            main: fullRect,
            'bottom-left': {
                x: padding,
                y: bottomStripY,
                width: Math.round((width - (padding * 3)) / 2),
                height: bottomStripHeight
            },
            'bottom-right': {
                x: padding * 2 + Math.round((width - (padding * 3)) / 2),
                y: bottomStripY,
                width: width - (padding * 3) - Math.round((width - (padding * 3)) / 2),
                height: bottomStripHeight
            }
        },
        'screen-plus-three-speakers': {
            main: fullRect,
            'bottom-left': {
                x: padding,
                y: bottomStripY,
                width: threePipWidth,
                height: bottomStripHeight
            },
            'bottom-center': {
                x: padding * 2 + threePipWidth,
                y: bottomStripY,
                width: threePipWidth,
                height: bottomStripHeight
            },
            'bottom-right': {
                x: padding * 3 + (threePipWidth * 2),
                y: bottomStripY,
                width: width - (padding * 4) - (threePipWidth * 2),
                height: bottomStripHeight
            }
        },
        'screen-plus-four-speakers': {
            main: fullRect,
            'bottom-left': {
                x: padding,
                y: bottomStripY,
                width: fourPipWidth,
                height: bottomStripHeight
            },
            'bottom-center-left': {
                x: padding * 2 + fourPipWidth,
                y: bottomStripY,
                width: fourPipWidth,
                height: bottomStripHeight
            },
            'bottom-center-right': {
                x: padding * 3 + (fourPipWidth * 2),
                y: bottomStripY,
                width: fourPipWidth,
                height: bottomStripHeight
            },
            'bottom-right': {
                x: padding * 4 + (fourPipWidth * 3),
                y: bottomStripY,
                width: width - (padding * 5) - (fourPipWidth * 3),
                height: bottomStripHeight
            }
        }
    };

    return rectsByPreset[presetId] || { main: fullRect };
}

function getHostSceneObsAssignments() {
    const preset = getActiveScenePreset();
    const hostParticipant = getHostParticipant();
    const assignments = getActiveSceneAssignments();
    const availableLocalSourceIds = new Set(state.availableLocalShareSources.map((source) => source.id));

    if (!preset || !hostParticipant) {
        return {
            presetId: preset?.id || '',
            hostCameraSourceId: '',
            hostCameraSlotId: '',
            hostLocalShareSourceId: '',
            hostLocalShareSlotId: ''
        };
    }

    const hostCameraSourceId = `${hostParticipant.id}-camera`;
    const hostCameraSlotId = Object.entries(assignments).find(([, sourceId]) => sourceId === hostCameraSourceId)?.[0] || '';
    const hostLocalShareEntry = Object.entries(assignments).find(([, sourceId]) => availableLocalSourceIds.has(sourceId));

    return {
        presetId: preset.id,
        hostCameraSourceId,
        hostCameraSlotId,
        hostLocalShareSourceId: hostLocalShareEntry?.[1] || '',
        hostLocalShareSlotId: hostLocalShareEntry?.[0] || ''
    };
}

function hasAdvancedLayoutEligiblePreset() {
    return ['two-up', 'screen-plus-speaker', 'screen-plus-two-speakers', 'screen-plus-two-speakers-bottom'].includes(state.activeScenePresetId);
}

function hasHostCameraAndShareSceneAssignment() {
    const assignments = getHostSceneObsAssignments();
    return !!assignments.hostCameraSlotId && !!assignments.hostLocalShareSlotId;
}

function canUseAdvancedLayoutPanel() {
    return hasAdvancedLayoutEligiblePreset() && hasHostCameraAndShareSceneAssignment();
}

function getBroadcastAdvancedLayoutRects(width, height, mode, scalePercent, placement = getSelectedShareParticipantPlacement()) {
    const safeWidth = Math.max(1, Number(width) || 1);
    const safeHeight = Math.max(1, Number(height) || 1);
    const safeScale = Math.max(5, Math.min(95, Number(scalePercent) || (String(mode || '').includes('slide') ? 35 : 50)));
    if (placement === 'bottom') {
        const cameraHeight = Math.round(safeHeight * (safeScale / 100));
        const screenHeight = Math.max(1, safeHeight - cameraHeight);
        const isScreenTop = mode === 'side-l' || mode === 'side-l-slide';
        return {
            screenRect: {
                x: 0,
                y: isScreenTop ? 0 : cameraHeight,
                width: safeWidth,
                height: screenHeight
            },
            cameraRect: {
                x: 0,
                y: isScreenTop ? screenHeight : 0,
                width: safeWidth,
                height: cameraHeight
            }
        };
    }

    const cameraWidth = Math.round(safeWidth * (safeScale / 100));
    const screenWidth = Math.max(1, safeWidth - cameraWidth);
    const isScreenLeft = mode === 'side-l' || mode === 'side-l-slide';
    return {
        screenRect: {
            x: isScreenLeft ? 0 : cameraWidth,
            y: 0,
            width: screenWidth,
            height: safeHeight
        },
        cameraRect: {
            x: isScreenLeft ? screenWidth : 0,
            y: 0,
            width: cameraWidth,
            height: safeHeight
        }
    };
}

function getBroadcastLayoutModeLabel(mode) {
    const [key, fallback] = getBroadcastAdvancedLayoutDisplayKey(mode);
    return t(key, fallback);
}

function getSelectedBroadcastAdvancedLayoutMode() {
    const radio = (els.advancedLayoutPresetRadios || []).find((item) => item.checked);
    return radio ? radio.value : (state.broadcastLayout.mode || 'side-l-slide');
}

function getBroadcastAdvancedLayoutAllowedModes() {
    return ['side-l', 'side-r', 'side-l-slide', 'side-r-slide'];
}

function getBroadcastAdvancedLayoutDisplayKey(mode) {
    if (getSelectedShareParticipantPlacement() === 'bottom') {
        if (mode === 'side-l') {
            return ['broadcast_room.share_layout_top_bottom_even', 'Ekran üstte, katılımcılar altta'];
        }
        if (mode === 'side-r') {
            return ['broadcast_room.share_layout_bottom_top_even', 'Katılımcılar üstte, ekran altta'];
        }
        if (mode === 'side-l-slide') {
            return ['broadcast_room.share_layout_top_bottom_65_35', 'Ekran üstte %65, katılımcılar altta %35'];
        }
        if (mode === 'side-r-slide') {
            return ['broadcast_room.share_layout_bottom_top_35_65', 'Katılımcılar üstte %35, ekran altta %65'];
        }
    }
    const fallbackMap = {
        'side-l': ['recording_wizard.layout.side_l', 'Yan Yana (Ekran Sol / Kamera Sağ)'],
        'side-r': ['recording_wizard.layout.side_r', 'Yan Yana (Kamera Sol / Ekran Sağ)'],
        'side-l-slide': ['recording_wizard.layout.side_l_slide', 'Sunum Yanyana (Ekran Solda %65, Kamera Sağda %35) - Tablo/Grafik için'],
        'side-r-slide': ['recording_wizard.layout.side_r_slide', 'Sunum Yanyana (Kamera Solda %35, Ekran Sağda %65) - Tablo/Grafik için']
    };
    return fallbackMap[mode] || ['recording_wizard.layout.side_l_slide', mode || ''];
}

function refreshBroadcastAdvancedLayoutPresetOptions() {
    const allowedModes = getBroadcastAdvancedLayoutAllowedModes();
    (els.advancedLayoutPresetRadios || []).forEach((radio) => {
        const mode = String(radio.value || '');
        const isAllowed = allowedModes.includes(mode);
        const label = radio.closest?.('label') || null;
        if (label) {
            label.hidden = false;
        }
        radio.disabled = false;
        const [key, fallback] = getBroadcastAdvancedLayoutDisplayKey(mode);
        const labelText = t(key, fallback);
        const textEl = document.querySelector(`[data-broadcast-layout-label-for="${mode}"]`);
        if (textEl) {
            textEl.textContent = labelText;
            textEl.setAttribute('data-i18n', key);
        }
    });
}

function setSelectedBroadcastAdvancedLayoutMode(mode) {
    const radios = els.advancedLayoutPresetRadios || [];
    radios.forEach((radio) => {
        radio.checked = radio.value === mode;
    });
    state.broadcastLayout.mode = mode;
}

function computeDefaultBroadcastAdvancedLayoutMode() {
    const assignments = getHostSceneObsAssignments();
    if (state.activeScenePresetId === 'two-up') {
        return assignments.hostCameraSlotId === 'left' ? 'side-r' : 'side-l';
    }
    return assignments.hostCameraSlotId === 'main' ? 'side-r-slide' : 'side-l-slide';
}

function getDefaultBroadcastAdvancedLayoutScale(mode) {
    return String(mode && mode.includes('slide') ? 35 : 50);
}

function syncBroadcastAdvancedLayoutDefaults(force = false) {
    const nextMode = computeDefaultBroadcastAdvancedLayoutMode();
    const currentMode = getSelectedBroadcastAdvancedLayoutMode();
    if (force || !currentMode || !['side-l', 'side-r', 'side-l-slide', 'side-r-slide'].includes(currentMode)) {
        setSelectedBroadcastAdvancedLayoutMode(nextMode);
    } else if (!state.broadcastLayout.mode) {
        state.broadcastLayout.mode = currentMode;
    }

    if (els.broadcastCamScale && (!els.broadcastCamScale.value || force)) {
        els.broadcastCamScale.value = getDefaultBroadcastAdvancedLayoutScale(nextMode);
    }
    if (els.broadcastShareParticipantPlacement) {
        els.broadcastShareParticipantPlacement.value = state.broadcastLayout.participantPlacement === 'side' ? 'side' : 'bottom';
    }
    refreshBroadcastAdvancedLayoutPresetOptions();
}

function resetBroadcastAdvancedLayoutAiUi() {
    state.broadcastLayout.aiSuggestion = null;
    state.broadcastLayout.aiSuggestionPreviewBase64 = null;
    state.broadcastLayout.aiSuggestionResponseText = '';
    if (els.btnApplyAiAdvancedLayout) {
        els.btnApplyAiAdvancedLayout.disabled = true;
    }
    if (els.advancedLayoutAiFollowupQuestion) {
        els.advancedLayoutAiFollowupQuestion.value = '';
    }
    if (els.advancedLayoutAiFollowupPanel) {
        els.advancedLayoutAiFollowupPanel.style.display = 'none';
    }
    if (els.advancedLayoutAiFollowupStatus) {
        els.advancedLayoutAiFollowupStatus.textContent = t('recording_wizard.ai.followup_waiting', 'A follow-up question can be asked after an AI suggestion is created.');
    }
}

function buildBroadcastAiSuggestionPrompt(currentPreset, currentScale, selectedBgColorText, selectedPanelFillText, selectedParticipantPlacementText = '') {
    const bgLine = selectedBgColorText
        ? (isTurkishUi()
            ? `Kullanıcı konuşmacı arka planı olarak "${selectedBgColorText}" seçti.`
            : `The user selected "${selectedBgColorText}" for the speaker background.`)
        : '';
    const panelFillLine = selectedPanelFillText
        ? (isTurkishUi()
            ? `Kullanıcı yan yana boşluk dolgusu olarak "${selectedPanelFillText}" seçti. Siyah boşluk veya letterbox alanları bununla yeterince kapanmış mı kontrol et.`
            : `The user selected "${selectedPanelFillText}" as the side-by-side gap fill. Check whether it adequately covers black bars or letterbox areas.`)
        : (isTurkishUi()
            ? 'Yan yana düzende siyah boşluk, letterbox veya doldurulmamış panel alanı görüyorsan bunu belirt ve uygun bir boşluk dolgusu öner.'
            : 'If you see black bars, letterboxing, or unfilled panel space in a side-by-side layout, mention it and recommend an appropriate gap fill.');
    return [
        isTurkishUi()
            ? 'Sen bir video düzenleme yardımcısısın. Yayın odasındaki ekran ve konuşmacı yerleşimi için en iyi oranı öner.'
            : 'You are a video production assistant. Recommend the best ratio for the screen and speaker layout in a broadcast room.',
        `${isTurkishUi() ? 'Kullanıcının seçtiği düzen' : 'The selected layout'}: ${currentPreset}. (${isTurkishUi() ? 'Konuşmacı alanı ölçeği' : 'Speaker area scale'}: %${currentScale})`,
        selectedParticipantPlacementText
            ? `${isTurkishUi() ? 'Katılımcı konumu' : 'Participant placement'}: ${selectedParticipantPlacementText}`
            : '',
        isTurkishUi()
            ? 'Gerekirse 50/50 ile 65/35 arasında daha uygun bir düzen öner. Yanıtı JSON ver.'
            : 'If needed, recommend a better layout between 50/50 and 65/35. Return JSON.',
        bgLine,
        panelFillLine,
        '{',
        '  "preset": "side-l-slide",',
        '  "camera": { "scalePercent": 35 },',
        '  "panelFillColor": "none",',
        '  "reason": "kisa aciklama"',
        '}'
    ].filter(Boolean).join('\n');
}

function buildBroadcastAiDescriptionPrompt(currentPreset, currentScale, selectedBgColorText, selectedPanelFillText) {
    const bgLine = selectedBgColorText
        ? (isTurkishUi()
            ? `- Kullanıcı konuşmacı arka planı olarak "${selectedBgColorText}" seçti.`
            : `- The user selected "${selectedBgColorText}" for the speaker background.`)
        : '';
    const panelFillLine = selectedPanelFillText
        ? (isTurkishUi()
            ? `- Kullanıcı yan yana boşluk dolgusu olarak "${selectedPanelFillText}" seçti. Kenarlarda siyah boşluk kalıp kalmadığını değerlendir.`
            : `- The user selected "${selectedPanelFillText}" as the side-by-side gap fill. Evaluate whether black gaps remain.`)
        : '';
    return [
        isTurkishUi()
            ? 'Kısa ve erişilebilir bir betimleme yap:'
            : 'Create a short accessible description:',
        isTurkishUi()
            ? '- Ekran paylaşımı ve konuşmacı dengeli mi?'
            : '- Is the screen share and speaker balanced?',
        isTurkishUi()
            ? `- Kullanıcı "${currentPreset}" düzeninde konuşmacıyı %${currentScale} oranında ayarladı.`
            : `- The user set the speaker area to ${currentScale}% in the "${currentPreset}" layout.`,
        bgLine,
        panelFillLine,
        isTurkishUi()
            ? '- Metinler okunaklı mı, konuşmacı yüzü yeterince büyük mü, siyah boşluk var mı?'
            : '- Are texts readable, is the speaker face large enough, and are there black gaps?',
        isTurkishUi()
            ? 'Maksimum 4-5 kısa cümle.'
            : 'Maximum 4-5 short sentences.'
    ].filter(Boolean).join('\n');
}

function buildLivePreviewAiReviewPrompt() {
    const presetLabel = getActiveScenePreset()?.label || t('broadcast_room.value_not_available', 'Hazır değil');
    const hostName = String(state.roomSettings.hostDisplayName || getDefaultHostDisplayName() || '').trim();
    const activeShares = state.participantSources.filter((source) => String(source?.sceneType || '') === 'guestShare');
    return [
        isTurkishUi()
            ? 'Sen erişilebilir yayın düzeni değerlendirmesi yapan bir yardımcı uzmansın.'
            : 'You are an assistant specialized in evaluating accessible broadcast layouts.',
        isTurkishUi()
            ? 'Tek bir gerçek yayın karesine bakarak kısa ve net değerlendirme ver.'
            : 'Look at a single real broadcast frame and provide a short, clear evaluation.',
        `${isTurkishUi() ? 'Aktif sahne düzeni' : 'Active scene layout'}: ${presetLabel}.`,
        `${isTurkishUi() ? 'Host adı' : 'Host name'}: ${hostName || (isTurkishUi() ? 'belirtilmedi' : 'not specified')}.`,
        `${isTurkishUi() ? 'Etkin konuk paylaşımı sayısı' : 'Active guest share count'}: ${activeShares.length}.`,
        isTurkishUi()
            ? 'Şunları değerlendir: 1) Host ve görünen konuk yüzleri gerçekten seçilebilir mi? 2) Ekran paylaşımı varsa paylaşım ile yüzler seçili düzene uygun mu? 3) Yüzler çok küçük, kesilmiş, gizlenmiş veya yanlış yerde mi? 4) Ekstra yanlış görünen bir kontrol, siyah boşluk, istenmeyen öğe veya dengesizlik var mı? 5) Gerekirse tek cümlelik bir düzen önerisi ver.'
            : 'Evaluate these points: 1) Are the host and visible guest faces actually discernible? 2) If there is screen sharing, is the balance between the share and faces appropriate for the selected layout? 3) Are faces too small, cropped, hidden, or misplaced? 4) Are there any extra controls, black gaps, unwanted elements, or visual imbalances? 5) If needed, give one short layout recommendation.',
        isTurkishUi()
            ? 'Yanıtı en fazla 6 kısa cümleyle ver. Önce genel sonuç, sonra sorunlar ve öneri gelsin.'
            : 'Answer in at most 6 short sentences. Start with the overall result, then mention issues and a recommendation.'
    ].join('\n');
}

function isRetryableAiReviewError(errorText = '') {
    const normalized = String(errorText || '').toLowerCase();
    return normalized.includes('high demand')
        || normalized.includes('try again later')
        || normalized.includes('rate limit')
        || normalized.includes('resource exhausted')
        || normalized.includes('temporarily unavailable')
        || normalized.includes('unavailable')
        || normalized.includes('quota')
        || normalized.includes('429')
        || normalized.includes('503')
        || normalized.includes('timeout')
        || normalized.includes('zaman aşımı');
}

async function requestLivePreviewAiReview() {
    if (els.aiLivePreviewStatus) {
        els.aiLivePreviewStatus.textContent = t('broadcast_room.ai_live_preview_preparing', 'Canlı önizleme yapay zeka değerlendirmesi hazırlanıyor...');
    }
    announce(t('broadcast_room.ai_live_preview_preparing', 'Canlı önizleme yapay zeka değerlendirmesi hazırlanıyor...'));

    const gemini = await ipcRenderer.invoke('get-gemini-api-data');
    const openAi = await ipcRenderer.invoke('get-openai-api-data').catch(() => ({}));
    if ((!gemini || !gemini.apiKey) && !openAi?.apiKey) {
        if (els.aiLivePreviewStatus) {
            els.aiLivePreviewStatus.textContent = t('recording_wizard.ai.gemini_key_missing', 'Gemini API key was not found.');
        }
        announce(t('recording_wizard.ai.gemini_key_missing', 'Gemini API key was not found.'));
        return;
    }

    const base64 = await getBroadcastSceneTrackPreviewBase64()
        || await getBroadcastStageOutputPreviewBase64()
        || await getBroadcastObsPreviewBase64();
    if (!base64) {
        if (els.aiLivePreviewStatus) {
            els.aiLivePreviewStatus.textContent = t('recording_wizard.ai.preview_unavailable', 'Preview could not be captured. OBS screenshot or desktop sources were not accessible.');
        }
        announce(t('recording_wizard.ai.preview_failed', 'Preview could not be captured.'));
        return;
    }

    const prompt = buildLivePreviewAiReviewPrompt();
    const systemInstruction = t('runtime.dialogs.ai_system_instruction', 'Respond only in {lang}. Keep the same response language in follow-up answers.', {
        lang: isTurkishUi() ? 'Turkish' : 'English'
    });
    let resp = null;
    let usedFallback = false;

    if (gemini?.apiKey) {
        resp = await ipcRenderer.invoke('gemini-vision-request', {
            apiKey: gemini.apiKey,
            model: gemini.model || 'gemini-2.5-flash',
            imageBase64: base64,
            prompt,
            history: [],
            systemInstruction
        });
    }

    if ((!resp || !resp.success) && openAi?.apiKey && (!gemini?.apiKey || isRetryableAiReviewError(resp?.error))) {
        usedFallback = !!gemini?.apiKey;
        resp = await ipcRenderer.invoke('openai-vision-request', {
            imageBase64: base64,
            prompt,
            systemInstruction,
            model: 'gpt-4.1-mini'
        });
    }

    if (!resp || !resp.success) {
        if (els.aiLivePreviewStatus) {
            els.aiLivePreviewStatus.textContent = t('recording_wizard.ai.request_failed', 'AI error: {error}', {
                error: resp?.error || t('recording_wizard.unknown_error', 'Unknown error')
            });
        }
        announce(t('recording_wizard.ai.request_failed_announce', 'An AI error occurred.'));
        return;
    }

    const text = String(resp.text || '').trim();
    const finalText = text
        ? (usedFallback
            ? `${t('broadcast_room.ai_live_preview_openai_fallback_used', 'Gemini yanıt veremedi; değerlendirme OpenAI yedek servisiyle alındı.')}\n${text}`
            : text)
        : t('recording_wizard.ai.description_missing', 'Description could not be generated.');
    if (els.aiLivePreviewStatus) {
        els.aiLivePreviewStatus.textContent = finalText;
    }
    announce(finalText);
}

async function getBroadcastSceneTrackPreviewBase64() {
    const preset = getActiveScenePreset();
    if (!preset) {
        return null;
    }
    const canvas = document.createElement('canvas');
    canvas.width = 1280;
    canvas.height = 720;
    const ctx = canvas.getContext('2d');
    if (!ctx) {
        return null;
    }
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const rects = getSceneSlotLayoutRects(preset.id, canvas.width, canvas.height);
    let drawnVideoCount = 0;
    const tempVideos = [];
    try {
        const slotEntries = (preset.slots || [])
            .map((slot) => {
                const assignedState = getAssignedSceneSourceState(slot.id, preset.id);
                const stageTrack = getSceneSourceStageTrack(assignedState.source);
                return {
                    slot,
                    rect: rects[slot.id] || null,
                    stageTrack
                };
            })
            .filter((entry) => entry.rect && entry.stageTrack?.track);

        if (!slotEntries.length && state.liveRoom.localVideoTrack) {
            slotEntries.push({
                slot: { id: 'main' },
                rect: { x: 0, y: 0, width: canvas.width, height: canvas.height },
                stageTrack: {
                    track: state.liveRoom.localVideoTrack,
                    isShare: false,
                    label: getDefaultHostDisplayName()
                }
            });
        }

        for (const entry of slotEntries) {
            const video = document.createElement('video');
            video.muted = true;
            video.defaultMuted = true;
            video.playsInline = true;
            video.autoplay = true;
            video.style.position = 'fixed';
            video.style.left = '-10000px';
            video.style.top = '-10000px';
            video.style.width = `${Math.max(1, Math.round(entry.rect.width))}px`;
            video.style.height = `${Math.max(1, Math.round(entry.rect.height))}px`;
            video.style.objectFit = entry.stageTrack.isShare ? 'contain' : 'cover';
            document.body.appendChild(video);
            tempVideos.push(video);
            safelyAttachTrackToElement(entry.stageTrack.track, video);
            const ready = await waitForAiPreviewVideoReady(video);
            if (!ready) {
                logBroadcastRoomDebug('ai-live-preview-scene-track-video-not-ready', {
                    slotId: entry.slot.id,
                    label: entry.stageTrack.label || '',
                    videoWidth: Number(video.videoWidth || 0),
                    videoHeight: Number(video.videoHeight || 0)
                });
                continue;
            }
            const drawn = drawVideoIntoCanvasContext(ctx, video, entry.rect, entry.rect);
            if (drawn) {
                drawnVideoCount += 1;
            }
        }
    } finally {
        tempVideos.forEach((video) => {
            clearAttachedMediaElement(video);
            video.remove();
        });
    }

    if (!drawnVideoCount) {
        logBroadcastRoomDebug('ai-live-preview-scene-track-empty', {
            presetId: preset.id,
            slotCount: (preset.slots || []).length,
            hasHostVideoTrack: !!state.liveRoom.localVideoTrack
        });
        return null;
    }

    const dataUrl = canvas.toDataURL('image/png');
    await saveAiLivePreviewDiagnosticFrame(dataUrl, 'scene_tracks');
    logBroadcastRoomDebug('ai-live-preview-scene-track-captured', {
        presetId: preset.id,
        drawnVideoCount,
        width: canvas.width,
        height: canvas.height
    });
    return dataUrl.includes('base64,') ? dataUrl.split('base64,')[1] : dataUrl;
}

async function waitForAiPreviewVideoReady(video) {
    const startedAt = Date.now();
    while (Date.now() - startedAt < 2400) {
        if (Number(video?.videoWidth || 0) > 0 && Number(video?.videoHeight || 0) > 0) {
            await new Promise((resolve) => setTimeout(resolve, 120));
            return true;
        }
        if (typeof video?.play === 'function') {
            video.play().catch(() => {});
        }
        await new Promise((resolve) => setTimeout(resolve, 80));
    }
    return Number(video?.videoWidth || 0) > 0 && Number(video?.videoHeight || 0) > 0;
}

async function getBroadcastStageOutputPreviewBase64() {
    try {
        await ensureStageOutputWindow({ focus: false });
        await syncStageOutputWindowMedia().catch(() => {});
        await waitForStageOutputWindowReadyForObsCapture({
            audioExpected: false,
            visualExpected: true,
            timeoutMs: 3600
        });
        await syncStageOutputWindowMedia().catch(() => {});
        const windowCaptureBase64 = await getBroadcastStageOutputWindowCaptureBase64();
        if (windowCaptureBase64) {
            return windowCaptureBase64;
        }
        const canvas = document.createElement('canvas');
        const drawnVideoCount = drawStageOutputFrameToCanvas(canvas);
        if (!drawnVideoCount || !canvas.width || !canvas.height) {
            logBroadcastRoomDebug('ai-live-preview-stage-output-empty', {
                drawnVideoCount: drawnVideoCount || 0,
                width: canvas.width || 0,
                height: canvas.height || 0
            });
            return null;
        }
        const dataUrl = canvas.toDataURL('image/png');
        saveAiLivePreviewDiagnosticFrame(dataUrl, 'canvas').catch(() => {});
        logBroadcastRoomDebug('ai-live-preview-stage-output-captured', {
            drawnVideoCount,
            width: canvas.width,
            height: canvas.height
        });
        return dataUrl.includes('base64,') ? dataUrl.split('base64,')[1] : dataUrl;
    } catch (error) {
        logBroadcastRoomDebug('ai-live-preview-stage-output-capture-failed', {
            error: error?.message || String(error || '')
        });
        return null;
    }
}

async function getBroadcastStageOutputWindowCaptureBase64() {
    let stream = null;
    let video = null;
    try {
        const source = await getStageOutputDesktopSource();
        if (!source?.id) {
            return null;
        }
        stream = await navigator.mediaDevices.getUserMedia({
            audio: false,
            video: {
                mandatory: {
                    chromeMediaSource: 'desktop',
                    chromeMediaSourceId: source.id,
                    minWidth: 1280,
                    maxWidth: 1920,
                    minHeight: 720,
                    maxHeight: 1080,
                    maxFrameRate: 5
                }
            }
        });
        video = document.createElement('video');
        video.muted = true;
        video.playsInline = true;
        video.srcObject = stream;
        await new Promise((resolve, reject) => {
            const timeout = setTimeout(() => reject(new Error('stage_output_window_capture_timeout')), 2200);
            video.onloadedmetadata = () => {
                video.play()
                    .then(() => {
                        clearTimeout(timeout);
                        resolve();
                    })
                    .catch((error) => {
                        clearTimeout(timeout);
                        reject(error);
                    });
            };
            video.onerror = () => {
                clearTimeout(timeout);
                reject(new Error('stage_output_window_capture_video_error'));
            };
        });
        await new Promise((resolve) => setTimeout(resolve, 250));
        const width = Number(video.videoWidth || 0);
        const height = Number(video.videoHeight || 0);
        if (!width || !height) {
            return null;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width % 2 === 0 ? width : width - 1;
        canvas.height = height % 2 === 0 ? height : height - 1;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return null;
        }
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/png');
        saveAiLivePreviewDiagnosticFrame(dataUrl, 'window').catch(() => {});
        logBroadcastRoomDebug('ai-live-preview-stage-window-captured', {
            sourceId: source.id,
            sourceName: source.name || '',
            width: canvas.width,
            height: canvas.height
        });
        return dataUrl.includes('base64,') ? dataUrl.split('base64,')[1] : dataUrl;
    } catch (error) {
        logBroadcastRoomDebug('ai-live-preview-stage-window-capture-failed', {
            error: error?.message || String(error || '')
        });
        return null;
    } finally {
        if (video) {
            video.pause?.();
            video.srcObject = null;
        }
        stream?.getTracks?.().forEach((track) => track.stop());
    }
}

async function saveAiLivePreviewDiagnosticFrame(dataUrl, method) {
    if (!dataUrl) {
        return;
    }
    const stamp = new Date().toISOString()
        .replace(/[:T]/g, '-')
        .replace(/\..+$/, '');
    const result = await ipcRenderer.invoke('save-base64-image', {
        base64Data: dataUrl,
        filename: `evd-ai-live-preview-${method || 'capture'}-${stamp}.png`
    }).catch(() => null);
    if (result?.success && result.filePath) {
        addDiagnosticEvent('broadcast', t('broadcast_room.status_ai_live_preview_frame_saved', 'AI önizleme tanı karesi kaydedildi ({method}): {path}', {
            method: getAiLivePreviewCaptureMethodLabel(method),
            path: result.filePath
        }));
        logBroadcastRoomDebug('ai-live-preview-diagnostic-frame-saved', {
            method: method || '',
            path: result.filePath
        });
    }
}

function getAiLivePreviewCaptureMethodLabel(method) {
    switch (String(method || '')) {
        case 'window':
            return t('broadcast_room.ai_live_preview_capture_method_window', 'temiz yayın penceresi');
        case 'canvas':
            return t('broadcast_room.ai_live_preview_capture_method_canvas', 'temiz yayın kanvası');
        case 'obs_composed':
            return t('broadcast_room.ai_live_preview_capture_method_obs_composed', 'OBS kaynak birleşimi');
        case 'obs_scene':
            return t('broadcast_room.ai_live_preview_capture_method_obs_scene', 'OBS sahnesi');
        case 'obs_source':
            return t('broadcast_room.ai_live_preview_capture_method_obs_source', 'OBS kaynak görüntüsü');
        default:
            return t('broadcast_room.ai_live_preview_capture_method_unknown', 'bilinmeyen yöntem');
    }
}

async function getBroadcastObsPreviewBase64() {
    const obsReady = await ensureObsReadyForRecording();
    if (!obsReady) {
        return null;
    }

    try {
        await ensureObsSceneForBroadcastRoom({ useSeparateRemoteAudioCapture: true });
    } catch (error) {
        console.error('Broadcast room OBS preview scene prepare error:', error);
        return null;
    }

    await new Promise((resolve) => setTimeout(resolve, 350));

    const screenshotToDataUrl = (result) => {
        if (!result?.success || !result.imageData) {
            return null;
        }
        return result.imageData.startsWith('data:')
            ? result.imageData
            : `data:image/png;base64,${result.imageData}`;
    };

    const loadImageFromDataUrl = (dataUrl) => new Promise((resolve, reject) => {
        const image = new Image();
        image.onload = () => resolve(image);
        image.onerror = reject;
        image.src = dataUrl;
    });

    const composePreviewFromSources = async () => {
        if (!state.obsSceneItems.screenInputName || !state.obsSceneItems.cameraInputName) {
            return null;
        }

        const screenShot = await ipcRenderer.invoke('obs-get-source-screenshot', {
            sourceName: state.obsSceneItems.screenInputName,
            width: 1280,
            height: 720,
            format: 'png'
        });
        const cameraShot = await ipcRenderer.invoke('obs-get-source-screenshot', {
            sourceName: state.obsSceneItems.cameraInputName,
            width: 640,
            height: 720,
            format: 'png'
        });

        const screenDataUrl = screenshotToDataUrl(screenShot);
        const cameraDataUrl = screenshotToDataUrl(cameraShot);
        if (!screenDataUrl || !cameraDataUrl) {
            return null;
        }

        const [screenImage, cameraImage] = await Promise.all([
            loadImageFromDataUrl(screenDataUrl),
            loadImageFromDataUrl(cameraDataUrl)
        ]);

        const canvas = document.createElement('canvas');
        canvas.width = 1280;
        canvas.height = 720;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            return null;
        }

        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        let screenRect = null;
        let cameraRect = null;
        if (canUseAdvancedLayoutPanel()) {
            const mode = getSelectedBroadcastAdvancedLayoutMode();
            const scalePercent = Math.max(5, Math.min(95, parseInt(els.broadcastCamScale?.value, 10) || (mode.includes('slide') ? 35 : 50)));
            const rects = getBroadcastAdvancedLayoutRects(canvas.width, canvas.height, mode, scalePercent);
            screenRect = rects.screenRect;
            cameraRect = rects.cameraRect;
        } else {
            const obsAssignments = getHostSceneObsAssignments();
            const slotRects = getSceneSlotLayoutRects(obsAssignments.presetId, canvas.width, canvas.height);
            screenRect = obsAssignments.hostLocalShareSlotId ? slotRects[obsAssignments.hostLocalShareSlotId] : null;
            cameraRect = obsAssignments.hostCameraSlotId ? slotRects[obsAssignments.hostCameraSlotId] : null;
        }

        if (!screenRect || !cameraRect) {
            return null;
        }

        ctx.drawImage(screenImage, screenRect.x, screenRect.y, screenRect.width, screenRect.height);
        ctx.drawImage(cameraImage, cameraRect.x, cameraRect.y, cameraRect.width, cameraRect.height);
        return canvas.toDataURL('image/png').split(',')[1];
    };

    try {
        const composedPreview = await composePreviewFromSources();
        if (composedPreview) {
            await saveAiLivePreviewDiagnosticFrame(composedPreview, 'obs_composed');
            return composedPreview;
        }
    } catch (error) {
        console.error('Broadcast room OBS preview compose error:', error);
    }

    const sceneShot = await ipcRenderer.invoke('obs-get-source-screenshot', {
        sourceName: BROADCAST_ROOM_SCENE_NAME,
        width: 1280,
        height: 720,
        format: 'png'
    });
    if (sceneShot && sceneShot.success && sceneShot.imageData) {
        await saveAiLivePreviewDiagnosticFrame(sceneShot.imageData, 'obs_scene');
        return sceneShot.imageData.includes('base64,') ? sceneShot.imageData.split('base64,')[1] : sceneShot.imageData;
    }

    if (state.obsSceneItems.screenInputName) {
        const sourceShot = await ipcRenderer.invoke('obs-get-source-screenshot', {
            sourceName: state.obsSceneItems.screenInputName,
            width: 1280,
            height: 720,
            format: 'png'
        });
        if (sourceShot && sourceShot.success && sourceShot.imageData) {
            await saveAiLivePreviewDiagnosticFrame(sourceShot.imageData, 'obs_source');
            return sourceShot.imageData.includes('base64,') ? sourceShot.imageData.split('base64,')[1] : sourceShot.imageData;
        }
    }
    return null;
}

function renderAdvancedLayoutPanelState() {
    const shouldShowToggle = true;
    refreshBroadcastAdvancedLayoutPresetOptions();
    if (els.btnToggleAdvancedLayout) {
        els.btnToggleAdvancedLayout.hidden = !shouldShowToggle;
        els.btnToggleAdvancedLayout.setAttribute('aria-expanded', state.broadcastLayout.expanded ? 'true' : 'false');
    }
    if (els.advancedLayoutPanel) {
        els.advancedLayoutPanel.hidden = !shouldShowToggle || !state.broadcastLayout.expanded;
    }
    const enabled = canUseAdvancedLayoutPanel();
    [
        els.broadcastShareParticipantPlacement,
        els.broadcastCamScale,
        els.broadcastCamBgColor,
        els.broadcastCamPanelFillColor
    ].forEach((item) => {
        if (item) {
            item.disabled = false;
        }
    });
    [
        els.btnApplyAdvancedLayout,
        els.btnAiSuggestAdvancedLayout,
        els.btnAiDescribeAdvancedLayout,
        els.btnAiFollowupAdvancedLayout
    ].forEach((item) => {
        if (item) {
            item.disabled = !enabled;
        }
    });
    (els.advancedLayoutPresetRadios || []).forEach((radio) => {
        radio.disabled = false;
    });
    if (els.btnApplyAiAdvancedLayout) {
        els.btnApplyAiAdvancedLayout.disabled = !enabled || !state.broadcastLayout.aiSuggestion;
    }
    if (els.advancedLayoutAiStatus && !enabled) {
        els.advancedLayoutAiStatus.textContent = t('broadcast_room.advanced_layout_share_pending', 'Paylaşım düzeni hazır. Uygula ve AI araçları, host kamerası ile paylaşım birlikte sahneye geldiğinde etkinleşir.');
    } else if (els.advancedLayoutAiStatus && enabled && (!state.broadcastLayout.aiSuggestion && !els.advancedLayoutAiStatus.textContent)) {
        els.advancedLayoutAiStatus.textContent = t('recording_wizard.step4.ai_waiting', 'AI önerisi bekleniyor.');
    }
}

function relocateAdvancedLayoutControlsToSharePanel() {
    const toolbar = els.btnToggleAdvancedLayout?.closest?.('.toolbar') || null;
    const behaviorContainer = els.hostShareSceneBehavior?.closest?.('div') || null;
    if (!els.hostSharePanel || !toolbar || !els.advancedLayoutPanel || !behaviorContainer) {
        return;
    }
    if (toolbar.parentElement === els.hostSharePanel) {
        return;
    }
    behaviorContainer.insertAdjacentElement('afterend', toolbar);
    toolbar.insertAdjacentElement('afterend', els.advancedLayoutPanel);
}

function getPreferredHostShareSource() {
    const activeShares = buildHostActiveShareSources();
    if (activeShares.length > 0) {
        const selectedActiveShare = activeShares.find((source) => source.id === state.selectedHostShareSourceId);
        return selectedActiveShare || activeShares[0];
    }

    const obsAssignments = getHostSceneObsAssignments();
    if (obsAssignments.hostLocalShareSourceId) {
        const assignedSource = state.availableLocalShareSources.find((source) => source.id === obsAssignments.hostLocalShareSourceId);
        if (assignedSource) {
            return assignedSource;
        }
    }

    const assignments = getActiveSceneAssignments();
    const assignedSourceId = Object.values(assignments).find((sourceId) => {
        return state.availableLocalShareSources.some((source) => source.id === sourceId);
    });

    if (assignedSourceId) {
        return state.availableLocalShareSources.find((source) => source.id === assignedSourceId) || null;
    }

    return null;
}

async function applyBroadcastAdvancedLayoutFromControls(options = {}) {
    const { skipEnsureScene = false } = options;
    if (!canUseAdvancedLayoutPanel()) {
        setStatus(t('broadcast_room.advanced_layout_unavailable', 'Bu panel için host kamerasını ve host paylaşımını sahneye birlikte atayın.'));
        return false;
    }

    if (!skipEnsureScene) {
        const obsReady = await ensureObsReadyForRecording();
        if (!obsReady) {
            return false;
        }
        await ensureObsSceneForBroadcastRoom({ skipAdvancedLayout: true });
    }

    const cameraItemId = state.obsSceneItems.cameraItemId;
    const screenItemId = state.obsSceneItems.screenItemId;
    if (!cameraItemId || !screenItemId) {
        setStatus(t('broadcast_room.obs_scene_source_required', 'Yayın için en az bir görsel kaynak gerekli. Host kamerasını açın veya bir yerel paylaşım başlatın.'));
        return false;
    }

    const videoSettings = await ipcRenderer.invoke('obs-get-video-settings');
    const baseWidth = videoSettings?.success ? (videoSettings.baseWidth || 1920) : 1920;
    const baseHeight = videoSettings?.success ? (videoSettings.baseHeight || 1080) : 1080;
    const mode = getSelectedBroadcastAdvancedLayoutMode();
    const scalePercent = Math.max(5, Math.min(95, parseInt(els.broadcastCamScale?.value, 10) || (mode.includes('slide') ? 35 : 50)));
    const { screenRect, cameraRect } = getBroadcastAdvancedLayoutRects(baseWidth, baseHeight, mode, scalePercent);

    await ipcRenderer.invoke('obs-set-transform', {
        sceneName: BROADCAST_ROOM_SCENE_NAME,
        sceneItemId: screenItemId,
        transform: {
            positionX: screenRect.x,
            positionY: screenRect.y,
            boundsType: 'OBS_BOUNDS_SCALE_INNER',
            boundsWidth: screenRect.width,
            boundsHeight: screenRect.height,
            alignment: 5
        }
    });

    await ipcRenderer.invoke('obs-set-transform', {
        sceneName: BROADCAST_ROOM_SCENE_NAME,
        sceneItemId: cameraItemId,
        transform: {
            positionX: cameraRect.x,
            positionY: cameraRect.y,
            scaleX: 1,
            scaleY: 1,
            boundsType: 'OBS_BOUNDS_SCALE_INNER',
            boundsWidth: cameraRect.width,
            boundsHeight: cameraRect.height,
            alignment: 5
        }
    });

    await ipcRenderer.invoke('obs-set-camera-panel-fill', {
        sceneName: BROADCAST_ROOM_SCENE_NAME,
        cameraItemId,
        colorName: els.broadcastCamPanelFillColor?.value || 'none'
    });
    await ipcRenderer.invoke('obs-set-camera-background', {
        sceneName: BROADCAST_ROOM_SCENE_NAME,
        cameraItemId,
        colorName: els.broadcastCamBgColor?.value || 'none'
    });

    setStatus(t('recording_wizard.layout.applying_announce', 'Applying layout: {layout}', {
        layout: getBroadcastLayoutModeLabel(mode)
    }));
    return true;
}

async function requestBroadcastAdvancedLayoutAiSuggestion() {
    if (els.advancedLayoutAiStatus) {
        els.advancedLayoutAiStatus.textContent = t('recording_wizard.ai.suggestion_preparing', 'Preparing AI suggestion...');
    }
    announce(t('recording_wizard.ai.suggestion_preparing_announce', 'Preparing AI suggestion.'));
    resetBroadcastAdvancedLayoutAiUi();

    const gemini = await ipcRenderer.invoke('get-gemini-api-data');
    if (!gemini || !gemini.apiKey) {
        if (els.advancedLayoutAiStatus) {
            els.advancedLayoutAiStatus.textContent = t('recording_wizard.ai.gemini_key_missing', 'Gemini API key was not found.');
        }
        announce(t('recording_wizard.ai.gemini_key_missing', 'Gemini API key was not found.'));
        return;
    }

    const base64 = await getBroadcastObsPreviewBase64();
    if (!base64) {
        if (els.advancedLayoutAiStatus) {
            els.advancedLayoutAiStatus.textContent = t('recording_wizard.ai.preview_unavailable', 'Preview could not be captured. OBS screenshot or desktop sources were not accessible.');
        }
        announce(t('recording_wizard.ai.preview_failed', 'Preview could not be captured.'));
        return;
    }

    const prompt = buildBroadcastAiSuggestionPrompt(
        getBroadcastLayoutModeLabel(getSelectedBroadcastAdvancedLayoutMode()),
        els.broadcastCamScale?.value || '35',
        getSelectedOptionText(els.broadcastCamBgColor),
        getSelectedOptionText(els.broadcastCamPanelFillColor),
        getSelectedOptionText(els.broadcastShareParticipantPlacement)
    );

    const resp = await ipcRenderer.invoke('gemini-vision-request', {
        apiKey: gemini.apiKey,
        model: gemini.model || 'gemini-2.5-flash',
        imageBase64: base64,
        prompt,
        history: [],
        systemInstruction: t('runtime.dialogs.ai_system_instruction_json', 'Respond only in {lang}. If JSON output is requested, keep all JSON keys and schema exactly as requested while writing any free text values in {lang}.', {
            lang: isTurkishUi() ? 'Turkish' : 'English'
        })
    });

    if (!resp || !resp.success) {
        if (els.advancedLayoutAiStatus) {
            els.advancedLayoutAiStatus.textContent = t('recording_wizard.ai.request_failed', 'AI error: {error}', {
                error: resp?.error || t('recording_wizard.unknown_error', 'Unknown error')
            });
        }
        announce(t('recording_wizard.ai.request_failed_announce', 'An AI error occurred.'));
        return;
    }

    let text = String(resp.text || '').replace(/```json/g, '').replace(/```/g, '').trim();
    try {
        const json = JSON.parse(text);
        state.broadcastLayout.aiSuggestion = json;
        state.broadcastLayout.aiSuggestionPreviewBase64 = base64;
        state.broadcastLayout.aiSuggestionResponseText = resp.text || '';
        if (els.advancedLayoutAiStatus) {
            els.advancedLayoutAiStatus.textContent = t('recording_wizard.ai.suggestion_ready', 'AI suggestion is ready: {reason}', {
                reason: json.reason || t('recording_wizard.ai.suggestion_created', 'Suggestion created.')
            });
        }
        if (els.btnApplyAiAdvancedLayout) {
            els.btnApplyAiAdvancedLayout.disabled = false;
        }
        if (els.advancedLayoutAiFollowupPanel) {
            els.advancedLayoutAiFollowupPanel.style.display = 'block';
        }
        if (els.advancedLayoutAiFollowupStatus) {
            els.advancedLayoutAiFollowupStatus.textContent = t('recording_wizard.ai.followup_ready', 'You can ask a follow-up question for more detail.');
        }
        announce(t('recording_wizard.ai.suggestion_ready_announce', 'AI suggestion is ready. {reason}', {
            reason: json.reason || ''
        }).trim());
    } catch (error) {
        if (els.advancedLayoutAiStatus) {
            els.advancedLayoutAiStatus.textContent = t('recording_wizard.ai.response_unparsed', 'AI response could not be parsed: {text}', { text });
        }
        announce(t('recording_wizard.ai.response_unparsed_announce', 'The AI response could not be understood.'));
    }
}

async function applyBroadcastAdvancedLayoutAiSuggestion() {
    const suggestion = state.broadcastLayout.aiSuggestion;
    if (!suggestion) {
        return;
    }
    if (typeof suggestion.preset === 'string' && ['side-l', 'side-r', 'side-l-slide', 'side-r-slide'].includes(suggestion.preset)) {
        setSelectedBroadcastAdvancedLayoutMode(suggestion.preset);
    }
    if (suggestion.camera?.scalePercent !== undefined && els.broadcastCamScale) {
        els.broadcastCamScale.value = Math.max(5, Math.min(95, Math.round(suggestion.camera.scalePercent)));
    }
    if (typeof suggestion.panelFillColor === 'string' && els.broadcastCamPanelFillColor) {
        const supportedValues = Array.from(els.broadcastCamPanelFillColor.options).map((option) => option.value);
        if (supportedValues.includes(suggestion.panelFillColor)) {
            els.broadcastCamPanelFillColor.value = suggestion.panelFillColor;
        }
    }
    await applyBroadcastAdvancedLayoutFromControls();
    announce(t('recording_wizard.ai.suggestion_applied', 'AI suggestion applied.'));
}

async function requestBroadcastAdvancedLayoutAiFollowup() {
    const question = String(els.advancedLayoutAiFollowupQuestion?.value || '').trim();
    if (!question) {
        if (els.advancedLayoutAiFollowupStatus) {
            els.advancedLayoutAiFollowupStatus.textContent = t('recording_wizard.ai.followup_missing_question', 'Please type a follow-up question first.');
        }
        announce(t('recording_wizard.ai.followup_missing_question', 'Please type a follow-up question first.'));
        return;
    }
    if (!state.broadcastLayout.aiSuggestionPreviewBase64) {
        if (els.advancedLayoutAiFollowupStatus) {
            els.advancedLayoutAiFollowupStatus.textContent = t('recording_wizard.ai.followup_missing_context', 'Create an AI suggestion first so the follow-up question has context.');
        }
        announce(t('recording_wizard.ai.followup_missing_context', 'Create an AI suggestion first so the follow-up question has context.'));
        return;
    }
    const gemini = await ipcRenderer.invoke('get-gemini-api-data');
    if (!gemini || !gemini.apiKey) {
        if (els.advancedLayoutAiFollowupStatus) {
            els.advancedLayoutAiFollowupStatus.textContent = t('recording_wizard.ai.gemini_key_missing', 'Gemini API key was not found.');
        }
        announce(t('recording_wizard.ai.gemini_key_missing', 'Gemini API key was not found.'));
        return;
    }
    if (els.btnAiFollowupAdvancedLayout) {
        els.btnAiFollowupAdvancedLayout.disabled = true;
    }
    if (els.advancedLayoutAiFollowupStatus) {
        els.advancedLayoutAiFollowupStatus.textContent = t('recording_wizard.ai.followup_preparing', 'Preparing the follow-up answer...');
    }
    announce(t('recording_wizard.ai.followup_preparing_announce', 'Preparing the follow-up answer.'));

    const prompt = [
        isTurkishUi() ? 'Sen bir video düzenleme yardımcısısın.' : 'You are a video production assistant.',
        `${isTurkishUi() ? 'Mevcut düzen' : 'Current layout'}: ${getBroadcastLayoutModeLabel(getSelectedBroadcastAdvancedLayoutMode())}.`,
        `${isTurkishUi() ? 'Katılımcı konumu' : 'Participant placement'}: ${getSelectedOptionText(els.broadcastShareParticipantPlacement) || getSelectedShareParticipantPlacement()}.`,
        `${isTurkishUi() ? 'Konuşmacı alanı ölçeği' : 'Speaker area scale'}: %${els.broadcastCamScale?.value || '35'}.`,
        `${isTurkishUi() ? 'Önceki öneri özeti' : 'Previous suggestion summary'}: ${JSON.stringify(state.broadcastLayout.aiSuggestion || {})}`,
        `${isTurkishUi() ? 'Kullanıcının ek sorusu' : 'User follow-up question'}: ${question}`
    ].join('\n');

    const resp = await ipcRenderer.invoke('gemini-vision-request', {
        apiKey: gemini.apiKey,
        model: gemini.model || 'gemini-2.5-flash',
        imageBase64: state.broadcastLayout.aiSuggestionPreviewBase64,
        prompt,
        history: [],
        systemInstruction: t('runtime.dialogs.ai_system_instruction', 'Respond only in {lang}. Keep the same response language in follow-up answers.', {
            lang: isTurkishUi() ? 'Turkish' : 'English'
        })
    });

    if (!resp || !resp.success) {
        if (els.advancedLayoutAiFollowupStatus) {
            els.advancedLayoutAiFollowupStatus.textContent = t('recording_wizard.ai.request_failed', 'AI error: {error}', {
                error: resp?.error || t('recording_wizard.unknown_error', 'Unknown error')
            });
        }
        announce(t('recording_wizard.ai.request_failed_announce', 'An AI error occurred.'));
    } else {
        const answer = String(resp.text || '').trim();
        if (els.advancedLayoutAiFollowupStatus) {
            els.advancedLayoutAiFollowupStatus.textContent = answer || t('recording_wizard.ai.description_missing', 'Description could not be generated.');
        }
        announce(t('recording_wizard.ai.followup_ready_announce', 'The follow-up answer is ready. {answer}', {
            answer: answer || ''
        }).trim());
    }
    if (els.btnAiFollowupAdvancedLayout) {
        els.btnAiFollowupAdvancedLayout.disabled = false;
    }
}

