async function ensureObsSceneForBroadcastRoom(options = {}) {
    const {
        skipAdvancedLayout = false,
        useSeparateRemoteAudioCapture = false,
        forceLiveRoomAudioBridge = false
    } = options;
    await syncHostLiveKitMedia({ skipShareSync: true });
    const obsAssignments = getHostSceneObsAssignments();
    const includeCamera = !!els.hostCameraEnabled?.checked;
    const includeMic = !!els.hostMicrophoneEnabled?.checked;
    const preferredShare = getPreferredHostShareSource();
    const preferredShareIncludesAudio = !!preferredShare && state.hostLocalShareAudioById[preferredShare.id] === true;
    const useCompositeWindowCapture = shouldUseObsCompositeWindowCapture(preferredShare);
    const hostShareSystemAudioNeeded = preferredShareIncludesAudio;
    const useNativeObsHostShareAudio = state.youtube.liveActive === true && hostShareSystemAudioNeeded;
    const liveRoomAudioBridgeNeeded = forceLiveRoomAudioBridge || getConnectedRemoteParticipantCount() > 0 || hostShareSystemAudioNeeded;
    const compositeAudioNeeded = false;
    const anyOutputAudioNeeded = false;
    const hasAssignedHostCamera = !!obsAssignments.hostCameraSlotId;
    const hasAssignedHostShare = !!obsAssignments.hostLocalShareSlotId && !!preferredShare;
    const shouldIncludeCameraSource = !useCompositeWindowCapture && includeCamera && (hasAssignedHostCamera || !preferredShare);
    const shouldIncludeShareSource = !useCompositeWindowCapture && !!preferredShare && (hasAssignedHostShare || !includeCamera);
    const shouldIncludeCompositeWindowSource = useCompositeWindowCapture;

    if (shouldIncludeCompositeWindowSource) {
        await ensureStageOutputWindow();
        await syncStageOutputWindowMedia().catch(() => {});
        await waitForStageOutputWindowReadyForObsCapture({
            audioExpected: compositeAudioNeeded && !hostShareSystemAudioNeeded,
            visualExpected: includeCamera || !!preferredShare || getConnectedRemoteParticipantCount() > 0
        });
    }

    if (liveRoomAudioBridgeNeeded) {
        try {
            await ensureObsAudioBridgeForBroadcast();
        } catch (error) {
            addDiagnosticEvent('broadcast', t('broadcast_room.status_obs_audio_bridge_failed', 'OBS canlı oda sesi köprüsü başlatılamadı: {error}', {
                error: error?.message || error || 'unknown_error'
            }));
            if (forceLiveRoomAudioBridge && getConnectedRemoteParticipantCount() > 0) {
                throw error;
            }
        }
    }

    if (!shouldIncludeCameraSource && !shouldIncludeShareSource && !shouldIncludeCompositeWindowSource) {
        throw new Error(t('broadcast_room.obs_scene_source_required', 'Yayın için en az bir görsel kaynak gerekli. Host kamerasını açın veya bir yerel paylaşım başlatın.'));
    }

    await ipcRenderer.invoke('obs-ensure-scene', { sceneName: BROADCAST_ROOM_SCENE_NAME });
    const stageOutputWindowTitle = getStageOutputWindowTitle();

    const setupParams = {
        sceneName: BROADCAST_ROOM_SCENE_NAME,
        captureMode: shouldIncludeCompositeWindowSource
            ? 'window'
            : (preferredShare?.shareKind === 'window' || preferredShare?.shareKind === 'application' ? 'window' : 'screen'),
        screenIndex: Number.isInteger(preferredShare?.monitorIndex) ? preferredShare.monitorIndex : 0,
        windowTitles: shouldIncludeCompositeWindowSource
            ? [stageOutputWindowTitle]
            : (preferredShare?.shareKind === 'window' || preferredShare?.shareKind === 'application'
                ? [preferredShare.sourceValue || preferredShare.name]
                : []),
        includeCamera: shouldIncludeCameraSource,
        includeMic,
        includeSystemAudio: useNativeObsHostShareAudio,
        systemAudioMode: shouldIncludeCompositeWindowSource
            ? (hostShareSystemAudioNeeded ? 'system' : 'window')
            : ((preferredShare?.shareKind === 'window' || preferredShare?.shareKind === 'application') ? 'window' : 'system'),
        systemAudioWindowTarget: shouldIncludeCompositeWindowSource
            ? stageOutputWindowTitle
            : (preferredShareIncludesAudio
                ? String(preferredShare?.sourceLookupId || preferredShare?.sourceValue || preferredShare?.name || '')
                : ''),
        allowSystemAudioFallback: useNativeObsHostShareAudio ? true : !shouldIncludeCompositeWindowSource,
        preferExplicitMicSource: state.youtube.liveChecking !== true && state.youtube.liveActive !== true,
        cameraDeviceId: state.audioDevices.selectedCameraId || null,
        micDeviceId: state.audioDevices.selectedMicrophoneId || null,
        cameraLabel: getSelectedCameraLabel(),
        micLabel: getSelectedMicrophoneLabel()
    };

    const setupResult = await ipcRenderer.invoke('obs-setup-sources', setupParams);
    if (!setupResult?.success) {
        throw new Error(setupResult?.error || t('broadcast_room.obs_scene_setup_failed', 'OBS yayın sahnesi hazırlanamadı.'));
    }

    state.obsSceneItems.cameraItemId = setupResult.cameraItemId || null;
    state.obsSceneItems.cameraInputName = setupResult.cameraInputName || null;
    state.obsSceneItems.screenItemId = setupResult.screenItemId || null;
    state.obsSceneItems.screenInputName = setupResult.screenInputName || null;
    state.obsSceneItems.micInputName = setupResult.micInputName || null;
    state.obsSceneItems.systemInputName = setupResult.systemInputName || null;
    await syncObsMicMuteForRoomAudioBridge({
        bridgeActive: liveRoomAudioBridgeNeeded && !!state.obsSceneItems.roomAudioInputName
    });
    if (setupParams.includeSystemAudio) {
        const audioModeKey = setupResult.systemAudioModeApplied === 'window'
            ? ['broadcast_room.obs_audio_mode_window', 'pencere sesi']
            : setupResult.systemAudioModeApplied === 'system'
                ? ['broadcast_room.obs_audio_mode_system', 'sistem sesi']
                : ['broadcast_room.obs_audio_mode_none', 'ses kaynağı bulunamadı'];
        addDiagnosticEvent('broadcast', t('broadcast_room.status_obs_audio_capture_mode', 'OBS ses yakalama modu: {mode}.', {
            mode: t(audioModeKey[0], audioModeKey[1])
        }));
        if (setupParams.systemAudioMode === 'window' && setupResult.systemAudioModeApplied !== 'window') {
            addDiagnosticEvent('broadcast', t('broadcast_room.status_obs_window_audio_capture_missing', 'OBS pencere sesi yakalanamadı. Konuk sesi kayda girmeyebilir; sistem sesi güvenlik için kapalı tutuldu.'));
        }
    }
    await applyBroadcastRecordingAudioPreset({
        micInputName: setupResult.micInputName || null,
        systemInputName: setupResult.systemInputName || null,
        roomAudioInputName: state.obsSceneItems.roomAudioInputName || null
    });

    if ((!shouldIncludeShareSource && !shouldIncludeCompositeWindowSource) || (!preferredShare && !shouldIncludeCompositeWindowSource)) {
        if (setupResult?.screenItemId) {
            await ipcRenderer.invoke('obs-set-scene-item-enabled', {
                sceneName: BROADCAST_ROOM_SCENE_NAME,
                sceneItemId: setupResult.screenItemId,
                enabled: false
            });
        }
    }

    if (shouldIncludeCompositeWindowSource && setupResult?.cameraItemId) {
        await ipcRenderer.invoke('obs-set-scene-item-enabled', {
            sceneName: BROADCAST_ROOM_SCENE_NAME,
            sceneItemId: setupResult.cameraItemId,
            enabled: false
        });
    }

    const videoSettings = await ipcRenderer.invoke('obs-get-video-settings');
    const baseWidth = videoSettings?.success ? (videoSettings.baseWidth || 1920) : 1920;
    const baseHeight = videoSettings?.success ? (videoSettings.baseHeight || 1080) : 1080;
    const slotRects = getSceneSlotLayoutRects(obsAssignments.presetId, baseWidth, baseHeight);
    const hostCameraRect = obsAssignments.hostCameraSlotId ? slotRects[obsAssignments.hostCameraSlotId] : null;
    const hostShareRect = shouldIncludeCompositeWindowSource
        ? { x: 0, y: 0, width: baseWidth, height: baseHeight }
        : (obsAssignments.hostLocalShareSlotId ? slotRects[obsAssignments.hostLocalShareSlotId] : null);

    if (setupResult?.cameraItemId) {
        await ipcRenderer.invoke('obs-set-scene-item-enabled', {
            sceneName: BROADCAST_ROOM_SCENE_NAME,
            sceneItemId: setupResult.cameraItemId,
            enabled: shouldIncludeCameraSource
        });
        if (shouldIncludeCameraSource) {
            const targetRect = hostCameraRect || { x: 0, y: 0, width: baseWidth, height: baseHeight };
            await ipcRenderer.invoke('obs-set-transform', {
                sceneName: BROADCAST_ROOM_SCENE_NAME,
                sceneItemId: setupResult.cameraItemId,
                transform: {
                    positionX: targetRect.x,
                    positionY: targetRect.y,
                    boundsType: 'OBS_BOUNDS_SCALE_INNER',
                    boundsWidth: targetRect.width,
                    boundsHeight: targetRect.height,
                    alignment: 5
                }
            });
        }
    }

    if (setupResult?.screenItemId && (shouldIncludeShareSource || shouldIncludeCompositeWindowSource)) {
        const targetRect = hostShareRect || { x: 0, y: 0, width: baseWidth, height: baseHeight };
        await ipcRenderer.invoke('obs-set-scene-item-enabled', {
            sceneName: BROADCAST_ROOM_SCENE_NAME,
            sceneItemId: setupResult.screenItemId,
            enabled: true
        });
        await ipcRenderer.invoke('obs-set-transform', {
            sceneName: BROADCAST_ROOM_SCENE_NAME,
            sceneItemId: setupResult.screenItemId,
            transform: {
                positionX: targetRect.x,
                positionY: targetRect.y,
                boundsType: 'OBS_BOUNDS_SCALE_INNER',
                boundsWidth: targetRect.width,
                boundsHeight: targetRect.height,
                alignment: 5
            }
        });
    }

    if (!skipAdvancedLayout && !shouldIncludeCompositeWindowSource && canUseAdvancedLayoutPanel() && shouldIncludeCameraSource && shouldIncludeShareSource) {
        syncBroadcastAdvancedLayoutDefaults();
        await applyBroadcastAdvancedLayoutFromControls({ skipEnsureScene: true });
    }

    if (state.sceneBackground?.sourcePath) {
        await applySceneBackgroundToObs().catch((error) => {
            addDiagnosticEvent('scene', t('broadcast_room.status_scene_background_failed', 'Sahne arka planı uygulanamadı: {error}', {
                error: error?.message || error
            }));
        });
    }

    await updateObsCaptionOverlay({ force: true }).catch(() => {});
    return setupResult;
}

function getFormattedYouTubeError(response = {}) {
    return response?.error || 'unknown_error';
}

function applyObsConfig(config = {}) {
    state.obs.config = {
        host: String(config.host || state.obs.config.host || '127.0.0.1'),
        port: Number(config.port || state.obs.config.port || 4455),
        password: String(config.password || state.obs.config.password || '')
    };
}

async function detectObs() {
    state.obs.checking = true;
    renderObsState();
    setStatus(t('broadcast_room.status_obs_checking', 'OBS Studio denetleniyor...'));

    try {
        const result = await ipcRenderer.invoke('obs-detect');
        state.obs.found = !!result?.found;
        if (state.obs.found) {
            setStatus(t('broadcast_room.status_obs_found', 'OBS Studio bulundu.'));
        } else {
            state.obs.connected = false;
            setStatus(t('broadcast_room.status_obs_not_found', 'OBS Studio bulunamadı. Yerel kayıt için OBS gerekli.'));
        }
    } catch (error) {
        state.obs.found = false;
        state.obs.connected = false;
        setStatus(t('broadcast_room.status_obs_detect_failed', 'OBS Studio denetlenemedi: {error}', {
            error: error.message
        }));
    } finally {
        state.obs.checking = false;
        renderObsState();
    }
}

async function testObsConnection(options = {}) {
    const { quiet = false } = options;
    state.obs.checking = true;
    renderObsState();

    try {
        const config = await ipcRenderer.invoke('obs-get-config');
        applyObsConfig(config || {});

        const result = await ipcRenderer.invoke('obs-test-connection', {
            host: state.obs.config.host,
            port: state.obs.config.port,
            password: state.obs.config.password
        });

        state.obs.connected = !!result?.success;
        if (state.obs.connected) {
            state.obs.found = true;
            await releaseIdleObsCameraSource();
            if (!quiet) {
                setStatus(t('broadcast_room.status_obs_connection_ready', 'OBS bağlantısı hazır.'));
            }
        } else if (!quiet) {
            setStatus(t('broadcast_room.status_obs_connection_failed', 'OBS bağlantısı kurulamadı: {error}', {
                error: result?.error || 'unknown_error'
            }));
        }
    } catch (error) {
        state.obs.connected = false;
        if (!quiet) {
            setStatus(t('broadcast_room.status_obs_connection_failed', 'OBS bağlantısı kurulamadı: {error}', {
                error: error.message
            }));
        }
    } finally {
        state.obs.checking = false;
        renderObsState();
    }
}

async function launchObs() {
    state.obs.checking = true;
    renderObsState();

    try {
        const result = await ipcRenderer.invoke('obs-launch');
        if (result && result.success === false) {
            setStatus(t('broadcast_room.status_obs_launch_failed', 'OBS açılamadı: {error}', {
                error: result.error || 'unknown_error'
            }));
            return;
        }

        setStatus(t('broadcast_room.status_obs_launch_started', 'OBS açıldı. Bağlantı hazırlanıyor...'));
        state.obs.found = true;

        let connected = false;
        for (let attempt = 0; attempt < 10; attempt += 1) {
            await new Promise((resolve) => setTimeout(resolve, 1000));
            await testObsConnection({ quiet: true });
            if (state.obs.connected) {
                connected = true;
                break;
            }
        }

        if (connected) {
            setStatus(t('broadcast_room.status_obs_connection_ready', 'OBS bağlantısı hazır.'));
        } else {
            setStatus(t('broadcast_room.status_obs_launch_waiting', 'OBS açıldı ancak bağlantı henüz hazır değil. OBS içinde WebSocket ayarlarını kontrol edin ve Bağlantıyı Test Et düğmesini tekrar deneyin.'));
        }
    } catch (error) {
        setStatus(t('broadcast_room.status_obs_launch_failed', 'OBS açılamadı: {error}', {
            error: error.message
        }));
    } finally {
        state.obs.checking = false;
        renderObsState();
    }
}

async function ensureObsReadyForRecording() {
    if (state.obs.connected) {
        return true;
    }

    if (!state.obs.found) {
        await detectObs();
    }

    if (!state.obs.found) {
        setStatus(t('broadcast_room.status_obs_required_for_recording', 'Yerel kayıt için OBS Studio kurulu ve açık olmalıdır.'));
        return false;
    }

    await testObsConnection({ quiet: true });
    if (!state.obs.connected) {
        setStatus(t('broadcast_room.status_obs_connection_required_for_recording', 'Yerel kayıt için önce OBS bağlantısını hazırlayın. Gerekirse OBS yi Aç veya Bağlantıyı Test Et düğmesini kullanın.'));
        return false;
    }

    return true;
}

function normalizeRecordingStatus(result) {
    if (!result?.success) {
        return;
    }

    state.recording.active = result.outputActive === true;
    state.recording.paused = result.outputPaused === true;
    state.recording.outputPath = String(result.outputPath || result.lastOutputPath || state.recording.outputPath || '');
    if (state.recording.active) {
        if (!state.recording.startedAt) {
            state.recording.startedAt = Date.now();
        }
        state.recording.lastState = state.recording.paused ? 'paused' : 'active';
    } else if (state.recording.lastState !== 'stopped') {
        state.recording.startedAt = 0;
        state.recording.lastState = 'idle';
    }
}

async function refreshRecordingStatus(options = {}) {
    const { quiet = true } = options;
    try {
        const result = await ipcRenderer.invoke('obs-get-recording-status');
        if (!result?.success) {
            if (!quiet) {
                setStatus(t('broadcast_room.status_recording_refresh_failed', 'Kayıt durumu alınamadı: {error}', {
                    error: result?.error || 'unknown_error'
                }));
            }
            return;
        }

        normalizeRecordingStatus(result);
        renderRecordingState();
        syncYouTubeChatStreamOverlay().catch(() => {});
    } catch (error) {
        if (!quiet) {
            setStatus(t('broadcast_room.status_recording_refresh_failed', 'Kayıt durumu alınamadı: {error}', {
                error: error.message
            }));
        }
    }
}

async function loadYouTubeAuthState() {
    const response = await ipcRenderer.invoke('youtube-get-auth-state');
    if (!response.success) {
        state.youtube.connected = false;
        state.youtube.clientConfigured = false;
        state.youtube.accounts = [];
        state.youtube.activeAccountId = '';
        state.youtube.channelTitle = '';
        state.youtube.playlists = [];
        state.youtube.broadcasts = [];
        renderAll();
        return;
    }

    state.youtube.connected = !!response.connected;
    state.youtube.clientConfigured = Boolean(String(response.clientId || '').trim());
    state.youtube.accounts = Array.isArray(response.accounts) ? response.accounts : [];
    state.youtube.activeAccountId = response.activeAccountId || '';
    state.youtube.channelTitle = response.channel?.title || '';
    renderAll();
}

async function refreshYouTubePlaylists(options = {}) {
    if (!state.youtube.connected || !state.youtube.activeAccountId) {
        state.youtube.playlists = [];
        renderAll();
        return;
    }

    const response = await ipcRenderer.invoke('youtube-list-playlists');
    if (!response.success) {
        state.youtube.playlists = [];
        renderAll();
        if (!options.silent) {
            syncYouTubeStatusText(t('broadcast_room.youtube_loading_failed', 'YouTube listeleri alınamadı: {error}', {
                error: response.error || 'unknown_error'
            }));
        }
        return;
    }

    state.youtube.playlists = response.playlists || [];
    renderAll();
}

async function refreshYouTubeBroadcasts(options = {}) {
    if (!state.youtube.connected || !state.youtube.activeAccountId) {
        state.youtube.broadcasts = [];
        renderAll();
        return;
    }

    syncYouTubeStatusText(t('broadcast_room.youtube_loading_broadcasts', 'Planlı YouTube yayınları getiriliyor...'));
    const response = await ipcRenderer.invoke('youtube-list-planned-broadcasts');
    if (!response.success) {
        state.youtube.broadcasts = [];
        renderAll();
        syncYouTubeStatusText(t('broadcast_room.youtube_loading_failed', 'YouTube listeleri alınamadı: {error}', {
            error: response.error || 'unknown_error'
        }));
        if (!options.silent) {
            announce(t('broadcast_room.youtube_loading_failed_announce', 'YouTube yayın listesi alınamadı.'));
        }
        return;
    }

    state.youtube.broadcasts = response.broadcasts || [];
    if (!state.youtube.selectedBroadcastId && state.youtube.broadcasts[0]) {
        state.youtube.selectedBroadcastId = state.youtube.broadcasts[0].id;
    }
    renderAll();
    syncYouTubeStatusText(
        state.youtube.broadcasts.length > 0
            ? t('broadcast_room.youtube_broadcasts_loaded', 'YouTube planlı yayın listesi hazır.')
            : t('broadcast_room.youtube_no_broadcasts', 'Planlı YouTube yayını bulunamadı.')
    );
}

// One-time OAuth setup intentionally has no shortcut-manager action.
async function saveYouTubeClientConfig() {
    const clientId = String(els.youtubeClientId?.value || '').trim();
    const clientSecret = String(els.youtubeClientSecret?.value || '').trim();
    if (!clientId) {
        syncYouTubeStatusText(t('youtube_oauth_setup.client_id_required', 'YouTube OAuth Client ID gereklidir.'));
        els.youtubeClientId?.focus();
        return;
    }
    const response = await ipcRenderer.invoke('youtube-save-client-config', { clientId, clientSecret });
    if (!response?.success) {
        syncYouTubeStatusText(t('youtube_oauth_setup.save_failed', 'YouTube OAuth bilgileri kaydedilemedi: {error}', { error: response?.error || 'unknown_error' }));
        return;
    }
    if (els.youtubeClientSecret) els.youtubeClientSecret.value = '';
    await loadYouTubeAuthState();
    const message = t('youtube_oauth_setup.saved', 'YouTube OAuth bilgileri kaydedildi. Şimdi YouTube hesabınızı bağlayabilirsiniz.');
    syncYouTubeStatusText(message);
    announce(message);
    els.btnYoutubeConnect?.focus();
}

async function connectYouTubeAccount() {
    state.youtube.checking = true;
    renderAll();
    syncYouTubeStatusText(t('broadcast_room.youtube_auth_connecting', 'YouTube bağlantısı açılıyor...'));

    try {
        const response = await ipcRenderer.invoke('youtube-connect-account');
        if (!response.success) {
            syncYouTubeStatusText(t('broadcast_room.youtube_auth_failed', 'YouTube hesabı bağlanamadı: {error}', {
                error: response.error || 'unknown_error'
            }));
            return;
        }

        await loadYouTubeAuthState();
        await refreshYouTubePlaylists({ silent: true });
        await refreshYouTubeBroadcasts({ silent: true });
        syncYouTubeStatusText(t('broadcast_room.youtube_auth_connected_short', 'YouTube hesabı bağlandı.'));
    } finally {
        state.youtube.checking = false;
        renderAll();
    }
}

async function disconnectYouTubeAccount() {
    state.youtube.checking = true;
    renderAll();

    try {
        const response = await ipcRenderer.invoke('youtube-disconnect-account', {
            accountId: state.youtube.activeAccountId
        });
        if (!response.success) {
            syncYouTubeStatusText(t('broadcast_room.youtube_disconnect_failed', 'YouTube bağlantısı kaldırılamadı: {error}', {
                error: response.error || 'unknown_error'
            }));
            return;
        }

        state.youtube.connected = false;
        state.youtube.accounts = [];
        state.youtube.activeAccountId = '';
        state.youtube.channelTitle = '';
        state.youtube.playlists = [];
        state.youtube.selectedPlaylistId = '';
        state.youtube.broadcasts = [];
        state.youtube.selectedBroadcastId = '';
        state.youtube.preparedBroadcastId = '';
        state.youtube.preparedBroadcastTitle = '';
        state.youtube.preparedWatchUrl = '';
        resetYouTubeChatState();
        renderAll();
        syncYouTubeStatusText(t('broadcast_room.youtube_disconnected', 'YouTube bağlantısı kaldırıldı.'));
    } finally {
        state.youtube.checking = false;
        renderAll();
    }
}

async function prepareYouTubeBroadcast() {
    if (!state.youtube.connected || !state.youtube.activeAccountId) {
        syncYouTubeStatusText(t('broadcast_room.youtube_auth_required', 'Öncelikle YouTube hesabınızı bağlayın.'));
        return;
    }

    state.youtube.checking = true;
    renderAll();

    try {
        let response = null;
        let preparedBroadcast = null;
        let ingestion = null;

        if (state.youtube.mode === 'existing') {
            if (!state.youtube.selectedBroadcastId) {
                syncYouTubeStatusText(t('broadcast_room.youtube_existing_required', 'Lütfen planlı bir YouTube yayını seçin.'));
                return;
            }

            response = await ipcRenderer.invoke('youtube-prepare-existing-broadcast', {
                broadcastId: state.youtube.selectedBroadcastId,
                playlistId: state.youtube.selectedPlaylistId
            });
            if (!response.success) {
                syncYouTubeStatusText(t('broadcast_room.youtube_prepare_failed', 'Seçilen YouTube yayını hazırlanamadı: {error}', {
                    error: getFormattedYouTubeError(response)
                }));
                return;
            }
            preparedBroadcast = response.broadcast;
            ingestion = response.ingestion;
        } else {
            const createTitle = String(els.youtubeTitle?.value || '').trim();
            if (!createTitle) {
                syncYouTubeStatusText(t('broadcast_room.youtube_title_required', 'YouTube yayın başlığı gerekli.'));
                return;
            }

            const description = String(els.youtubeDescription?.value || '').trim();
            const privacyStatus = String(els.youtubeVisibility?.value || 'private');
            const scheduledStartTime = state.youtube.mode === 'planned'
                ? localInputToIso(String(els.youtubeScheduledAt?.value || ''))
                : new Date().toISOString();

            if (state.youtube.mode === 'planned' && !scheduledStartTime) {
                syncYouTubeStatusText(t('broadcast_room.youtube_schedule_required', 'Planlı yayın için başlangıç zamanı gerekli.'));
                return;
            }

            response = await ipcRenderer.invoke('youtube-create-broadcast', {
                title: createTitle,
                description,
                privacyStatus,
                scheduledStartTime,
                madeForKids: false,
                playlistId: state.youtube.selectedPlaylistId,
                enableAutoStart: true,
                enableAutoStop: true
            });
            if (!response.success) {
                syncYouTubeStatusText(t('broadcast_room.youtube_prepare_failed', 'YouTube yayını hazırlanamadı: {error}', {
                    error: getFormattedYouTubeError(response)
                }));
                return;
            }
            preparedBroadcast = response.broadcast;
            ingestion = response.ingestion;
        }

        state.youtube.preparedBroadcastId = preparedBroadcast?.id || '';
        state.youtube.preparedBroadcastTitle = preparedBroadcast?.title || '';
        state.youtube.preparedWatchUrl = preparedBroadcast?.watchUrl || '';
        state.youtube.broadcastServer = ingestion?.server || state.youtube.broadcastServer;
        state.youtube.broadcastStreamKey = ingestion?.streamKey || state.youtube.broadcastStreamKey;
        resetYouTubeChatState();
        renderAll();
        await refreshYouTubeLiveStats();
        await syncLiveRoomSettings();
        syncYouTubeStatusText(t('broadcast_room.youtube_prepared', 'YouTube yayını hazırlandı: {title}', {
            title: state.youtube.preparedBroadcastTitle || t('broadcast_room.youtube_broadcast_untitled', 'Adsız yayın')
        }));
        await ensureYouTubeChatSessionLoaded();
        await pollYouTubeChatMessages({ initial: true });
    } finally {
        state.youtube.checking = false;
        renderAll();
    }
}

async function applyYouTubeBroadcastSettings() {
    if (!state.youtube.broadcastServer) {
        throw new Error(t('broadcast_room.youtube_server_required', 'Yayın sunucusu hazır değil. Önce yayını hazırlayın.'));
    }
    if (!state.youtube.broadcastStreamKey) {
        throw new Error(t('broadcast_room.youtube_stream_key_required', 'Yayın anahtarı hazır değil. Önce yayını hazırlayın.'));
    }

    const result = await ipcRenderer.invoke('obs-set-stream-service-settings', {
        streamServiceType: 'rtmp_custom',
        streamServiceSettings: {
            server: state.youtube.broadcastServer,
            key: state.youtube.broadcastStreamKey
        }
    });

    if (!result?.success) {
        throw new Error(result?.error || t('broadcast_room.youtube_stream_settings_failed', 'OBS yayın ayarları uygulanamadı.'));
    }
}

async function applyYouTubeStreamQualityPreset() {
    const result = await ipcRenderer.invoke('obs-apply-video-quality-preset', {
        preset: 'youtube_720',
        mode: 'broadcast'
    }).catch((error) => ({
        success: false,
        error: error?.message || String(error || '')
    }));

    if (!result?.success) {
        addDiagnosticEvent('broadcast', t('broadcast_room.status_youtube_quality_preset_failed', 'YouTube yayın kalite ayarı uygulanamadı: {error}', {
            error: result?.error || 'unknown_error'
        }));
        logBroadcastRoomDebug('youtube-quality-preset-failed', {
            error: result?.error || 'unknown_error'
        });
        return false;
    }

    const stream = result.stream || {};
    addDiagnosticEvent('broadcast', t('broadcast_room.status_youtube_quality_preset_applied', 'YouTube yayın kalite ayarı uygulandı: 720p 30 FPS, video {videoBitrate} kbps, ses {audioBitrate} kbps, anahtar kare {keyframeIntervalSec} saniye.', {
        videoBitrate: stream.videoBitrate || 6000,
        audioBitrate: stream.audioBitrate || 160,
        keyframeIntervalSec: stream.keyframeIntervalSec || 2
    }));
    logBroadcastRoomDebug('youtube-quality-preset-applied', {
        preset: result.preset || 'youtube_720',
        settings: result.settings || null,
        stream
    });
    return true;
}

async function refreshStreamingStatus(options = {}) {
    try {
        const result = await ipcRenderer.invoke('obs-get-streaming-status');
        if (!result?.success) {
            return;
        }

        state.youtube.liveActive = !!result.outputActive;
        if (state.youtube.liveActive) {
            state.youtube.lastLiveState = 'active';
            if (!state.youtube.healthTimer) {
                startYouTubeHealthDiagnostics();
            }
        } else if (state.youtube.lastLiveState === 'active') {
            state.youtube.lastLiveState = 'stopped';
            stopYouTubeHealthDiagnostics();
        }
        updateYouTubeAuthUi();
        renderYouTubeLiveState();
        syncYouTubeChatStreamOverlay().catch(() => {});
    } catch (error) {
        if (!options.quiet) {
            syncYouTubeStatusText(t('broadcast_room.youtube_status_refresh_failed', 'Canlı yayın durumu alınamadı: {error}', {
                error: error.message
            }));
        }
    }
}

function stopYouTubeHealthDiagnostics() {
    if (state.youtube.healthTimer) {
        clearInterval(state.youtube.healthTimer);
        state.youtube.healthTimer = null;
    }
    state.youtube.lastHealthSignature = '';
}

function formatOptionalNumber(value, digits = 1) {
    const number = Number(value);
    if (!Number.isFinite(number)) {
        return '-';
    }
    return number.toFixed(digits);
}

async function sampleYouTubeHealthDiagnostics() {
    if (state.youtube.liveActive !== true) {
        return;
    }
    try {
        const [streamStatus, stats] = await Promise.all([
            ipcRenderer.invoke('obs-get-streaming-status').catch((error) => ({ success: false, error: error?.message || String(error || '') })),
            ipcRenderer.invoke('obs-get-stats').catch((error) => ({ success: false, error: error?.message || String(error || '') }))
        ]);
        const payload = {
            active: streamStatus?.outputActive === true,
            reconnecting: streamStatus?.outputReconnecting === true,
            congestion: formatOptionalNumber(streamStatus?.outputCongestion, 2),
            streamDropped: Number(streamStatus?.outputSkippedFrames ?? 0) || 0,
            streamTotal: Number(streamStatus?.outputTotalFrames ?? 0) || 0,
            renderSkipped: Number(stats?.renderSkippedFrames ?? 0) || 0,
            outputSkipped: Number(stats?.outputSkippedFrames ?? 0) || 0,
            fps: formatOptionalNumber(stats?.activeFps, 1),
            renderMs: formatOptionalNumber(stats?.averageFrameRenderTime, 2),
            cpu: formatOptionalNumber(stats?.cpuUsage, 1),
            memory: formatOptionalNumber(stats?.memoryUsage, 0)
        };
        const signature = JSON.stringify(payload);
        if (signature === state.youtube.lastHealthSignature) {
            return;
        }
        state.youtube.lastHealthSignature = signature;
        addDiagnosticEvent('broadcast', t('broadcast_room.status_youtube_health_diagnostics', 'YouTube yayın sağlığı: aktif={active}, yeniden bağlanıyor={reconnecting}, tıkanıklık={congestion}, stream düşen kare={streamDropped}/{streamTotal}, render atlanan={renderSkipped}, çıkış atlanan={outputSkipped}, FPS={fps}, render={renderMs} ms, CPU={cpu}%, bellek={memory} MB.', payload));
        logBroadcastRoomDebug('youtube-health-diagnostics', payload);
    } catch (error) {
        logBroadcastRoomDebug('youtube-health-diagnostics-failed', {
            error: error?.message || String(error || '')
        });
    }
}

function startYouTubeHealthDiagnostics() {
    stopYouTubeHealthDiagnostics();
    sampleYouTubeHealthDiagnostics().catch(() => {});
    state.youtube.healthTimer = setInterval(() => {
        sampleYouTubeHealthDiagnostics().catch(() => {});
    }, 15000);
}

async function startYouTubeLive() {
    const obsReady = await ensureObsReadyForRecording();
    if (!obsReady) {
        renderAll();
        return;
    }

    if (!state.youtube.preparedBroadcastId) {
        syncYouTubeStatusText(t('broadcast_room.youtube_prepare_first', 'Önce YouTube yayınını hazırlayın.'));
        return;
    }

    state.youtube.liveChecking = true;
    state.stageCapturePreparing = true;
    renderStageFocusMode();
    renderAll();

    try {
        const introSlot = getConfiguredLiveEffectSlot('intro');
        await resetLiveEffectsSession({ removeObsVideo: !(introSlot && introSlot.type === 'video') });
        await new Promise((resolve) => setTimeout(resolve, 250));
        await stopObsAudioBridge().catch(() => {});
        state.obsSceneItems.roomAudioInputName = null;
        state.obsSceneItems.roomAudioSourceUrl = '';
        state.liveRoom.obsAudioBridgeInputName = '';
        const resetAudioSourcesResult = await ipcRenderer.invoke('obs-reset-broadcast-room-audio-sources', {
            sceneName: BROADCAST_ROOM_SCENE_NAME
        }).catch((error) => {
            logBroadcastRoomDebug('obs-broadcast-audio-source-reset-failed', {
                error: error?.message || String(error || '')
            });
            return null;
        });
        if (resetAudioSourcesResult && resetAudioSourcesResult.success === false) {
            logBroadcastRoomDebug('obs-broadcast-audio-source-reset-failed', {
                error: resetAudioSourcesResult.error || 'unknown_error'
            });
        }
        await ensureObsSceneForBroadcastRoom({ forceLiveRoomAudioBridge: true });
        await applyYouTubeStreamQualityPreset();
        await applyYouTubeBroadcastSettings();
        const result = await ipcRenderer.invoke('obs-start-streaming');
        if (!result?.success) {
            syncYouTubeStatusText(t('broadcast_room.youtube_start_failed', 'Canlı yayın başlatılamadı: {error}', {
                error: getFormattedYouTubeError(result)
            }));
            return;
        }
        await ipcRenderer.invoke('youtube-save-active-live-broadcast', {
            broadcastId: state.youtube.preparedBroadcastId,
            title: state.youtube.preparedBroadcastTitle || '',
            watchUrl: state.youtube.preparedWatchUrl || '',
            source: 'broadcast-room'
        }).catch(() => {});

        const liveResponse = await ipcRenderer.invoke('youtube-transition-broadcast-live', {
            broadcastId: state.youtube.preparedBroadcastId
        });

        state.youtube.liveActive = true;
        state.youtube.lastLiveState = 'active';
        try {
            await ensureObsAudioBridgeForBroadcast();
        } catch (error) {
            logBroadcastRoomDebug('obs-audio-bridge-youtube-activation-retry-failed', {
                error: error?.message || String(error || '')
            });
        }
        await syncLiveRoomSettings();
        state.stageCapturePreparing = false;
        startYouTubeHealthDiagnostics();
        await enforceYoutubeTranslationServicePolicy();
        renderStageFocusMode();
        renderAll();
        await renderHostRemoteParticipantMedia();

        if (!liveResponse?.success) {
            syncYouTubeStatusText(t('broadcast_room.youtube_transition_failed', 'OBS yayını başladı ancak YouTube canlıya geçemedi: {error}', {
                error: getFormattedYouTubeError(liveResponse)
            }));
            setStatus(t('broadcast_room.status_youtube_started_with_warning', 'Yayın OBS tarafında başladı ancak YouTube canlıya geçişi tamamlanamadı.'));
            await refreshStreamingStatus({ quiet: true });
            return;
        }

        syncYouTubeStatusText(t('broadcast_room.youtube_live_started', 'YouTube canlı yayını başladı: {title}', {
            title: state.youtube.preparedBroadcastTitle || t('broadcast_room.youtube_broadcast_untitled', 'Adsız yayın')
        }));
        addDiagnosticEvent('broadcast', t('broadcast_room.status_youtube_started', 'YouTube canlı yayını başlatıldı.'));
        setStatus(t('broadcast_room.status_youtube_started', 'YouTube canlı yayını başlatıldı.'));
        await ensureYouTubeChatSessionLoaded();
        await pollYouTubeChatMessages({ initial: true });
        await refreshYouTubeLiveStats({ scheduleNext: true });
        if (introSlot && introSlot.sourcePath) {
            await playLiveEffectSlot(introSlot, {
                announceSelection: false,
                forceLoop: false,
                waitForCompletion: false
            });
        }
        await refreshStreamingStatus({ quiet: true });
    } finally {
        state.youtube.liveChecking = false;
        state.stageCapturePreparing = false;
        renderStageFocusMode();
        renderAll();
    }
}

async function stopYouTubeLive() {
    state.youtube.liveChecking = true;
    renderAll();

    try {
        const outroSlot = getConfiguredLiveEffectSlot('outro');
        if (outroSlot && outroSlot.sourcePath) {
            syncYouTubeStatusText(t('recording_wizard.recording.outro_playing', 'Bitiş efekti çalıyor, kayıt tamamlanınca otomatik duracak...'));
            let outroPlayed = false;
            try {
                outroPlayed = await playLiveEffectSlotForOutputStop(outroSlot, {
                    debugPrefix: 'youtube-outro-effect'
                });
            } catch (error) {
                logBroadcastRoomDebug('youtube-outro-effect-start-failed', {
                    slotId: outroSlot.id || null,
                    slotType: outroSlot.type || null,
                    sourcePath: outroSlot.sourcePath || null,
                    error: error?.message || String(error || 'unknown_error')
                });
            }
            if (!outroPlayed) {
                logBroadcastRoomDebug('youtube-outro-effect-player-failed-fallback-wait', {
                    slotId: outroSlot.id || null,
                    slotType: outroSlot.type || null,
                    sourcePath: outroSlot.sourcePath || null
                });
                await new Promise((resolve) => setTimeout(resolve, 3000));
            }
            await new Promise((resolve) => setTimeout(resolve, 5000));
        }
        const result = await ipcRenderer.invoke('obs-stop-streaming');
        if (!result?.success) {
            syncYouTubeStatusText(t('broadcast_room.youtube_stop_failed', 'Canlı yayın durdurulamadı: {error}', {
                error: getFormattedYouTubeError(result)
            }));
            return;
        }

        if (state.youtube.preparedBroadcastId) {
            const completeResponse = await ipcRenderer.invoke('youtube-complete-broadcast', {
                broadcastId: state.youtube.preparedBroadcastId
            });
            if (!completeResponse?.success) {
                syncYouTubeStatusText(t('broadcast_room.youtube_complete_failed', 'OBS yayını durdu ancak YouTube kapanışı tamamlanamadı: {error}', {
                    error: getFormattedYouTubeError(completeResponse)
                }));
                state.youtube.liveActive = false;
                state.youtube.lastLiveState = 'stopped';
                stopYouTubeHealthDiagnostics();
                await updateObsCaptionOverlay({ force: true }).catch(() => {});
                await releaseIdleObsCameraSource();
                renderStageFocusMode();
                renderAll();
                return;
            }
        }

        state.youtube.liveActive = false;
        state.youtube.lastLiveState = 'stopped';
        stopYouTubeHealthDiagnostics();
        await syncLiveRoomSettings();
        await ipcRenderer.invoke('youtube-clear-active-live-broadcast').catch(() => {});
        await updateObsCaptionOverlay({ force: true }).catch(() => {});
        await releaseIdleObsCameraSource();
        renderStageFocusMode();
        renderAll();
        await renderHostRemoteParticipantMedia();
        stopYouTubeChatPolling();
        stopYouTubeLiveStatsPolling();
        await refreshYouTubeLiveStats();
        await syncYouTubeChatStreamOverlay();
        await resetLiveEffectsSession();
        syncYouTubeStatusText(t('broadcast_room.youtube_live_stopped', 'YouTube canlı yayını durduruldu.'));
        addDiagnosticEvent('broadcast', t('broadcast_room.status_youtube_stopped', 'YouTube canlı yayını durduruldu.'));
        setStatus(t('broadcast_room.status_youtube_stopped', 'YouTube canlı yayını durduruldu.'));
        await refreshStreamingStatus({ quiet: true });
    } finally {
        state.youtube.liveChecking = false;
        renderAll();
    }
}

async function toggleYouTubeLiveFromShortcut() {
    if (state.youtube.liveChecking) {
        setStatus(t('broadcast_room.status_youtube_toggle_busy', 'YouTube canlı yayın işlemi zaten sürüyor.'));
        return;
    }
    if (state.youtube.liveActive) {
        await stopYouTubeLive();
    } else {
        await startYouTubeLive();
    }
}

function registerBroadcastRoomGlobalShortcuts() {
    const accelerators = Object.keys(BROADCAST_ROOM_GLOBAL_SHORTCUT_ACTIONS)
        .map((actionId) => normalizeGlobalShortcutAccelerator(getBroadcastRoomGlobalShortcutBinding(actionId)))
        .filter(Boolean);
    [...new Set(accelerators)].forEach((accelerator) => {
        ipcRenderer.invoke('register-global-shortcut', {
            accelerator,
            focusWindowOnTrigger: true
        }).catch(() => {});
    });
}

function unregisterBroadcastRoomGlobalShortcuts() {
    const accelerators = Object.keys(BROADCAST_ROOM_GLOBAL_SHORTCUT_ACTIONS)
        .map((actionId) => normalizeGlobalShortcutAccelerator(getBroadcastRoomGlobalShortcutBinding(actionId)))
        .filter(Boolean);
    accelerators.forEach((accelerator) => {
        ipcRenderer.invoke('unregister-global-shortcut', accelerator).catch(() => {});
    });
}

function openPreparedYouTubeWatchLink() {
    if (!state.youtube.preparedWatchUrl) {
        return;
    }
    shell.openExternal(state.youtube.preparedWatchUrl);
}

function copyPreparedYouTubeWatchLink() {
    if (!state.youtube.preparedWatchUrl) {
        return;
    }
    clipboard.writeText(state.youtube.preparedWatchUrl);
    syncYouTubeStatusText(t('broadcast_room.youtube_watch_link_copied', 'YouTube bağlantısı panoya kopyalandı.'));
}

function ensureRecordingStatusPolling() {
    if (state.recording.pollTimer) {
        clearInterval(state.recording.pollTimer);
    }

    state.recording.pollTimer = setInterval(() => {
        refreshRecordingStatus({ quiet: true }).catch((error) => {
            console.error('Broadcast room recording status poll error:', error);
        });
        refreshStreamingStatus({ quiet: true }).catch((error) => {
            console.error('Broadcast room streaming status poll error:', error);
        });
    }, 1500);
}

async function startLocalRecording() {
    const obsReady = await ensureObsReadyForRecording();
    if (!obsReady) {
        renderRecordingState();
        return;
    }

    state.recording.checking = true;
    state.stageCapturePreparing = true;
    state.recording.startedAt = 0;
    resetRecordingTimeline();
    resetDubRecordingArchive();
    renderStageFocusMode();
    renderRecordingState();

    try {
        const introSlot = getConfiguredLiveEffectSlot('intro');
        await resetLiveEffectsSession({ removeObsVideo: !(introSlot && introSlot.type === 'video') });
        if (introSlot && introSlot.sourcePath && introSlot.type === 'video') {
            await syncLiveEffectVisual(introSlot, { visible: false, restart: false });
        }
        await new Promise((resolve) => setTimeout(resolve, 250));
        await ensureObsSceneForBroadcastRoom();
        if (!state.liveRoom.obsAudioBridgeReady) {
            startRemoteAudioRecorderForRecording();
        }
        state.recording.startedAt = Date.now();
        state.recording.lastStartedAt = state.recording.startedAt;
        const result = await ipcRenderer.invoke('obs-start-recording');
        if (!result?.success) {
            await stopRemoteAudioRecorderForRecording().catch(() => {});
            setStatus(t('broadcast_room.status_recording_start_failed', 'Kayıt başlatılamadı: {error}', {
                error: result?.error || 'unknown_error'
            }));
            return;
        }

        normalizeRecordingStatus({
            success: true,
            outputActive: result.outputActive !== false,
            outputPaused: false,
            outputPath: result.outputPath || state.recording.outputPath || ''
        });
        state.recording.lastState = 'active';
        recordRecordingTimelineEvent('recording_started', { force: true });
        startLiveInterpreterTrackRecorderIfEnabled();
        state.stageCapturePreparing = false;
        renderStageFocusMode();
        renderRecordingState();
        await renderHostRemoteParticipantMedia();
        await syncLiveRoomSettings().catch(() => {});
        addDiagnosticEvent('broadcast', t('broadcast_room.status_recording_started', 'Yerel kayıt başlatıldı.'));
        setStatus(t('broadcast_room.status_recording_started', 'Yerel kayıt başlatıldı.'));
        if (introSlot && introSlot.sourcePath) {
            await playLiveEffectSlot(introSlot, {
                announceSelection: false,
                forceLoop: false,
                waitForCompletion: false
            });
        }
        await refreshRecordingStatus({ quiet: true });
    } catch (error) {
        setStatus(t('broadcast_room.status_recording_start_failed', 'Kayıt başlatılamadı: {error}', {
            error: error.message
        }));
    } finally {
        state.recording.checking = false;
        state.stageCapturePreparing = false;
        if (!state.recording.active && state.recording.lastState !== 'active') {
            state.recording.startedAt = 0;
        }
        renderStageFocusMode();
        renderRecordingState();
    }
}

async function stopLocalRecording() {
    state.recording.checking = true;
    renderRecordingState();

    try {
        const outroSlot = getConfiguredLiveEffectSlot('outro');
        if (outroSlot && outroSlot.sourcePath) {
            if (els.recordingStatus) {
                els.recordingStatus.textContent = t('recording_wizard.recording.outro_playing', 'Bitiş efekti çalıyor, kayıt tamamlanınca otomatik duracak...');
            }
            await playLiveEffectSlot(outroSlot, {
                announceSelection: false,
                forceLoop: false,
                waitForCompletion: true
            });
        }
        if (state.translation.running || state.translation.waitingForAudio || state.translation.finalizing || hasPendingTranslationGenerationWork()) {
            await stopLiveTranslationPrototype({ quiet: true, preservePrepared: false, preserveTranscript: true });
        }
        const result = await ipcRenderer.invoke('obs-stop-recording');
        const liveInterpreterAudioPath = await stopLiveInterpreterTrackRecorder();
        const remoteAudioPath = await stopRemoteAudioRecorderForRecording();
        if (!result?.success) {
            await stopLiveInterpreterTrackRecorder().catch(() => {});
            await stopRemoteAudioRecorderForRecording().catch(() => {});
            setStatus(t('broadcast_room.status_recording_stop_failed', 'Kayıt durdurulamadı: {error}', {
                error: result?.error || 'unknown_error'
            }));
            return;
        }

        recordRecordingTimelineEvent('recording_stopping', { force: true });
        state.recording.active = false;
        state.recording.paused = false;
        state.recording.startedAt = 0;
        state.recording.outputPath = String(result.outputPath || state.recording.outputPath || '');
        state.recording.dubSegmentInputPath = state.recording.outputPath || state.recording.dubSegmentInputPath || '';
        state.recording.lastState = 'stopped';
        if (remoteAudioPath && state.recording.outputPath) {
            setStatus(t('broadcast_room.status_recording_remote_audio_mixing', 'Konuk sesi kayda ekleniyor...'));
            const mixResponse = await ipcRenderer.invoke('ffmpeg-mix-extra-audio-into-recording', {
                videoPath: state.recording.outputPath,
                audioPath: remoteAudioPath,
                audioVolume: 1
            });
            if (mixResponse?.success && mixResponse.outputPath) {
                state.recording.outputPath = String(mixResponse.outputPath);
                state.recording.dubSegmentInputPath = state.recording.outputPath;
                addDiagnosticEvent('broadcast', t('broadcast_room.status_recording_remote_audio_mixed', 'Konuk sesi kayıt dosyasına eklendi.'));
            } else {
                addDiagnosticEvent('broadcast', t('broadcast_room.status_recording_remote_audio_mix_failed', 'Konuk sesi kayıt dosyasına eklenemedi: {error}', {
                    error: mixResponse?.error || 'unknown_error'
                }));
            }
        } else {
            addDiagnosticEvent('broadcast', t('broadcast_room.status_recording_remote_audio_empty', 'Konuk sesi için ayrı kayıt verisi oluşmadı. Konuk mikrofonu kapalı olabilir veya ses izi kayıt sırasında gelmemiş olabilir.'));
        }
        const timelinePath = writeRecordingTimelineFile(state.recording.outputPath);
        if (timelinePath) {
            addDiagnosticEvent('broadcast', t('broadcast_room.status_recording_timeline_saved', 'Kayıt sahne zaman çizelgesi kaydedildi: {path}', {
                path: timelinePath
            }));
        }
        await updateObsCaptionOverlay({ force: true }).catch(() => {});
        await releaseIdleObsCameraSource();
        await stopIdleObsAudioBridge('recording_stopped').catch((error) => {
            logBroadcastRoomDebug('obs-audio-bridge-stop-idle-failed', {
                reason: 'recording_stopped',
                error: error?.message || String(error || '')
            });
        });
        await resetLiveEffectsSession();
        renderStageFocusMode();
        renderRecordingState();
        await renderHostRemoteParticipantMedia();
        await syncLiveRoomSettings().catch(() => {});
        await refreshLocalBackupRecordings({ quiet: true }).catch(() => {});
        await addLiveInterpreterTrackAfterRecordingIfEnabled(liveInterpreterAudioPath);
        const stoppedMessage = state.recording.outputPath
            ? t('broadcast_room.status_recording_stopped_with_path', 'Yerel kayıt durduruldu. Çıktı: {path}', {
                path: state.recording.outputPath
            })
            : t('broadcast_room.status_recording_stopped', 'Yerel kayıt durduruldu.');
        addDiagnosticEvent('broadcast', stoppedMessage);
        setStatus(stoppedMessage);
    } catch (error) {
        setStatus(t('broadcast_room.status_recording_stop_failed', 'Kayıt durdurulamadı: {error}', {
            error: error.message
        }));
    } finally {
        state.recording.checking = false;
        renderRecordingState();
    }
}

function getBotStageRecordingOutputPath() {
    const baseDir = state.recording.outputPath
        ? path.dirname(state.recording.outputPath)
        : path.join(os.homedir(), 'Videos', 'EVD');
    try {
        fs.mkdirSync(baseDir, { recursive: true });
    } catch (_error) {}
    const stamp = new Date().toISOString()
        .replace(/[:T]/g, '-')
        .replace(/\..+$/, '');
    return path.join(baseDir, `${stamp}-bot-sahne-kaydi.webm`);
}

function getPreferredBotRecordingMimeType() {
    const candidates = [
        'video/webm;codecs=vp9,opus',
        'video/webm;codecs=vp8,opus',
        'video/webm'
    ];
    return candidates.find((candidate) => {
        try {
            return typeof MediaRecorder !== 'undefined' && MediaRecorder.isTypeSupported(candidate);
        } catch (_error) {
            return false;
        }
    }) || '';
}

async function getStageOutputDesktopSource() {
    const title = getStageOutputWindowTitle();
    const normalizedTitle = title.toLocaleLowerCase(i18nState.currentLang || 'tr');
    let lastSourceNames = [];
    for (let attempt = 0; attempt < 12; attempt += 1) {
        const response = await ipcRenderer.invoke('get-desktop-sources', {
            types: ['window', 'screen'],
            thumbnailSize: { width: 0, height: 0 },
            fetchWindowIcons: false
        });
        if (!response?.success) {
            throw new Error(response?.error || 'desktop_sources_unavailable');
        }
        const sources = Array.isArray(response.sources) ? response.sources : [];
        lastSourceNames = sources.map((source) => String(source.name || '').trim()).filter(Boolean);
        const windowSources = sources.filter((source) => String(source.id || '').startsWith('window:'));
        const match = windowSources.find((source) => String(source.name || '').trim() === title)
            || windowSources.find((source) => String(source.name || '').toLocaleLowerCase(i18nState.currentLang || 'tr').includes(normalizedTitle))
            || windowSources.find((source) => String(source.name || '').toLocaleLowerCase(i18nState.currentLang || 'tr').includes('yayın çıkışı'))
            || windowSources.find((source) => String(source.name || '').toLocaleLowerCase(i18nState.currentLang || 'tr').includes('yayin cikisi'))
            || windowSources.find((source) => String(source.name || '').toLocaleLowerCase(i18nState.currentLang || 'tr').includes('stage output'));
        if (match?.id) {
            logBroadcastRoomDebug('bot-stage-recording-source-found', {
                attempt: attempt + 1,
                sourceId: match.id,
                sourceName: match.name || ''
            });
            return match;
        }
        await new Promise((resolve) => setTimeout(resolve, 250));
    }
    logBroadcastRoomDebug('bot-stage-recording-source-missing', {
        expectedTitle: title,
        sources: lastSourceNames.slice(0, 30)
    });
    return null;
}

async function captureStageOutputWindowForBotRecording() {
    await ensureStageOutputWindow({ focus: false });
    await syncStageOutputWindowMedia().catch(() => {});
    await protectStageOutputWindowForCapture().catch(() => {});
    await new Promise((resolve) => setTimeout(resolve, 350));
    await waitForStageOutputWindowReadyForObsCapture({
        audioExpected: false,
        visualExpected: true,
        timeoutMs: 3600
    });
    await protectStageOutputWindowForCapture().catch(() => {});
    const source = await getStageOutputDesktopSource();
    if (!source?.id) {
        logBroadcastRoomDebug('bot-stage-recording-fallback-to-canvas');
        return captureStageOutputCanvasForBotRecording();
    }
    return navigator.mediaDevices.getUserMedia({
        audio: false,
        video: {
            mandatory: {
                chromeMediaSource: 'desktop',
                chromeMediaSourceId: source.id,
                minWidth: 1280,
                maxWidth: 1920,
                minHeight: 720,
                maxHeight: 1080,
                maxFrameRate: 30
            }
        }
    });
}

function drawVideoIntoCanvasContext(ctx, video, sourceRect, targetRect) {
    const videoWidth = Number(video.videoWidth || 0);
    const videoHeight = Number(video.videoHeight || 0);
    if (!videoWidth || !videoHeight || !targetRect.width || !targetRect.height) {
        return false;
    }
    const objectFit = String(video.ownerDocument.defaultView?.getComputedStyle(video).objectFit || 'cover');
    let drawWidth = targetRect.width;
    let drawHeight = targetRect.height;
    if (objectFit === 'contain') {
        const scale = Math.min(targetRect.width / videoWidth, targetRect.height / videoHeight);
        drawWidth = videoWidth * scale;
        drawHeight = videoHeight * scale;
    } else {
        const scale = Math.max(targetRect.width / videoWidth, targetRect.height / videoHeight);
        drawWidth = videoWidth * scale;
        drawHeight = videoHeight * scale;
    }
    const dx = targetRect.x + (targetRect.width - drawWidth) / 2;
    const dy = targetRect.y + (targetRect.height - drawHeight) / 2;
    ctx.save();
    ctx.beginPath();
    ctx.rect(targetRect.x, targetRect.y, targetRect.width, targetRect.height);
    ctx.clip();
    ctx.fillStyle = '#000';
    ctx.fillRect(targetRect.x, targetRect.y, targetRect.width, targetRect.height);
    try {
        ctx.drawImage(video, dx, dy, drawWidth, drawHeight);
    } catch (_error) {
        ctx.restore();
        return false;
    }
    ctx.restore();
    return true;
}

function drawStageCaptionIntoCanvas(ctx, captionEl, scaleX, scaleY) {
    if (!captionEl || captionEl.hidden) {
        return;
    }
    const text = String(captionEl.textContent || '').trim();
    if (!text) {
        return;
    }
    const rect = captionEl.getBoundingClientRect();
    const x = rect.left * scaleX;
    const y = rect.top * scaleY;
    const width = rect.width * scaleX;
    const height = rect.height * scaleY;
    const fontSize = Math.max(22, Math.round(34 * scaleY));
    ctx.save();
    ctx.fillStyle = 'rgba(0, 0, 0, 0.78)';
    ctx.beginPath();
    ctx.roundRect?.(x, y, width, height, 14 * Math.min(scaleX, scaleY));
    if (typeof ctx.roundRect === 'function') {
        ctx.fill();
    } else {
        ctx.fillRect(x, y, width, height);
    }
    ctx.fillStyle = '#fff';
    ctx.font = `700 ${fontSize}px Segoe UI, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const lines = text.split(/\s+/).reduce((acc, word) => {
        const current = acc[acc.length - 1] || '';
        const next = current ? `${current} ${word}` : word;
        if (ctx.measureText(next).width > width - 36 && current) {
            acc.push(word);
        } else if (acc.length) {
            acc[acc.length - 1] = next;
        } else {
            acc.push(next);
        }
        return acc;
    }, []);
    const lineHeight = fontSize * 1.25;
    const firstY = y + height / 2 - ((lines.length - 1) * lineHeight) / 2;
    lines.slice(0, 3).forEach((line, index) => {
        ctx.fillText(line, x + width / 2, firstY + index * lineHeight, width - 36);
    });
    ctx.restore();
}

function drawStageOutputFrameToCanvas(canvas) {
    const doc = getStageOutputDocument();
    if (!doc || !canvas) {
        return 0;
    }
    const rawWidth = Math.max(640, Number(doc.defaultView?.innerWidth || 1280));
    const rawHeight = Math.max(360, Number(doc.defaultView?.innerHeight || 720));
    const width = rawWidth % 2 === 0 ? rawWidth : rawWidth - 1;
    const height = rawHeight % 2 === 0 ? rawHeight : rawHeight - 1;
    if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
    }
    const ctx = canvas.getContext('2d');
    if (!ctx) {
        return 0;
    }
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    const scaleX = canvas.width / width;
    const scaleY = canvas.height / height;
    const videos = Array.from(doc.querySelectorAll('video'))
        .filter((video) => {
            const rect = video.getBoundingClientRect();
            const style = doc.defaultView?.getComputedStyle(video);
            return rect.width > 2
                && rect.height > 2
                && style?.display !== 'none'
                && style?.visibility !== 'hidden'
                && Number(video.videoWidth || 0) > 0
                && Number(video.videoHeight || 0) > 0;
        })
        .sort((a, b) => {
            const za = Number(doc.defaultView?.getComputedStyle(a.closest('.host-camera-pip, .sign-interpreter-overlay, .scene-slot-frame, .frame, .remote-section') || a).zIndex || 0);
            const zb = Number(doc.defaultView?.getComputedStyle(b.closest('.host-camera-pip, .sign-interpreter-overlay, .scene-slot-frame, .frame, .remote-section') || b).zIndex || 0);
            return za - zb;
        });
    let drawnVideoCount = 0;
    videos.forEach((video) => {
        const rect = video.getBoundingClientRect();
        const drawn = drawVideoIntoCanvasContext(ctx, video, rect, {
            x: rect.left * scaleX,
            y: rect.top * scaleY,
            width: rect.width * scaleX,
            height: rect.height * scaleY
        });
        if (drawn) {
            drawnVideoCount += 1;
        }
    });
    drawStageCaptionIntoCanvas(ctx, doc.getElementById('stage-output-caption-overlay'), scaleX, scaleY);
    return drawnVideoCount;
}

async function captureStageOutputCanvasForBotRecording() {
    await ensureStageOutputWindow({ focus: false });
    await syncStageOutputWindowMedia().catch(() => {});
    await waitForStageOutputWindowReadyForObsCapture({
        audioExpected: false,
        visualExpected: true,
        timeoutMs: 3600
    });
    const canvas = document.createElement('canvas');
    state.recording.botCanvas = canvas;
    drawStageOutputFrameToCanvas(canvas);
    if (state.recording.botCanvasDrawTimer) {
        clearInterval(state.recording.botCanvasDrawTimer);
    }
    if (state.recording.botCanvasFrameRequest) {
        cancelAnimationFrame(state.recording.botCanvasFrameRequest);
        state.recording.botCanvasFrameRequest = null;
    }
    const targetFps = 15;
    let lastDrawAt = 0;
    const drawLoop = (timestamp) => {
        if (!state.recording.botPreparing && !state.recording.botActive) {
            state.recording.botCanvasFrameRequest = null;
            return;
        }
        if (!lastDrawAt || timestamp - lastDrawAt >= (1000 / targetFps)) {
            lastDrawAt = timestamp;
            drawStageOutputFrameToCanvas(canvas);
        }
        state.recording.botCanvasFrameRequest = requestAnimationFrame(drawLoop);
    };
    state.recording.botCanvasFrameRequest = requestAnimationFrame(drawLoop);
    const stream = canvas.captureStream(targetFps);
    logBroadcastRoomDebug('bot-stage-recording-canvas-capture-started', {
        width: canvas.width,
        height: canvas.height,
        fps: targetFps
    });
    return stream;
}

function buildBotStageRecordingAudioStream() {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) {
        return null;
    }
    const sourceTracks = [
        ...getTranslationTrackMediaStreamTracks(),
        state.liveRoom.localShareAudioTrack?.mediaStreamTrack || null,
        state.liveRoom.effectAudioTrack || null
    ].filter((track, index, allTracks) => (
        track
        && track.readyState !== 'ended'
        && allTracks.findIndex((candidate) => candidate && candidate.id === track.id) === index
    ));
    if (!sourceTracks.length) {
        return null;
    }
    const audioContext = new AudioContextClass();
    const destination = audioContext.createMediaStreamDestination();
    const nodes = [];
    const clonedTracks = [];
    sourceTracks.forEach((track) => {
        let usableTrack = track;
        try {
            usableTrack = typeof track.clone === 'function' ? track.clone() : track;
        } catch (_error) {
            usableTrack = track;
        }
        if (usableTrack !== track) {
            clonedTracks.push(usableTrack);
        }
        const sourceNode = audioContext.createMediaStreamSource(new MediaStream([usableTrack]));
        const gainNode = audioContext.createGain();
        gainNode.gain.value = 1;
        sourceNode.connect(gainNode);
        gainNode.connect(destination);
        nodes.push(sourceNode, gainNode);
    });
    state.recording.botAudioContext = audioContext;
    state.recording.botAudioNodes = nodes;
    state.recording.botClonedTracks = clonedTracks;
    audioContext.resume?.().catch?.(() => {});
    return destination.stream;
}

function cleanupBotStageRecordingResources({ stopRecorder = false } = {}) {
    if (stopRecorder && state.recording.botRecorder && state.recording.botRecorder.state !== 'inactive') {
        try { state.recording.botRecorder.stop(); } catch (_error) {}
    }
    if (state.recording.botStream) {
        state.recording.botStream.getTracks().forEach((track) => {
            try { track.stop(); } catch (_error) {}
        });
    }
    if (state.recording.botCanvasDrawTimer) {
        clearInterval(state.recording.botCanvasDrawTimer);
    }
    if (state.recording.botCanvasFrameRequest) {
        cancelAnimationFrame(state.recording.botCanvasFrameRequest);
    }
    state.recording.botCanvasDrawTimer = null;
    state.recording.botCanvasFrameRequest = null;
    state.recording.botCanvas = null;
    (state.recording.botClonedTracks || []).forEach((track) => {
        try { track.stop(); } catch (_error) {}
    });
    try {
        state.recording.botAudioNodes?.forEach((node) => {
            try { node.disconnect(); } catch (_error) {}
        });
    } catch (_error) {}
    if (state.recording.botAudioContext && state.recording.botAudioContext.state !== 'closed') {
        state.recording.botAudioContext.close().catch(() => {});
    }
    state.recording.botStream = null;
    state.recording.botAudioContext = null;
    state.recording.botAudioNodes = [];
    state.recording.botClonedTracks = [];
}

async function startBotStageRecording() {
    if (state.recording.active || state.recording.botActive || state.recording.checking) {
        setStatus(t('broadcast_room.status_bot_stage_recording_busy', 'Başka bir kayıt işlemi zaten sürüyor.'));
        return;
    }
    if (typeof MediaRecorder === 'undefined') {
        setStatus(t('broadcast_room.status_bot_stage_recording_unsupported', 'Bu sistemde bot kaydı için MediaRecorder desteği bulunamadı.'));
        return;
    }

    state.recording.checking = true;
    state.recording.botPreparing = true;
    renderRecordingState();
    try {
        await syncHostLiveKitMedia({ skipShareSync: true }).catch(() => {});
        const videoStream = await captureStageOutputWindowForBotRecording();
        const audioStream = buildBotStageRecordingAudioStream();
        const tracks = [
            ...videoStream.getVideoTracks(),
            ...(audioStream ? audioStream.getAudioTracks() : [])
        ];
        if (!tracks.some((track) => track.kind === 'video')) {
            throw new Error('stage_video_track_missing');
        }
        const mixedStream = new MediaStream(tracks);
        const mimeType = getPreferredBotRecordingMimeType();
        const recorder = mimeType
            ? new MediaRecorder(mixedStream, { mimeType, videoBitsPerSecond: 2500000, audioBitsPerSecond: 160000 })
            : new MediaRecorder(mixedStream);
        const outputPath = getBotStageRecordingOutputPath();
        state.recording.botRecorder = recorder;
        state.recording.botStream = mixedStream;
        state.recording.botChunks = [];
        state.recording.botOutputPath = outputPath;
        state.recording.botStartedAt = Date.now();
        state.recording.lastStartedAt = state.recording.botStartedAt;
        resetRecordingTimeline();
        resetDubRecordingArchive();
        state.recording.botStopPromise = new Promise((resolve, reject) => {
            recorder.addEventListener('dataavailable', (event) => {
                if (event.data && event.data.size > 0) {
                    state.recording.botChunks.push(event.data);
                }
            });
            recorder.addEventListener('stop', async () => {
                try {
                    const blob = new Blob(state.recording.botChunks, { type: recorder.mimeType || 'video/webm' });
                    const buffer = Buffer.from(await blob.arrayBuffer());
                    fs.writeFileSync(outputPath, buffer);
                    resolve(outputPath);
                } catch (error) {
                    reject(error);
                }
            }, { once: true });
            recorder.addEventListener('error', (event) => {
                reject(event.error || new Error('bot_stage_recording_recorder_error'));
            }, { once: true });
        });
        state.recording.botActive = true;
        state.recording.botPreparing = false;
        state.stageOutput.keepOpenUntil = 0;
        state.recording.outputPath = '';
        state.recording.dubSegmentInputPath = '';
        recorder.start(1000);
        recordRecordingTimelineEvent('bot_recording_started', { force: true });
        addDiagnosticEvent('broadcast', t('broadcast_room.status_bot_stage_recording_started', 'Bot sahne kaydı başlatıldı.'));
        setStatus(t('broadcast_room.status_bot_stage_recording_started', 'Bot sahne kaydı başlatıldı.'));
    } catch (error) {
        cleanupBotStageRecordingResources();
        state.recording.botActive = false;
        // Keep the output window open briefly for diagnostics; the next retry can reuse it.
        state.stageOutput.keepOpenUntil = Date.now() + 20000;
        state.recording.botStartedAt = 0;
        setStatus(t('broadcast_room.status_bot_stage_recording_start_failed', 'Bot kaydı başlatılamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        }));
    } finally {
        state.recording.botPreparing = false;
        state.recording.checking = false;
        renderRecordingState();
    }
}

async function stopBotStageRecording() {
    if (!state.recording.botActive || !state.recording.botRecorder) {
        setStatus(t('broadcast_room.status_bot_stage_recording_not_active', 'Süren bir bot kaydı yok.'));
        return;
    }
    state.recording.checking = true;
    renderRecordingState();
    try {
        flushGeminiVoiceTranslationRecordingBuffer();
        recordRecordingTimelineEvent('bot_recording_stopping', { force: true });
        const recorder = state.recording.botRecorder;
        if (recorder.state !== 'inactive') {
            recorder.stop();
        }
        const outputPath = await state.recording.botStopPromise;
        state.recording.botActive = false;
        state.recording.botPreparing = false;
        state.recording.outputPath = String(outputPath || state.recording.botOutputPath || '');
        state.recording.dubSegmentInputPath = state.recording.outputPath;
        state.recording.lastState = 'stopped';
        const timelinePath = writeRecordingTimelineFile(state.recording.outputPath);
        if (timelinePath) {
            addDiagnosticEvent('broadcast', t('broadcast_room.status_recording_timeline_saved', 'Kayıt sahne zaman çizelgesi kaydedildi: {path}', {
                path: timelinePath
            }));
        }
        cleanupBotStageRecordingResources();
        state.recording.botRecorder = null;
        state.recording.botChunks = [];
        state.recording.botStartedAt = 0;
        state.recording.botStopPromise = null;
        addDiagnosticEvent('broadcast', t('broadcast_room.status_bot_stage_recording_stopped', 'Bot sahne kaydı durduruldu: {path}', {
            path: state.recording.outputPath
        }));
        setStatus(t('broadcast_room.status_bot_stage_recording_stopped', 'Bot sahne kaydı durduruldu: {path}', {
            path: state.recording.outputPath
        }));
    } catch (error) {
        setStatus(t('broadcast_room.status_bot_stage_recording_stop_failed', 'Bot kaydı durdurulamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        }));
    } finally {
        state.recording.checking = false;
        renderRecordingState();
    }
}

async function toggleBotStageRecordingFromShortcut() {
    if (state.recording.checking) {
        setStatus(t('broadcast_room.status_bot_stage_recording_busy', 'Başka bir kayıt işlemi zaten sürüyor.'));
        return;
    }
    if (state.recording.botActive) {
        await stopBotStageRecording();
        return;
    }
    await startBotStageRecording();
}

async function toggleLiveTranslationFromShortcut() {
    if (!state.translation.enabled) {
        setStatus(t('broadcast_room.status_translation_shortcut_disabled', 'Canlı çeviri veya altyazı etkin değil. Önce canlı çeviri/altyazı bölümündeki etkinleştirme onay kutusunu açın.'));
        return;
    }
    if (state.translation.running || state.translation.waitingForAudio || state.translation.finalizing) {
        await stopLiveTranslationPrototype();
        return;
    }
    await startLiveTranslationPrototype();
}

async function openRecordingFolder() {
    if (!state.recording.outputPath) {
        setStatus(t('broadcast_room.status_recording_output_missing', 'Henüz açılacak bir kayıt dosyası yok.'));
        return;
    }

    const normalizedOutputPath = process.platform === 'win32'
        ? path.win32.normalize(state.recording.outputPath)
        : state.recording.outputPath;
    const folder = path.dirname(normalizedOutputPath);

    try {
        if (process.platform === 'win32') {
            spawn('explorer.exe', ['/select,', normalizedOutputPath], {
                detached: true,
                stdio: 'ignore'
            }).unref();
            setStatus(t('broadcast_room.status_recording_file_revealed', 'Kayıt dosyası klasöründe gösteriliyor.'));
        } else {
            await shell.openPath(folder);
            setStatus(t('broadcast_room.status_recording_folder_opened', 'Kayıt klasörü açıldı.'));
        }
    } catch (_error) {
        shell.showItemInFolder(state.recording.outputPath);
        setStatus(t('broadcast_room.status_recording_file_revealed', 'Kayıt dosyası klasöründe gösteriliyor.'));
    }
}

function copyRecordingPath() {
    if (!state.recording.outputPath) {
        setStatus(t('broadcast_room.status_recording_output_missing', 'Henüz açılacak bir kayıt dosyası yok.'));
        return;
    }

    clipboard.writeText(state.recording.outputPath);
    setStatus(t('broadcast_room.status_recording_path_copied', 'Kayıt yolu panoya kopyalandı.'));
}

function buildDubbedRecordingOutputPath(inputPath) {
    const parsed = path.parse(inputPath);
    const extension = parsed.ext || '.mp4';
    return path.join(parsed.dir, `${parsed.name}-dublajli${extension}`);
}

function buildLiveInterpreterRecordingOutputPath(inputPath) {
    const parsed = path.parse(inputPath);
    const extension = parsed.ext || '.mp4';
    return path.join(parsed.dir, `${parsed.name}-canli-ceviri-kanalli${extension}`);
}

function buildSingleDubbedRecordingOutputPath(inputPath) {
    const parsed = path.parse(inputPath);
    const extension = String(parsed.ext || '').toLowerCase() === '.webm'
        ? '.mp4'
        : (parsed.ext || '.mp4');
    return path.join(parsed.dir, `${parsed.name}-dublajli-tek-ses${extension}`);
}

function buildRecordingTimelineOutputPath(inputPath) {
    const parsed = path.parse(inputPath || `broadcast-room-${Date.now()}.mp4`);
    return path.join(parsed.dir || os.tmpdir(), `${parsed.name}-timeline.json`);
}

function getRecordingTimelineOffsetSeconds(timestamp = Date.now()) {
    const startedAt = Number(state.recording.lastStartedAt || state.recording.startedAt || 0);
    if (!startedAt) {
        return 0;
    }
    return Math.max(0, (Number(timestamp || Date.now()) - startedAt) / 1000);
}

function buildRecordingTimelineSnapshot(reason = 'snapshot') {
    const sceneState = buildSceneStatePayloadForLiveRoom();
    const activeShares = buildHostActiveShareSources().map((source) => ({
        id: String(source.id || ''),
        name: String(source.name || ''),
        shareKind: String(source.shareKind || ''),
        includeAudio: state.hostLocalShareAudioById[source.id] === true
    }));
    const participants = Object.values(state.liveRoom.remoteParticipants || {}).map((participantState) => ({
        identity: String(participantState.identity || ''),
        name: getLiveRemoteParticipantLabel(participantState),
        videoTracks: getPreferredLiveVideoTracks(participantState).map((trackState) => ({
            sid: String(trackState.sid || ''),
            source: String(trackState.source || ''),
            label: getLiveTrackSourceLabel(trackState),
            isShare: isLiveShareSource(trackState)
        })),
        audioTracks: (Array.isArray(participantState.audioTracks) ? participantState.audioTracks : []).map((trackState) => ({
            sid: String(trackState.sid || ''),
            source: String(trackState.source || ''),
            label: getLiveTrackSourceLabel(trackState)
        }))
    }));

    return {
        reason: String(reason || 'snapshot'),
        scene: sceneState,
        activeShares,
        participants,
        host: {
            cameraEnabled: !!els.hostCameraEnabled?.checked,
            microphoneEnabled: !!els.hostMicrophoneEnabled?.checked,
            cameraLabel: getSelectedCameraLabel(),
            microphoneLabel: getSelectedMicrophoneLabel()
        }
    };
}

function resetRecordingTimeline() {
    state.recording.timelineEvents = [];
    state.recording.timelineLastSignature = '';
    state.recording.timelineOutputPath = '';
}

function recordRecordingTimelineEvent(reason = 'snapshot', { force = false } = {}) {
    if (!state.recording.active && !force) {
        return;
    }
    const timestamp = Date.now();
    const snapshot = buildRecordingTimelineSnapshot(reason);
    const signature = JSON.stringify(snapshot);
    if (!force && signature === state.recording.timelineLastSignature) {
        return;
    }
    state.recording.timelineLastSignature = signature;
    state.recording.timelineEvents.push({
        at: timestamp,
        offset: Number(getRecordingTimelineOffsetSeconds(timestamp).toFixed(3)),
        ...snapshot
    });
}

function writeRecordingTimelineFile(outputPath = '') {
    const targetRecordingPath = String(outputPath || state.recording.outputPath || '').trim();
    if (!targetRecordingPath || !Array.isArray(state.recording.timelineEvents) || state.recording.timelineEvents.length === 0) {
        return '';
    }
    const timelinePath = buildRecordingTimelineOutputPath(targetRecordingPath);
    const payload = {
        version: 1,
        createdAt: Date.now(),
        roomId: String(state.roomState.roomId || ''),
        recordingPath: targetRecordingPath,
        startedAt: Number(state.recording.lastStartedAt || 0),
        endedAt: Date.now(),
        events: state.recording.timelineEvents
    };
    fs.writeFileSync(timelinePath, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
    state.recording.timelineOutputPath = timelinePath;
    return timelinePath;
}

function buildElevenLabsDubbedRecordingOutputPath(inputPath) {
    const parsed = path.parse(inputPath);
    const extension = parsed.ext || '.mp4';
    return path.join(parsed.dir, `${parsed.name}-elevenlabs-dublaj${extension}`);
}

function buildRebalancedDubbedRecordingOutputPath(inputPath) {
    const parsed = path.parse(inputPath);
    const extension = parsed.ext || '.mp4';
    return path.join(parsed.dir, `${parsed.name}-yeniden-dengeli${extension}`);
}

function getElevenLabsDubbingInputPath() {
    return String(state.recording.elevenLabsDubbingInputPath || state.recording.outputPath || '').trim();
}

function getDubSegmentInputPath() {
    return String(state.recording.dubSegmentInputPath || state.recording.outputPath || '').trim();
}

function getDubRecordingSegmentsForOutput() {
    const timingOffset = getDubOutputTimingOffsetSeconds();
    return Array.isArray(state.translation.dubRecordingSegments)
        ? state.translation.dubRecordingSegments
            .filter((segment) => segment?.path)
            .map((segment) => ({
                ...segment,
                offset: Math.max(0, Number(segment.offset || 0) + timingOffset),
                sourceDuration: Math.max(0, Number(segment.sourceDuration || 0) || 0)
            }))
        : [];
}

function getDubOutputTimingOffsetSeconds() {
    const preset = String(state.recording.dubOutputTiming || 'on_time');
    if (preset === 'later') {
        return 2;
    }
    if (preset === 'slightly_early') {
        return -0.6;
    }
    if (preset === 'on_time') {
        return 0;
    }
    return 1.1;
}

function getDubOutputOriginalVolumeValue() {
    const preset = String(state.recording.dubOutputOriginalVolume || 'medium');
    if (preset === 'medium') {
        return 0.16;
    }
    if (preset === 'low') {
        return 0.1;
    }
    return 0.06;
}

function getDubOutputDubVolumeValue() {
    const preset = String(state.recording.dubOutputDubVolume || 'medium');
    if (preset === 'very_high') {
        return 16;
    }
    if (preset === 'medium') {
        return 6;
    }
    return 10;
}

function formatDubbingEstimateDuration(seconds) {
    const safeSeconds = Math.max(0, Math.round(Number(seconds || 0)));
    const minutes = Math.floor(safeSeconds / 60);
    const rest = safeSeconds % 60;
    return t('broadcast_room.elevenlabs_dubbing_duration_format', '{minutes} dakika {seconds} saniye', {
        minutes,
        seconds: rest
    });
}

function estimateElevenLabsDubbingCredits(durationSeconds) {
    return Math.ceil((Math.max(1, Number(durationSeconds || 0)) / 60) * 3000);
}

function getRebalancePreviewStartSeconds() {
    return Math.max(0, Number(els.rebalancePreviewStart?.value || 0) || 0);
}

function getImportedDubbedRebalanceOptions() {
    return {
        originalVolume: getDubOutputOriginalVolumeValue(),
        dubVolume: getDubOutputDubVolumeValue(),
        originalRemovalVolume: 0.18,
        originalAudioIndex: 0,
        dubAudioIndex: 1
    };
}

function stopRebalancePreviewAudio() {
    if (state.recording.rebalancePreviewAudioEl) {
        try {
            state.recording.rebalancePreviewAudioEl.pause();
            state.recording.rebalancePreviewAudioEl.removeAttribute('src');
            state.recording.rebalancePreviewAudioEl.load();
        } catch (_error) {}
    }
    if (state.recording.rebalancePreviewUrl) {
        try { URL.revokeObjectURL(state.recording.rebalancePreviewUrl); } catch (_error) {}
        state.recording.rebalancePreviewUrl = '';
    }
}

async function importDubbedRecordingForRebalance() {
    const result = await ipcRenderer.invoke('open-file-dialog', {
        title: t('broadcast_room.import_dubbed_recording_dialog_title', 'İki ses parçalı dublajlı kaydı seçin'),
        properties: ['openFile'],
        filters: [
            { name: 'Video', extensions: ['mp4', 'mkv', 'mov', 'webm'] }
        ]
    });
    const filePath = Array.isArray(result?.filePaths) ? result.filePaths[0] : '';
    if (!filePath) {
        return;
    }
    const metadataResponse = await ipcRenderer.invoke('get-video-metadata', filePath).catch((error) => ({
        success: false,
        error: error?.message || error || 'metadata_failed'
    }));
    const streams = Array.isArray(metadataResponse?.data?.streams)
        ? metadataResponse.data.streams
        : Array.isArray(metadataResponse?.metadata?.streams)
            ? metadataResponse.metadata.streams
            : Array.isArray(metadataResponse?.streams)
                ? metadataResponse.streams
                : [];
    const audioCount = streams.filter((stream) => stream?.codec_type === 'audio').length;
    state.recording.importedDubbedPath = filePath;
    state.recording.importedDubbedAudioCount = audioCount;
    renderRecordingState();
    if (audioCount < 2) {
        setStatus(t('broadcast_room.status_rebalance_import_needs_two_tracks', 'Seçilen dosyada en az iki ses parçası bulunamadı.'));
        return;
    }
    setStatus(t('broadcast_room.status_rebalance_imported', 'İki ses parçalı kayıt içe aktarıldı. Düzeyleri seçip önizleme yapabilirsiniz.'));
}

async function previewRebalancedDubbedRecording() {
    if (!state.recording.importedDubbedPath) {
        setStatus(t('broadcast_room.rebalance_import_empty', 'Henüz iki ses parçalı kayıt içe aktarılmadı.'));
        return;
    }
    state.recording.checking = true;
    renderRecordingState();
    setStatus(t('broadcast_room.status_rebalance_preview_creating', 'Denge önizlemesi hazırlanıyor...'));
    try {
        const response = await ipcRenderer.invoke('ffmpeg-preview-rebalanced-dubbed-recording', {
            videoPath: state.recording.importedDubbedPath,
            startTime: getRebalancePreviewStartSeconds(),
            duration: 20,
            ...getImportedDubbedRebalanceOptions()
        });
        if (!response?.success) {
            throw new Error(response?.error || 'rebalance_preview_failed');
        }
        stopRebalancePreviewAudio();
        const audio = state.recording.rebalancePreviewAudioEl || new Audio();
        state.recording.rebalancePreviewAudioEl = audio;
        state.recording.rebalancePreviewUrl = `file:///${String(response.outputPath || '').replace(/\\/g, '/')}`;
        audio.src = state.recording.rebalancePreviewUrl;
        audio.volume = 1;
        await audio.play();
        setStatus(t('broadcast_room.status_rebalance_preview_playing', 'Denge önizlemesi oynatılıyor.'));
    } catch (error) {
        setStatus(t('broadcast_room.status_rebalance_preview_failed', 'Denge önizlemesi hazırlanamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        }));
    } finally {
        state.recording.checking = false;
        renderRecordingState();
    }
}

async function exportRebalancedDubbedRecording() {
    if (!state.recording.importedDubbedPath) {
        setStatus(t('broadcast_room.rebalance_import_empty', 'Henüz iki ses parçalı kayıt içe aktarılmadı.'));
        return;
    }
    state.recording.checking = true;
    renderRecordingState();
    setStatus(t('broadcast_room.status_rebalance_export_creating', 'Yeniden dengelenmiş tek sesli kopya oluşturuluyor...'));
    try {
        const response = await ipcRenderer.invoke('ffmpeg-create-rebalanced-dubbed-recording', {
            videoPath: state.recording.importedDubbedPath,
            outputPath: buildRebalancedDubbedRecordingOutputPath(state.recording.importedDubbedPath),
            trackTitle: t('broadcast_room.dub_track_title', 'Dublaj + Özgün'),
            ...getImportedDubbedRebalanceOptions()
        });
        if (!response?.success) {
            throw new Error(response?.error || 'rebalance_export_failed');
        }
        state.recording.outputPath = String(response.outputPath || state.recording.outputPath || '');
        renderRecordingState();
        setStatus(t('broadcast_room.status_rebalance_export_created', 'Yeniden dengelenmiş tek sesli kopya oluşturuldu: {path}', {
            path: state.recording.outputPath
        }));
    } catch (error) {
        setStatus(t('broadcast_room.status_rebalance_export_failed', 'Yeniden dengelenmiş kopya oluşturulamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        }));
    } finally {
        state.recording.checking = false;
        renderRecordingState();
    }
}

async function importRecordingForElevenLabsDubbing() {
    const result = await ipcRenderer.invoke('open-file-dialog', {
        title: t('broadcast_room.import_elevenlabs_dubbing_recording_dialog_title', 'ElevenLabs dublaj için kayıt dosyasını seçin'),
        properties: ['openFile'],
        filters: [
            { name: 'Video', extensions: ['mp4', 'mkv', 'mov', 'webm'] }
        ]
    });
    const filePath = Array.isArray(result?.filePaths) ? result.filePaths[0] : '';
    if (!filePath) {
        return;
    }
    state.recording.elevenLabsDubbingInputPath = filePath;
    state.recording.elevenLabsDubbingEstimateStatus = '';
    state.recording.elevenLabsDubbingStatus = t('broadcast_room.status_elevenlabs_dubbing_imported', 'ElevenLabs dublaj için kayıt dosyası seçildi.');
    renderRecordingState();
    setStatus(state.recording.elevenLabsDubbingStatus);
}

async function checkElevenLabsDubbingEstimate() {
    const inputPath = getElevenLabsDubbingInputPath();
    if (!inputPath) {
        setStatus(t('broadcast_room.status_recording_output_missing', 'Henüz açılacak bir kayıt dosyası yok.'));
        return;
    }
    state.recording.checking = true;
    state.recording.elevenLabsDubbingEstimateStatus = t('broadcast_room.elevenlabs_dubbing_estimate_checking', 'Süre ve kredi bilgisi kontrol ediliyor...');
    renderRecordingState();
    try {
        const metadataResponse = await ipcRenderer.invoke('get-video-metadata', inputPath);
        if (!metadataResponse?.success) {
            throw new Error(metadataResponse?.error || 'metadata_failed');
        }
        const metadata = metadataResponse.data || metadataResponse.metadata || metadataResponse;
        const durationSeconds = Number(metadata?.duration || metadata?.format?.duration || 0) || 0;
        const estimatedCredits = estimateElevenLabsDubbingCredits(durationSeconds);
        const subscriptionResponse = await ipcRenderer.invoke('elevenlabs-get-subscription-info');
        if (!subscriptionResponse?.success) {
            throw new Error(subscriptionResponse?.error || 'subscription_failed');
        }
        const subscription = subscriptionResponse.subscription || {};
        const used = Number(subscription.character_count || 0) || 0;
        const limit = Number(subscription.character_limit || 0) || 0;
        const remaining = Math.max(0, limit - used);
        const overage = subscription.max_credit_limit_extension;
        const overageAllowed = overage === 'unlimited' || Number(overage || 0) > 0 || subscription.can_extend_character_limit === true;
        const key = remaining >= estimatedCredits
            ? 'broadcast_room.elevenlabs_dubbing_estimate_enough'
            : overageAllowed
                ? 'broadcast_room.elevenlabs_dubbing_estimate_overage_possible'
                : 'broadcast_room.elevenlabs_dubbing_estimate_not_enough';
        const fallback = remaining >= estimatedCredits
            ? 'Video süresi: {duration}. Tahmini kredi: {estimated}. Kalan kredi: {remaining}. Kredi yeterli görünüyor.'
            : overageAllowed
                ? 'Video süresi: {duration}. Tahmini kredi: {estimated}. Kalan kredi: {remaining}. Kalan kredi yetmeyebilir, ancak hesabınızda aşım/ek kullanım izni görünüyor.'
                : 'Video süresi: {duration}. Tahmini kredi: {estimated}. Kalan kredi: {remaining}. Kredi yeterli görünmüyor.';
        state.recording.elevenLabsDubbingEstimateStatus = t(key, fallback, {
            duration: formatDubbingEstimateDuration(durationSeconds),
            estimated: estimatedCredits,
            remaining
        });
        setStatus(state.recording.elevenLabsDubbingEstimateStatus);
    } catch (error) {
        state.recording.elevenLabsDubbingEstimateStatus = t('broadcast_room.elevenlabs_dubbing_estimate_failed', 'Süre ve kredi tahmini alınamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        });
        setStatus(state.recording.elevenLabsDubbingEstimateStatus);
    } finally {
        state.recording.checking = false;
        renderRecordingState();
    }
}

async function addDubTrackToRecording() {
    const inputPath = getDubSegmentInputPath();
    if (!inputPath) {
        setStatus(t('broadcast_room.status_recording_output_missing', 'Henüz açılacak bir kayıt dosyası yok.'));
        return;
    }
    const segments = getDubRecordingSegmentsForOutput();
    if (!segments.length) {
        setStatus(t('broadcast_room.status_dub_track_no_segments', 'Bu kayıt için eklenebilir dublaj parçası yok.'));
        return;
    }

    state.recording.checking = true;
    renderRecordingState();
    setStatus(t('broadcast_room.status_dub_track_adding', 'Dublaj ayrı ses parçası olarak kayda ekleniyor...'));
    try {
        const response = await ipcRenderer.invoke('ffmpeg-add-separate-audio-track', {
            videoPath: inputPath,
            segments,
            outputPath: buildDubbedRecordingOutputPath(inputPath),
            trackTitle: t('broadcast_room.dub_track_title', 'Dublaj + Özgün'),
            originalUnderVolume: getDubOutputOriginalVolumeValue(),
            dubVolume: getDubOutputDubVolumeValue()
        });
        if (!response?.success) {
            throw new Error(response?.error || 'dub_track_add_failed');
        }
        state.recording.outputPath = String(response.outputPath || state.recording.outputPath);
        renderRecordingState();
        setStatus(t('broadcast_room.status_dub_track_added', 'Dublaj ayrı ses parçası olarak eklendi: {path}', {
            path: state.recording.outputPath
        }));
    } catch (error) {
        setStatus(t('broadcast_room.status_dub_track_add_failed', 'Dublaj ses parçası eklenemedi: {error}', {
            error: error?.message || error || 'unknown_error'
        }));
    } finally {
        state.recording.checking = false;
        renderRecordingState();
    }
}

