async function createSingleDubbedRecording() {
    const inputPath = getDubSegmentInputPath();
    if (!inputPath) {
        setStatus(t('broadcast_room.status_recording_output_missing', 'Henüz açılacak bir kayıt dosyası yok.'));
        return;
    }
    flushGeminiVoiceTranslationRecordingBuffer();
    const segments = getDubRecordingSegmentsForOutput();
    const continuousGeminiDubPath = writeGeminiVoiceTranslationContinuousDubAudio()
        || (String(state.translation.service || '') === 'gemini'
            ? writeContinuousDubAudioFromSegments(segments)
            : '');
    if (!continuousGeminiDubPath && !segments.length) {
        setStatus(t('broadcast_room.status_dub_track_no_segments', 'Bu kayıt için eklenebilir dublaj parçası yok.'));
        return;
    }

    state.recording.checking = true;
    renderRecordingState();
    setStatus(t('broadcast_room.status_single_dubbed_recording_creating', 'Dublajlı tek sesli kopya oluşturuluyor...'));
    try {
        logBroadcastRoomDebug('single-dubbed-recording-create-start', {
            inputPath,
            segmentCount: segments.length,
            continuousGeminiDub: !!continuousGeminiDubPath,
            outputPath: buildSingleDubbedRecordingOutputPath(inputPath)
        });
        const response = continuousGeminiDubPath
            ? await ipcRenderer.invoke('ffmpeg-create-single-dubbed-recording-from-audio', {
                videoPath: inputPath,
                dubAudioPath: continuousGeminiDubPath,
                outputPath: buildSingleDubbedRecordingOutputPath(inputPath),
                trackTitle: t('broadcast_room.dub_track_title', 'Dublaj + Özgün'),
                originalUnderVolume: getDubOutputOriginalVolumeValue(),
                dubVolume: getDubOutputDubVolumeValue()
            })
            : await ipcRenderer.invoke('ffmpeg-create-single-dubbed-recording', {
                videoPath: inputPath,
                segments,
                outputPath: buildSingleDubbedRecordingOutputPath(inputPath),
                trackTitle: t('broadcast_room.dub_track_title', 'Dublaj + Özgün'),
                originalUnderVolume: getDubOutputOriginalVolumeValue(),
                dubVolume: getDubOutputDubVolumeValue()
            });
        if (!response?.success) {
            throw new Error(response?.error || 'single_dubbed_recording_failed');
        }
        logBroadcastRoomDebug('single-dubbed-recording-create-done', {
            outputPath: response.outputPath || ''
        });
        state.recording.outputPath = String(response.outputPath || state.recording.outputPath);
        renderRecordingState();
        setStatus(t('broadcast_room.status_single_dubbed_recording_created', 'Dublajlı tek sesli kopya oluşturuldu: {path}', {
            path: state.recording.outputPath
        }));
    } catch (error) {
        logBroadcastRoomDebug('single-dubbed-recording-create-failed', {
            error: error?.message || String(error || '')
        });
        setStatus(t('broadcast_room.status_single_dubbed_recording_failed', 'Dublajlı tek sesli kopya oluşturulamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        }));
    } finally {
        state.recording.checking = false;
        renderRecordingState();
    }
}

async function createElevenLabsDubbedRecording() {
    const inputPath = getElevenLabsDubbingInputPath();
    if (!inputPath) {
        setStatus(t('broadcast_room.status_recording_output_missing', 'Henüz açılacak bir kayıt dosyası yok.'));
        return;
    }
    const sourceLanguage = String(state.recording.elevenLabsDubbingSourceLanguage || 'auto');
    const targetLanguage = String(state.recording.elevenLabsDubbingTargetLanguage || 'tr');
    if (!targetLanguage || targetLanguage === 'auto') {
        setStatus(t('broadcast_room.status_elevenlabs_dubbing_target_required', 'ElevenLabs dublaj için hedef dili seçin.'));
        return;
    }

    state.recording.checking = true;
    state.recording.elevenLabsDubbingActive = true;
    state.recording.elevenLabsDubbingStatus = t('broadcast_room.status_elevenlabs_dubbing_uploading', 'Kayıt ElevenLabs Dubbing servisine gönderiliyor...');
    renderRecordingState();
    setStatus(state.recording.elevenLabsDubbingStatus);
    try {
        const dubbingResponse = await ipcRenderer.invoke('elevenlabs-create-dubbing-audio-from-file', {
            filePath: inputPath,
            sourceLanguage,
            targetLanguage
        });
        if (!dubbingResponse?.success) {
            throw new Error(dubbingResponse?.error || 'elevenlabs_dubbing_failed');
        }
        state.recording.elevenLabsDubbingCachedAudioPath = String(dubbingResponse.outputPath || '').trim();
        state.recording.elevenLabsDubbingCachedSourcePath = inputPath;
        state.recording.elevenLabsDubbingStatus = t('broadcast_room.status_elevenlabs_dubbing_mixing', 'ElevenLabs dublajı indirildi. Tek sesli kopya hazırlanıyor...');
        renderRecordingState();
        setStatus(state.recording.elevenLabsDubbingStatus);
        const mixResponse = await ipcRenderer.invoke('ffmpeg-create-single-dubbed-recording-from-audio', {
            videoPath: inputPath,
            dubAudioPath: dubbingResponse.outputPath,
            outputPath: buildElevenLabsDubbedRecordingOutputPath(inputPath),
            trackTitle: t('broadcast_room.dub_track_title', 'Dublaj + Özgün'),
            originalUnderVolume: getDubOutputOriginalVolumeValue(),
            dubVolume: getDubOutputDubVolumeValue()
        });
        if (!mixResponse?.success) {
            throw new Error(mixResponse?.error || 'elevenlabs_dubbing_mix_failed');
        }
        if (Array.isArray(state.translation.dubRecordingSegments) && state.translation.dubRecordingSegments.length > 0 && !state.recording.dubSegmentInputPath) {
            state.recording.dubSegmentInputPath = inputPath;
        }
        state.recording.outputPath = String(mixResponse.outputPath || state.recording.outputPath);
        state.recording.elevenLabsDubbingStatus = t('broadcast_room.status_elevenlabs_dubbing_created', 'ElevenLabs dublajlı kopya oluşturuldu: {path}', {
            path: state.recording.outputPath
        });
        renderRecordingState();
        setStatus(state.recording.elevenLabsDubbingStatus);
    } catch (error) {
        state.recording.elevenLabsDubbingStatus = t('broadcast_room.status_elevenlabs_dubbing_failed', 'ElevenLabs dublajlı kopya oluşturulamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        });
        setStatus(state.recording.elevenLabsDubbingStatus);
    } finally {
        state.recording.checking = false;
        state.recording.elevenLabsDubbingActive = false;
        renderRecordingState();
    }
}

async function remixElevenLabsDubbedRecording() {
    const inputPath = String(state.recording.elevenLabsDubbingCachedSourcePath || '').trim();
    const dubAudioPath = String(state.recording.elevenLabsDubbingCachedAudioPath || '').trim();
    if (!inputPath || !dubAudioPath) {
        setStatus(t('broadcast_room.status_elevenlabs_dubbing_cache_missing', 'Yeniden dengelemek için saklanan ElevenLabs dublaj sesi bulunamadı.'));
        return;
    }

    state.recording.checking = true;
    state.recording.elevenLabsDubbingActive = true;
    state.recording.elevenLabsDubbingStatus = t('broadcast_room.status_elevenlabs_dubbing_remixing', 'Saklanan ElevenLabs dublaj sesiyle yeni denge oluşturuluyor...');
    renderRecordingState();
    setStatus(state.recording.elevenLabsDubbingStatus);
    try {
        const mixResponse = await ipcRenderer.invoke('ffmpeg-create-single-dubbed-recording-from-audio', {
            videoPath: inputPath,
            dubAudioPath,
            outputPath: buildElevenLabsDubbedRecordingOutputPath(inputPath),
            trackTitle: t('broadcast_room.dub_track_title', 'Dublaj + Özgün'),
            originalUnderVolume: getDubOutputOriginalVolumeValue(),
            dubVolume: getDubOutputDubVolumeValue()
        });
        if (!mixResponse?.success) {
            throw new Error(mixResponse?.error || 'elevenlabs_dubbing_remix_failed');
        }
        state.recording.outputPath = String(mixResponse.outputPath || state.recording.outputPath);
        state.recording.elevenLabsDubbingStatus = t('broadcast_room.status_elevenlabs_dubbing_remixed', 'Saklanan ElevenLabs dublajıyla yeni denge oluşturuldu: {path}', {
            path: state.recording.outputPath
        });
        renderRecordingState();
        setStatus(state.recording.elevenLabsDubbingStatus);
    } catch (error) {
        state.recording.elevenLabsDubbingStatus = t('broadcast_room.status_elevenlabs_dubbing_remix_failed', 'Saklanan ElevenLabs dublajı yeniden dengelenemedi: {error}', {
            error: error?.message || error || 'unknown_error'
        });
        setStatus(state.recording.elevenLabsDubbingStatus);
    } finally {
        state.recording.checking = false;
        state.recording.elevenLabsDubbingActive = false;
        renderRecordingState();
    }
}

function syncHostToggleControls() {
    const localIdentity = String(state.roomState.hostIdentity || '').trim();
    const localParticipant = localIdentity
        ? state.participants.find((participant) => String(participant.id || '').trim() === localIdentity)
        : null;
    const fallbackHostParticipant = state.participants.find((participant) => String(participant.id || '').startsWith('host-'));
    const participant = localParticipant || (isLocalRoomHost() ? fallbackHostParticipant : null);
    if (!participant) {
        return;
    }

    if (els.hostCameraEnabled) {
        els.hostCameraEnabled.checked = participant.cameraEnabled !== false;
    }
    if (els.hostMicrophoneEnabled) {
        els.hostMicrophoneEnabled.checked = participant.microphoneEnabled !== false;
    }
    updateHostMediaActionButtons();
}

function applyRoomSnapshot(snapshot) {
    if (!snapshot) {
        return;
    }
    const previousRoomSettings = { ...state.roomSettings };
    const previousLocalRole = getLocalRoomRole();
    const previousLatestRoomChatId = getLatestRoomChatMessageId();
    const previousLocalIdentity = String(state.roomState.hostIdentity || '').trim();
    const previousOwnParticipant = previousLocalIdentity
        ? state.participants.find((participant) => String(participant.id || participant.identity || '').trim() === previousLocalIdentity)
        : null;
    const previousOwnDisplayName = String(previousOwnParticipant?.name || state.roomState.localDisplayName || '').trim();

    state.roomState = {
        roomId: String(snapshot.roomState?.roomId || ''),
        inviteUrl: String(snapshot.roomState?.inviteUrl || ''),
        hostConnected: snapshot.roomState?.hostConnected !== false,
        mode: String(snapshot.roomState?.mode || state.roomState.mode || 'prototype'),
        hostIdentity: String(snapshot.roomState?.hostIdentity || state.roomState.hostIdentity || ''),
        hostToken: String(snapshot.roomState?.hostToken || state.roomState.hostToken || ''),
        livekitUrl: String(snapshot.roomState?.livekitUrl || state.roomState.livekitUrl || ''),
        allowGuestScreenShare: snapshot.roomState?.allowGuestScreenShare !== false,
        persistentRoom: snapshot.roomState?.persistentRoom === true || state.roomState.persistentRoom === true,
        localRole: String(snapshot.roomState?.localRole || state.roomState.localRole || 'host').trim() || 'host',
        localDisplayName: String(snapshot.roomState?.localDisplayName || state.roomState.localDisplayName || '').trim()
    };
    if (previousLocalRole !== 'guest' && getLocalRoomRole() === 'guest') {
        state.lastGuestHostActivityKey = '';
    }
    state.roomSettings = {
        title: String(snapshot.roomSettings?.title || state.roomSettings.title || ''),
        hostDisplayName: String(snapshot.roomSettings?.hostDisplayName || state.roomSettings.hostDisplayName || getDefaultHostDisplayName()),
        persistentRoom: snapshot.roomSettings?.persistentRoom === true,
        roomSlug: String(snapshot.roomSettings?.roomSlug || state.roomSettings.roomSlug || ''),
        password: String(snapshot.roomSettings?.password || state.roomSettings.password || ''),
        allowJoinWhenHostAbsent: snapshot.roomSettings?.allowJoinWhenHostAbsent === true,
        requirePasswordWhenHostPresent: snapshot.roomSettings?.requirePasswordWhenHostPresent === true,
        requirePasswordWhenHostAbsent: snapshot.roomSettings?.requirePasswordWhenHostAbsent === true,
        webinarMode: snapshot.roomSettings?.webinarMode === true,
        allowGuestCamera: snapshot.roomSettings?.allowGuestCamera !== false,
        allowGuestMicrophone: snapshot.roomSettings?.allowGuestMicrophone !== false,
        hostRecordingActive: snapshot.roomSettings?.hostRecordingActive === true,
        hostShareActive: snapshot.roomSettings?.hostShareActive === true,
        hostShareLabel: String(snapshot.roomSettings?.hostShareLabel || ''),
        hostShareMonitorAudioEnabled: snapshot.roomSettings?.hostShareMonitorAudioEnabled === true,
        youtubeWatchUrl: String(snapshot.roomSettings?.youtubeWatchUrl || ''),
        youtubeLiveActive: snapshot.roomSettings?.youtubeLiveActive === true
    };
    if (getLocalRoomRole() === 'guest') {
        const nextWatchUrl = state.roomSettings.youtubeWatchUrl;
        if (nextWatchUrl !== state.youtube.preparedWatchUrl) {
            stopYouTubeChatPolling();
            state.youtube.liveChatId = '';
            state.youtube.chatNextPageToken = '';
            state.youtube.chatMessages = [];
            state.youtube.preparedWatchUrl = nextWatchUrl;
            if (nextWatchUrl) {
                ensureYouTubeChatSessionLoaded().then((loaded) => {
                    if (loaded) pollYouTubeChatMessages({ initial: true }).catch(() => {});
                }).catch(() => {});
            }
        }
        state.youtube.liveActive = state.roomSettings.youtubeLiveActive;
    }
    announceGuestHostActivityChange(previousRoomSettings, state.roomSettings);
    ensureGuestShareMonitorAudioSocket();
    const nextParticipants = Array.isArray(snapshot.participants) ? snapshot.participants : [];
    const nextLocalIdentity = String(state.roomState.hostIdentity || '').trim();
    const nextOwnParticipant = nextLocalIdentity
        ? nextParticipants.find((participant) => String(participant.id || participant.identity || '').trim() === nextLocalIdentity)
        : null;
    const nextOwnDisplayName = String(nextOwnParticipant?.name || state.roomState.localDisplayName || '').trim();
    const ownDisplayNameChangedByHost = getLocalRoomRole() === 'guest'
        && previousOwnDisplayName
        && nextOwnDisplayName
        && previousOwnDisplayName !== nextOwnDisplayName;
    state.participants = nextParticipants;
    if (ownDisplayNameChangedByHost) {
        state.roomState.localDisplayName = nextOwnDisplayName;
        persistJoinDisplayName(nextOwnDisplayName);
        if (els.joinedGuestDisplayName) {
            els.joinedGuestDisplayName.value = nextOwnDisplayName;
        }
        const message = t('broadcast_room.joined_guest_name_changed_by_host', 'Host görünen adınızı değiştirdi: {name}', {
            name: nextOwnDisplayName
        });
        setStatus(message);
        announce(message);
    }
    state.roomChat.messages = Array.isArray(snapshot.chatMessages) ? snapshot.chatMessages : state.roomChat.messages;
    state.liveCaption = snapshot.liveCaption || state.liveCaption;
    syncGeminiPersonalTranslationChannelsIfNeeded().catch((error) => {
        logBroadcastRoomDebug('gemini-personal-translation-channel-sync-failed', {
            error: error?.message || String(error || '')
        });
    });
    syncStageOutputCaptionOverlay();
    refreshLiveInterpreterRecordingGraph();
    state.participantSources = Array.isArray(snapshot.participantSources) ? snapshot.participantSources.map((item) => {
        const normalizedOwnerName = String(item.ownerName || '').trim() || t('broadcast_room.value_not_available', 'Hazır değil');
        const normalizedRole = item.sourceGroup === 'host-share' || String(item.ownerId || '').startsWith('host-')
            ? 'host'
            : 'guest';
        if (item.type === 'share') {
            return {
                id: String(item.id || ''),
                rawType: 'share',
                ownerId: String(item.ownerId || ''),
                ownerName: item.ownerName,
                sourceGroup: item.sourceGroup,
                shareKind: item.shareKind,
                name: item.label || t('broadcast_room.participant_share_source', '{name} paylaşımı', { name: item.ownerName }),
                type: getShareKindLabel(item.shareKind),
                sourceKey: `participant::${normalizedRole}::${normalizedOwnerName.toLowerCase()}::share::${String(item.shareKind || '').toLowerCase()}::${String(item.label || '').trim().toLowerCase()}`,
                includeAudio: item.includeAudio === true,
                enabled: item.enabled !== false
            };
        }

        return {
            id: String(item.id || ''),
            rawType: item.type,
            ownerId: String(item.ownerId || ''),
            ownerName: item.ownerName,
            name: item.type === 'camera'
                ? t('broadcast_room.participant_camera_source', '{name} Kamerası', { name: item.ownerName })
                : t('broadcast_room.participant_microphone_source', '{name} Mikrofonu', { name: item.ownerName }),
            type: item.type === 'camera'
                ? t('broadcast_room.source_type_camera', 'Kamera')
                : t('broadcast_room.source_type_microphone', 'Mikrofon'),
            sourceKey: `participant::${normalizedRole}::${normalizedOwnerName.toLowerCase()}::${String(item.type || '').toLowerCase()}`,
            enabled: item.enabled !== false
        };
    }) : [];
    if (!state.roomState.roomId) {
        state.translation.prepared = false;
        state.translation.waitingForAudio = false;
        state.translation.lastPublishedCaptionSignature = '';
        state.liveCaption = {
            text: '',
            sourceLanguage: '',
            targetLanguage: '',
            scope: '',
            mode: '',
            updatedAt: 0
        };
    }

    syncHostToggleControls();
    announceNewRoomChatMessages({ previousLatestId: previousLatestRoomChatId }).catch(() => {});
    announceHandRaiseChanges();
    reconcileSceneAssignments();
    syncGuestShareSceneBehavior();
    if (state.activeScenePresetId === 'six-gallery') {
        applyActiveSpeakerGalleryLayout();
    }
    renderAll();
    updateRoomLifecycleState();
}

function applyInitOptions(options = {}) {
    if (options.roomId) {
        state.roomState.roomId = String(options.roomId);
    }
    if (options.inviteUrl) {
        state.roomState.inviteUrl = String(options.inviteUrl);
    }
    renderAll();
}

function assignSelectedSourceToSelectedSlot(sourceId = '') {
    if (!isLocalRoomHost()) return false;
    if (sourceId) {
        state.selectedSceneSourceId = String(sourceId || '');
    }
    const preset = getActiveScenePreset();
    const slot = preset?.slots.find((item) => item.id === state.selectedSceneSlotId);
    const source = getSceneAssignableSources().find((item) => item.id === state.selectedSceneSourceId);

    if (!slot) {
        setStatus(t('broadcast_room.status_scene_slot_missing', 'Önce bir sahne slotu seçin.'));
        return false;
    }
    if (!source) {
        setStatus(t('broadcast_room.status_scene_source_missing', 'Önce sahneye atanacak bir kaynak seçin.'));
        return false;
    }
    if (Array.isArray(slot.acceptedTypes) && !slot.acceptedTypes.includes(source.sceneType)) {
        setStatus(t('broadcast_room.status_scene_source_incompatible', 'Bu kaynak seçili slot için uygun değil.'));
        return false;
    }

    const assignments = getActiveSceneAssignments();
    const conflictingSlot = Object.entries(assignments).find(([slotId, sourceId]) => slotId !== slot.id && sourceId === source.id);
    if (conflictingSlot) {
        const conflictingSlotLabel = preset?.slots.find((item) => item.id === conflictingSlot[0])?.label || conflictingSlot[0];
        setStatus(t('broadcast_room.status_scene_source_already_used', 'Bu kaynak zaten {slot} slotunda kullanılıyor.', {
            slot: conflictingSlotLabel
        }));
        return false;
    }

    assignments[slot.id] = source.id;
    getActiveSceneAssignmentAnchors()[slot.id] = buildSceneSourceAnchor(source);
    syncBroadcastAdvancedLayoutDefaults(true);
    renderSceneSlotSelector();
    renderSceneSourceSelector();
    renderSceneSummary();
    renderAdvancedLayoutPanelState();
    syncLiveSceneState().catch(() => {});
    syncStageOutputWindowMedia().catch(() => {});
    scheduleObsSceneRefreshForActiveBroadcast();
    addDiagnosticEvent('scene', t('broadcast_room.status_scene_source_assigned', '{source}, {slot} slotuna atandı.', {
        source: source.label,
        slot: slot.label
    }));
    setStatus(t('broadcast_room.status_scene_source_assigned', '{source}, {slot} slotuna atandı.', {
        source: source.label,
        slot: slot.label
    }));
    return true;
}

function clearSelectedSceneSlot() {
    if (!isLocalRoomHost()) return;
    const preset = getActiveScenePreset();
    const slot = preset?.slots.find((item) => item.id === state.selectedSceneSlotId);
    if (!slot) {
        setStatus(t('broadcast_room.status_scene_slot_missing', 'Önce bir sahne slotu seçin.'));
        return;
    }

    const assignments = getActiveSceneAssignments();
    if (!assignments[slot.id]) {
        setStatus(t('broadcast_room.status_scene_slot_already_empty', 'Seçili slot zaten boş.'));
        return;
    }

    delete assignments[slot.id];
    delete getActiveSceneAssignmentAnchors()[slot.id];
    syncBroadcastAdvancedLayoutDefaults(true);
    renderSceneSlotSelector();
    renderSceneSourceSelector();
    renderSceneSummary();
    renderAdvancedLayoutPanelState();
    syncLiveSceneState().catch(() => {});
    syncStageOutputWindowMedia().catch(() => {});
    scheduleObsSceneRefreshForActiveBroadcast();
    addDiagnosticEvent('scene', t('broadcast_room.status_scene_slot_cleared', '{slot} slotundaki kaynak kaldırıldı.', {
        slot: slot.label
    }));
    setStatus(t('broadcast_room.status_scene_slot_cleared', '{slot} slotundaki kaynak kaldırıldı.', {
        slot: slot.label
    }));
}

function buildHostShareSourcePool({ screens = [], windows = [] }) {
    const nextSources = [];

    const buildStableShareId = (prefix, rawValue, fallbackValue) => {
        const normalized = String(rawValue || fallbackValue || '')
            .trim()
            .toLowerCase()
            .replace(/\s+/g, '-')
            .replace(/[^a-z0-9_-]/g, '_')
            .slice(0, 80);
        return `${prefix}-${normalized || String(fallbackValue || 'source')}`;
    };

    screens.forEach((screen, index) => {
        const sourceValue = screen.id || screen.name || `screen-${index + 1}`;
        nextSources.push({
            id: buildStableShareId('screen', sourceValue, index + 1),
            name: screen.name || t('broadcast_room.default_source_local_screen', 'Yerel ekran paylaşımı'),
            type: t('broadcast_room.share_kind_screen', 'Ekran paylaşımı'),
            shareKind: 'screen',
            monitorIndex: index,
            sourceValue,
            sourceKey: `host-local-share::screen::${String(sourceValue || '').toLowerCase()}`
        });
    });

    windows.slice(0, 8).forEach((windowItem, index) => {
        const normalizedName = String(windowItem.name || '');
        const looksLikeApp = !normalizedName.includes(' - ') && !normalizedName.includes('/');
        const sourceValue = normalizedName || windowItem.id || `window-${index + 1}`;
        nextSources.push({
            id: buildStableShareId(looksLikeApp ? 'app' : 'window', sourceValue, index + 1),
            name: normalizedName || t('broadcast_room.default_source_window', 'Yerel pencere veya uygulama'),
            shareKind: looksLikeApp ? 'application' : 'window',
            sourceValue,
            sourceLookupId: windowItem.id || '',
            sourceKey: `host-local-share::${looksLikeApp ? 'application' : 'window'}::${String(windowItem.id || sourceValue || '').toLowerCase()}`,
            type: looksLikeApp
                ? t('broadcast_room.share_kind_application', 'Uygulama paylaşımı')
                : t('broadcast_room.share_kind_window', 'Pencere paylaşımı')
        });
    });

    return nextSources;
}

async function refreshLocalSources() {
    setStatus(t('broadcast_room.status_refreshing_sources', 'Yerel kaynaklar yenileniyor...'));
    const previousSelectedHostShareId = String(state.selectedHostShareSourceId || els.hostShareSourceSelect?.value || '');
    const previousSources = Array.isArray(state.availableLocalShareSources) ? [...state.availableLocalShareSources] : [];

    let screens = [];
    let windows = [];
    let cameras = [];
    let microphones = [];
    let speakers = [];

    try {
        const result = await ipcRenderer.invoke('get-desktop-sources', { types: ['screen'], fetchWindowIcons: false, thumbnailSize: { width: 0, height: 0 } });
        if (result?.success && Array.isArray(result.sources)) {
            screens = result.sources;
        }
    } catch (error) {
        console.error('Broadcast room screen sources error:', error);
    }

    try {
        const result = await ipcRenderer.invoke('get-desktop-sources', { types: ['window'], fetchWindowIcons: false, thumbnailSize: { width: 0, height: 0 } });
        if (result?.success && Array.isArray(result.sources)) {
            windows = result.sources;
        }
    } catch (error) {
        console.error('Broadcast room window sources error:', error);
    }

    try {
        const nativeResult = await ipcRenderer.invoke('get-native-window-sources');
        if (nativeResult?.success && Array.isArray(nativeResult.sources)) {
            const existingNames = new Set(windows.map((item) => String(item.name || '').trim().toLowerCase()).filter(Boolean));
            nativeResult.sources.forEach((source) => {
                const normalizedName = String(source.name || '').trim().toLowerCase();
                if (!normalizedName || existingNames.has(normalizedName)) {
                    return;
                }
                windows.push(source);
                existingNames.add(normalizedName);
            });
        }
    } catch (error) {
        console.error('Broadcast room native window sources error:', error);
    }

    try {
        if (navigator.mediaDevices?.enumerateDevices) {
            const devices = await navigator.mediaDevices.enumerateDevices();
            cameras = devices.filter((device) => device.kind === 'videoinput');
            microphones = devices.filter((device) => device.kind === 'audioinput');
            speakers = devices.filter((device) => device.kind === 'audiooutput');
        }
    } catch (error) {
        console.error('Broadcast room media devices error:', error);
    }

    state.audioDevices.cameras = cameras.map((device, index) => ({
        deviceId: device.deviceId || `camera-${index + 1}`,
        label: device.label || t('broadcast_room.default_camera_option', 'Kamera {index}', { index: String(index + 1) })
    }));
    state.audioDevices.microphones = microphones.map((device, index) => ({
        deviceId: device.deviceId || `microphone-${index + 1}`,
        label: device.label || t('broadcast_room.default_microphone_option', 'Mikrofon {index}', { index: String(index + 1) })
    }));
    state.audioDevices.speakers = speakers.map((device, index) => ({
        deviceId: device.deviceId || `speaker-${index + 1}`,
        label: device.label || t('broadcast_room.default_speaker_option', 'Hoparlör {index}', { index: String(index + 1) })
    }));

    const cameraIds = new Set(state.audioDevices.cameras.map((camera) => String(camera.deviceId || '').trim()).filter(Boolean));
    const microphoneIds = new Set(state.audioDevices.microphones.map((microphone) => String(microphone.deviceId || '').trim()).filter(Boolean));
    if (!state.audioDevices.selectedCameraId || !cameraIds.has(String(state.audioDevices.selectedCameraId || '').trim())) {
        state.audioDevices.selectedCameraId = state.audioDevices.cameras[0]?.deviceId || '';
    }
    if (!state.audioDevices.selectedMicrophoneId || !microphoneIds.has(String(state.audioDevices.selectedMicrophoneId || '').trim())) {
        state.audioDevices.selectedMicrophoneId = state.audioDevices.microphones[0]?.deviceId || '';
    }
    const speakerIds = new Set(state.audioDevices.speakers.map((speaker) => String(speaker.deviceId || '').trim()).filter(Boolean));
    const hasDefaultSpeaker = speakerIds.has('default');
    if (!state.audioDevices.selectedSpeakerId
        || state.audioDevices.selectedSpeakerId === 'communications'
        || !speakerIds.has(state.audioDevices.selectedSpeakerId)) {
        state.audioDevices.selectedSpeakerId = hasDefaultSpeaker
            ? 'default'
            : state.audioDevices.speakers[0]?.deviceId || '';
    }

    const nextLocalShareSources = buildHostShareSourcePool({ screens, windows });
    const remappedSourceIds = new Map();
    previousSources.forEach((previousSource) => {
        const match = nextLocalShareSources.find((nextSource) => (
            nextSource.shareKind === previousSource.shareKind
            && (
                (nextSource.sourceLookupId && previousSource.sourceLookupId && nextSource.sourceLookupId === previousSource.sourceLookupId)
                || (nextSource.sourceValue && previousSource.sourceValue && nextSource.sourceValue === previousSource.sourceValue)
                || (nextSource.name && previousSource.name && nextSource.name === previousSource.name)
            )
        ));
        if (match) {
            remappedSourceIds.set(previousSource.id, match.id);
        }
    });

    state.availableLocalShareSources = nextLocalShareSources;
    state.activeLocalShareSourceIds = state.activeLocalShareSourceIds
        .map((id) => remappedSourceIds.get(id) || id)
        .filter((id, index, array) => array.indexOf(id) === index)
        .filter((id) => state.availableLocalShareSources.some((source) => source.id === id));
    state.hostLocalShareAudioById = Object.fromEntries(
        Object.entries(state.hostLocalShareAudioById)
            .map(([id, value]) => [remappedSourceIds.get(id) || id, value])
            .filter(([id]) => state.availableLocalShareSources.some((source) => source.id === id))
    );
    Object.keys(state.sceneAssignmentsByPreset || {}).forEach((presetId) => {
        const assignments = state.sceneAssignmentsByPreset[presetId];
        if (!assignments || typeof assignments !== 'object') {
            return;
        }
        Object.keys(assignments).forEach((slotId) => {
            const sourceId = assignments[slotId];
            if (remappedSourceIds.has(sourceId)) {
                assignments[slotId] = remappedSourceIds.get(sourceId);
            }
        });
    });

    reconcileSceneAssignments();

    if (els.hostShareSourceSelect && state.availableLocalShareSources.length > 0) {
        const remappedSelectedId = remappedSourceIds.get(previousSelectedHostShareId) || previousSelectedHostShareId;
        const nextSelectedId = state.availableLocalShareSources.some((source) => source.id === remappedSelectedId)
            ? remappedSelectedId
            : state.availableLocalShareSources[0].id;
        state.selectedHostShareSourceId = nextSelectedId;
    } else {
        state.selectedHostShareSourceId = '';
    }
    renderAll();
    setStatus(t('broadcast_room.status_sources_refreshed', 'Yerel kaynak listesi yenilendi. Toplam {count} kaynak var.', {
        count: String(state.availableLocalShareSources.length + state.participantSources.length)
    }));
}

function updateSelectedAudioDevice(type, value) {
    const map = {
        camera: 'selectedCameraId',
        microphone: 'selectedMicrophoneId',
        speaker: 'selectedSpeakerId'
    };
    state.audioDevices[map[type]] = String(value || '');

    const sourceLists = {
        camera: state.audioDevices.cameras,
        microphone: state.audioDevices.microphones,
        speaker: state.audioDevices.speakers
    };

    const selected = sourceLists[type].find((item) => item.deviceId === value);
    const keyMap = {
        camera: 'broadcast_room.status_camera_device_selected',
        microphone: 'broadcast_room.status_microphone_device_selected',
        speaker: 'broadcast_room.status_speaker_device_selected'
    };
    const fallbackMap = {
        camera: 'Seçili kamera değiştirildi: {name}',
        microphone: 'Seçili mikrofon değiştirildi: {name}',
        speaker: 'Seçili hoparlör değiştirildi: {name}'
    };

    setStatus(t(keyMap[type], fallbackMap[type], {
        name: selected?.label || t('broadcast_room.unknown_device', 'Bilinmeyen aygıt')
    }));
}

function setHostAudioTestStatus(message) {
    if (els.hostAudioTestStatus) {
        els.hostAudioTestStatus.textContent = message;
    }
    setStatus(message);
}

function createBeepWaveBlob({ durationSeconds = 0.45, frequency = 880, volume = 0.35 } = {}) {
    const sampleRate = 44100;
    const sampleCount = Math.max(1, Math.floor(sampleRate * durationSeconds));
    const buffer = new ArrayBuffer(44 + sampleCount * 2);
    const view = new DataView(buffer);
    const writeString = (offset, value) => {
        for (let index = 0; index < value.length; index += 1) {
            view.setUint8(offset + index, value.charCodeAt(index));
        }
    };
    writeString(0, 'RIFF');
    view.setUint32(4, 36 + sampleCount * 2, true);
    writeString(8, 'WAVE');
    writeString(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true);
    view.setUint16(22, 1, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    writeString(36, 'data');
    view.setUint32(40, sampleCount * 2, true);
    for (let index = 0; index < sampleCount; index += 1) {
        const fadeIn = Math.min(1, index / 600);
        const fadeOut = Math.min(1, (sampleCount - index) / 1200);
        const envelope = Math.min(fadeIn, fadeOut);
        const sample = Math.sin((2 * Math.PI * frequency * index) / sampleRate) * volume * envelope;
        view.setInt16(44 + index * 2, Math.max(-1, Math.min(1, sample)) * 32767, true);
    }
    return new Blob([buffer], { type: 'audio/wav' });
}

async function applySelectedSpeakerToAudioElement(audioEl) {
    const speakerId = String(state.audioDevices.selectedSpeakerId || els.hostSpeakerDevice?.value || '').trim();
    if (speakerId && typeof audioEl.setSinkId === 'function') {
        await audioEl.setSinkId(speakerId).catch(() => {});
    }
}

async function testHostSpeaker() {
    const audio = new Audio(URL.createObjectURL(createBeepWaveBlob()));
    audio.volume = getHostSpeakerVolume();
    await applySelectedSpeakerToAudioElement(audio);
    audio.addEventListener('ended', () => {
        URL.revokeObjectURL(audio.src);
    }, { once: true });
    await audio.play();
    setHostAudioTestStatus(t('broadcast_room.status_speaker_test_played', 'Hoparlör test sesi çalındı.'));
}

function stopHostMicrophoneTest({ announceStatus = true } = {}) {
    if (state.audioTest.microphoneStopTimer) {
        clearTimeout(state.audioTest.microphoneStopTimer);
        state.audioTest.microphoneStopTimer = null;
    }
    if (state.audioTest.microphoneAudio) {
        try { state.audioTest.microphoneAudio.pause(); } catch (_error) {}
        state.audioTest.microphoneAudio.srcObject = null;
        state.audioTest.microphoneAudio = null;
    }
    if (state.audioTest.microphoneStream) {
        state.audioTest.microphoneStream.getTracks().forEach((track) => {
            try { track.stop(); } catch (_error) {}
        });
        state.audioTest.microphoneStream = null;
    }
    applyDynamicButtonLabel(
        els.btnTestHostMicrophone,
        'broadcast_room.test_microphone_button',
        'Mikrofonu test et'
    );
    if (announceStatus) {
        setHostAudioTestStatus(t('broadcast_room.status_microphone_test_stopped', 'Mikrofon testi durduruldu.'));
    }
}

async function toggleHostMicrophoneTest() {
    if (state.audioTest.microphoneStream) {
        stopHostMicrophoneTest();
        return;
    }
    const deviceId = String(state.audioDevices.selectedMicrophoneId || els.hostMicrophoneDevice?.value || '').trim();
    const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
            deviceId: deviceId ? { exact: deviceId } : undefined,
            echoCancellation: false,
            noiseSuppression: false,
            autoGainControl: false
        }
    });
    const audio = document.createElement('audio');
    audio.autoplay = true;
    audio.srcObject = stream;
    audio.volume = getHostSpeakerVolume();
    await applySelectedSpeakerToAudioElement(audio);
    state.audioTest.microphoneStream = stream;
    state.audioTest.microphoneAudio = audio;
    applyDynamicButtonLabel(
        els.btnTestHostMicrophone,
        'broadcast_room.stop_microphone_test_button',
        'Mikrofon testini durdur'
    );
    setHostAudioTestStatus(t('broadcast_room.status_microphone_test_started', 'Mikrofon testi başladı. Kendi sesinizi birkaç saniye duyacaksınız.'));
    state.audioTest.microphoneStopTimer = window.setTimeout(() => {
        stopHostMicrophoneTest();
    }, 6000);
    await audio.play().catch(() => {});
}

function announceInitialRoomConnection({ roomName = '', inviteUrl = '' } = {}) {
    const safeRoomName = String(roomName || '').trim() || t('broadcast_room.default_room_title', 'EVD Yayın Odası');
    const safeInviteUrl = String(inviteUrl || '').trim();
    if (safeInviteUrl) {
        clipboard.writeText(safeInviteUrl);
    }
    setStatus(t(
        'broadcast_room.status_initial_room_connection_ready',
        '{name} isimli oda bağlantısı kuruldu ve oda bağlantısı panoya kopyalandı. Dilerseniz bu bağlantıyı konuklarınızla paylaşın.',
        { name: safeRoomName }
    ));
}

function readValidatedPersistentRoomSlug() {
    const rawSlug = String(els.persistentRoomSlugInput?.value || '').trim();
    if (!rawSlug) {
        return { ok: true, slug: '' };
    }
    if (!/^[A-Za-z0-9_-]+$/.test(rawSlug)) {
        setStatus(t(
            'broadcast_room.persistent_room_slug_invalid',
            'Kalıcı oda bağlantı anahtarı yalnızca İngilizce harf, rakam, tire ve alt çizgi içerebilir. Boşluk ve Türkçe karakter kullanmayın.'
        ));
        els.persistentRoomSlugInput?.focus?.();
        return { ok: false, slug: '' };
    }
    const normalizedSlug = rawSlug.toLowerCase();
    if (els.persistentRoomSlugInput && els.persistentRoomSlugInput.value !== normalizedSlug) {
        els.persistentRoomSlugInput.value = normalizedSlug;
    }
    return { ok: true, slug: normalizedSlug };
}

async function createRoom() {
    stopLiveRoomSync();
    try {
        const hostName = String(els.hostDisplayNameInput?.value || state.roomSettings.hostDisplayName || getDefaultHostDisplayName()).trim()
            || getDefaultHostDisplayName();
        const requestedAllowGuestScreenShare = !!els.allowGuestScreenShare?.checked;
        state.roomSettings.title = String(els.roomTitleInput?.value || '').trim() || t('broadcast_room.default_room_title', 'EVD Yayın Odası');
        state.roomSettings.hostDisplayName = hostName;
        state.roomSettings.persistentRoom = !!els.persistentRoomEnabled?.checked;
        const slugResult = state.roomSettings.persistentRoom
            ? readValidatedPersistentRoomSlug()
            : { ok: true, slug: String(els.persistentRoomSlugInput?.value || '').trim() };
        if (!slugResult.ok) {
            return;
        }
        state.roomSettings.roomSlug = slugResult.slug;
        state.roomSettings.password = String(els.persistentRoomPasswordInput?.value || '');
        state.roomSettings.allowJoinWhenHostAbsent = !!els.allowJoinWhenHostAbsent?.checked;
        state.roomSettings.requirePasswordWhenHostPresent = !!els.requirePasswordWhenHostPresent?.checked;
        state.roomSettings.requirePasswordWhenHostAbsent = !!els.requirePasswordWhenHostAbsent?.checked;
        state.roomSettings.webinarMode = !!els.webinarModeEnabled?.checked;
        state.roomSettings.allowGuestCamera = !!els.allowGuestCamera?.checked;
        state.roomSettings.allowGuestMicrophone = !!els.allowGuestMicrophone?.checked;
        persistHostDisplayName(hostName);
        const createdRoom = await requestLiveBroadcastRoomApi('/broadcast-room/create', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                hostDisplayName: hostName,
                title: state.roomSettings.title,
                persistentRoom: state.roomSettings.persistentRoom === true,
                roomSlug: state.roomSettings.roomSlug,
                password: state.roomSettings.password,
                allowJoinWhenHostAbsent: state.roomSettings.allowJoinWhenHostAbsent === true,
                requirePasswordWhenHostPresent: state.roomSettings.requirePasswordWhenHostPresent === true,
                requirePasswordWhenHostAbsent: state.roomSettings.requirePasswordWhenHostAbsent === true,
                webinarMode: state.roomSettings.webinarMode === true
            })
        });

        const hostTokenPayload = await requestLiveBroadcastRoomApi('/broadcast-room/host-token', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                roomId: createdRoom.roomId,
                hostDisplayName: hostName
            })
        });

        state.roomState = {
            roomId: String(createdRoom.roomId || ''),
            inviteUrl: String(createdRoom.inviteUrl || ''),
            hostConnected: true,
            mode: 'live',
            hostIdentity: String(hostTokenPayload.participantIdentity || ''),
            hostToken: String(hostTokenPayload.token || ''),
            livekitUrl: String(hostTokenPayload.livekitUrl || ''),
            allowGuestScreenShare: requestedAllowGuestScreenShare,
            localRole: 'host',
            localDisplayName: hostName
        };
        state.roomSettings.roomSlug = String(createdRoom.inviteId || state.roomSettings.roomSlug || '');

        await connectHostToLiveKit();
        await syncLiveRoomSettings();
        await updateOwnMediaState({
            cameraEnabled: !!state.liveRoom.localVideoTrack,
            microphoneEnabled: !!state.liveRoom.localAudioTrack
        });
        await syncLiveRoomSnapshot();
        startLiveRoomSync();
        announceInitialRoomConnection({
            roomName: state.roomSettings.title,
            inviteUrl: state.roomState.inviteUrl
        });
        addDiagnosticEvent('room', t('broadcast_room.status_room_created', 'Yeni oda oluşturuldu. Davet bağlantısı hazır.'));
        addDiagnosticEvent('room', t('broadcast_room.status_live_room_ready', 'Canlı yayın odası backend üzerinde hazırlandı.'));
    } catch (error) {
        setStatus(t('broadcast_room.status_room_create_failed', 'Oda oluşturulamadı: {error}', {
            error: getBroadcastRoomApiErrorMessage(error)
        }));
    }
}

async function openWebinarWithHostKey() {
    stopLiveRoomSync();
    try {
        const webinarHostKey = String(els.webinarHostKeyInput?.value || '').trim();
        if (!webinarHostKey) {
            const message = t('broadcast_room.webinar_host_key_required', 'Webinarı açmak için webinar anahtarını girin.');
            setStatus(message);
            announce(message);
            return;
        }
        const hostName = String(els.webinarHostNameInput?.value || els.hostDisplayNameInput?.value || state.roomSettings.hostDisplayName || getDefaultHostDisplayName()).trim()
            || getDefaultHostDisplayName();
        persistHostDisplayName(hostName);
        const openedRoom = await requestLiveBroadcastRoomApi('/broadcast-room/open-webinar', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                webinarHostKey,
                hostDisplayName: hostName
            })
        });
        const hostTokenPayload = await requestLiveBroadcastRoomApi('/broadcast-room/host-token', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                roomId: openedRoom.roomId,
                hostDisplayName: hostName
            })
        });
        state.roomSettings.title = String(openedRoom.webinar?.title || state.roomSettings.title || t('broadcast_room.default_room_title', 'EVD Yayın Odası'));
        state.roomSettings.hostDisplayName = hostName;
        state.roomSettings.webinarMode = true;
        state.roomSettings.persistentRoom = openedRoom.joinPolicy?.persistentRoom === true;
        state.roomSettings.roomSlug = String(openedRoom.inviteId || '');
        state.roomState = {
            roomId: String(openedRoom.roomId || ''),
            inviteUrl: String(openedRoom.inviteUrl || ''),
            hostConnected: true,
            mode: 'live',
            hostIdentity: String(hostTokenPayload.participantIdentity || ''),
            hostToken: String(hostTokenPayload.token || ''),
            livekitUrl: String(hostTokenPayload.livekitUrl || ''),
            allowGuestScreenShare: !!els.allowGuestScreenShare?.checked,
            localRole: 'host',
            localDisplayName: hostName
        };
        await connectHostToLiveKit();
        await syncLiveRoomSettings();
        await updateOwnMediaState({
            cameraEnabled: !!state.liveRoom.localVideoTrack,
            microphoneEnabled: !!state.liveRoom.localAudioTrack
        });
        await syncLiveRoomSnapshot();
        startLiveRoomSync();
        renderRoomState();
        announceInitialRoomConnection({
            roomName: state.roomSettings.title,
            inviteUrl: state.roomState.inviteUrl
        });
        addDiagnosticEvent('room', t('broadcast_room.webinar_opened_with_key', 'Webinar anahtarıyla webinar açıldı.'));
    } catch (error) {
        setStatus(getWebinarOpenErrorMessage(error?.message || error));
    }
}

function copyInviteLink() {
    if (!state.roomState.inviteUrl) {
        setStatus(t('broadcast_room.status_copy_without_room', 'Önce bir oda oluşturun.'));
        return;
    }
    clipboard.writeText(state.roomState.inviteUrl);
    addDiagnosticEvent('room', t('broadcast_room.status_invite_copied', 'Davet bağlantısı panoya kopyalandı.'));
    setStatus(t('broadcast_room.status_invite_copied', 'Davet bağlantısı panoya kopyalandı.'));
}

async function openTestGuestWindow() {
    if (!state.roomState.roomId || !state.roomState.inviteUrl) {
        setStatus(t('broadcast_room.status_open_guest_without_room', 'Önce bir oda oluşturun, sonra test konuk penceresini açın.'));
        return;
    }

    if (state.roomState.mode === 'live') {
        await shell.openExternal(state.roomState.inviteUrl);
        setPassiveStatus(t('broadcast_room.status_live_invite_opened', 'Canlı davet bağlantısı tarayıcıda açıldı.'));
        return;
    }

    state.guestWindowCounter += 1;
    const result = await ipcRenderer.invoke('broadcast-room-open-test-guest-window', {
        roomId: state.roomState.roomId,
        inviteUrl: state.roomState.inviteUrl,
        suggestedDisplayName: t('broadcast_room.test_guest_name', 'Test Konuk {index}', {
            index: String(state.guestWindowCounter)
        })
    });

    if (!result?.success) {
        setStatus(t('broadcast_room.status_guest_window_failed', 'Test konuk penceresi açılamadı: {error}', {
            error: result?.error || 'unknown_error'
        }));
        return;
    }

    setPassiveStatus(t('broadcast_room.status_guest_window_opened', 'Test konuk penceresi açıldı. İsterseniz adı değiştirip odaya katılabilirsiniz.'));
}

async function openMultipleTestGuestWindows(count) {
    const safeCount = Math.max(1, Math.min(8, Number(count) || 1));
    for (let index = 0; index < safeCount; index += 1) {
        await openTestGuestWindow();
    }
    setPassiveStatus(t('broadcast_room.status_multiple_guest_windows_opened', '{count} test konuk penceresi açıldı.', {
        count: String(safeCount)
    }));
}

async function updateOwnMediaState(options = {}) {
    if (!state.roomState.roomId) {
        return;
    }
    if (state.roomState.mode === 'live' && state.roomState.roomId && state.roomState.hostIdentity) {
        const localRole = getLocalRoomRole();
        try {
            await requestLiveBroadcastRoomApi('/broadcast-room/participant-state', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    roomId: state.roomState.roomId,
                    identity: state.roomState.hostIdentity,
                    displayName: String(state.roomState.localDisplayName || state.roomSettings.hostDisplayName || '').trim() || getDefaultHostDisplayName(),
                    role: localRole,
                    cameraEnabled: options.cameraEnabled,
                    microphoneEnabled: options.microphoneEnabled,
                    connected: true
                })
            });
            await syncLiveRoomSnapshot();
            return;
        } catch (error) {
            setStatus(t('broadcast_room.status_media_state_update_failed', 'Medya durumu güncellenemedi: {error}', {
                error: error?.message || error || 'unknown_error'
            }));
            return;
        }
    }

    const result = await ipcRenderer.invoke('broadcast-room-update-prototype-media-state', options);
    if (!result?.success) {
        if (result?.error === 'participant_binding_not_found') {
            return;
        }
        setStatus(t('broadcast_room.status_media_state_update_failed', 'Medya durumu güncellenemedi: {error}', {
            error: result?.error || 'unknown_error'
        }));
        return;
    }
    applyRoomSnapshot(result.snapshot);
}

async function closeCurrentRoomOrWindow() {
    if (state.roomState.mode === 'live' && state.roomState.roomId) {
        if (!isLocalRoomHost()) {
            try {
                await leaveCurrentLiveRoom();
            } catch (error) {
                setStatus(t('broadcast_room.status_room_leave_failed', 'Odadan ayrılamadı: {error}', {
                    error: error?.message || error || 'unknown_error'
                }));
                return;
            }
            setStatus(t('broadcast_room.status_room_left', 'Odadan ayrıldınız.'));
            return;
        }
        const choice = await promptRoomExitChoice();
        if (choice === 'cancel') {
            setStatus(t('broadcast_room.status_room_exit_cancelled', 'Odadan ayrılma iptal edildi.'));
            return;
        }
        if (choice === 'end_for_everyone') {
            try {
                await requestLiveBroadcastRoomApi(`/broadcast-room/${encodeURIComponent(state.roomState.roomId)}/end-session`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        hostIdentity: state.roomState.hostIdentity
                    })
                });
            } catch (error) {
                setStatus(t('broadcast_room.status_room_end_for_everyone_failed', 'Toplantı herkes için sonlandırılamadı: {error}', {
                    error: error?.message || error || 'unknown_error'
                }));
                return;
            }
            await leaveCurrentLiveRoom({ refreshRooms: false, notifyBackend: false });
            refreshPersistentRooms().catch(() => {});
            setStatus(t('broadcast_room.status_room_ended_for_everyone', 'Toplantı herkes için sonlandırıldı. Oda geçmişi temizlendi ve katılımcılar çıkarıldı.'));
            return;
        }
        if (choice === 'leave') {
            try {
                await leaveCurrentLiveRoom();
            } catch (error) {
                setStatus(t('broadcast_room.status_room_leave_failed', 'Odadan ayrılamadı: {error}', {
                    error: error?.message || error || 'unknown_error'
                }));
                return;
            }
            setStatus(t('broadcast_room.status_room_left', 'Odadan ayrıldınız.'));
            return;
        }
    }
    window.close();
}

function promptRoomExitChoice() {
    return new Promise((resolve) => {
        const previousActiveElement = document.activeElement;
        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.setAttribute('role', 'presentation');
        overlay.innerHTML = `
            <div class="dialog-content" role="dialog" aria-modal="true" aria-labelledby="persistent-room-exit-title" aria-describedby="persistent-room-exit-description" tabindex="-1">
                <h2 id="persistent-room-exit-title">${escapeHtml(t('broadcast_room.room_exit_title', 'Odadan ayrıl'))}</h2>
                <p id="persistent-room-exit-description">${escapeHtml(t('broadcast_room.room_exit_description', 'Yalnızca siz odadan ayrılabilir ya da toplantıyı herkes için sonlandırıp katılımcıları çıkarabilir ve bu oturumun sohbet geçmişini temizleyebilirsiniz.'))}</p>
                <div class="dialog-buttons">
                    <button type="button" data-exit-choice="leave">${escapeHtml(t('broadcast_room.room_leave_only', 'Yalnızca odadan ayrıl'))}</button>
                    <button type="button" class="danger" data-exit-choice="end_for_everyone">${escapeHtml(t('broadcast_room.room_end_for_everyone', 'Toplantıyı herkes için sonlandır'))}</button>
                    <button type="button" class="secondary" data-exit-choice="cancel">${escapeHtml(t('dialog.cancel', 'İptal'))}</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);
        const dialog = overlay.querySelector('[role="dialog"]');
        const leaveButton = overlay.querySelector('[data-exit-choice="leave"]');
        const finish = (choice) => {
            overlay.remove();
            if (previousActiveElement && typeof previousActiveElement.focus === 'function') {
                previousActiveElement.focus();
            }
            resolve(choice);
        };
        overlay.querySelectorAll('[data-exit-choice]').forEach((button) => {
            button.addEventListener('click', () => finish(button.getAttribute('data-exit-choice') || 'cancel'));
        });
        overlay.addEventListener('keydown', (event) => {
            if (event.key === 'Escape') {
                event.preventDefault();
                finish('cancel');
            }
        });
        announce(t('broadcast_room.room_exit_description', 'Yalnızca siz odadan ayrılabilir ya da toplantıyı herkes için sonlandırıp katılımcıları çıkarabilir ve bu oturumun sohbet geçmişini temizleyebilirsiniz.'));
        setTimeout(() => {
            (leaveButton || dialog)?.focus?.();
        }, 0);
    });
}

function getRoomExitFailureMessage(error) {
    const errorText = error?.message || error || 'unknown_error';
    return shouldLeaveCurrentRoom()
        ? t('broadcast_room.status_room_leave_failed', 'Odadan ayrılamadı: {error}', { error: errorText })
        : t('broadcast_room.status_room_close_failed', 'Oda kapatılamadı: {error}', { error: errorText });
}

async function startHostLocalShare() {
    const selectedId = String(state.selectedHostShareSourceId || els.hostShareSourceSelect?.value || '');
    if (!selectedId) {
        setStatus(t('broadcast_room.status_host_share_source_missing', 'Önce paylaşılacak bir yerel kaynak seçin.'));
        return;
    }
    state.selectedHostShareSourceId = selectedId;

    if (!state.activeLocalShareSourceIds.includes(selectedId)) {
        state.activeLocalShareSourceIds.push(selectedId);
    }
    state.hostLocalShareAudioById[selectedId] = !!els.hostShareAudioEnabled?.checked;

    const selected = state.availableLocalShareSources.find((item) => item.id === selectedId);
    const localIsHost = isLocalRoomHost();
    try {
        logBroadcastRoomDebug('host-share-start-click', {
            selectedId,
            includeAudio: !!els.hostShareAudioEnabled?.checked,
            selectedName: selected?.name || ''
        });
        renderSources();
        if (localIsHost) {
            applyHostShareSceneBehavior(selectedId);
        }
        updateHostShareButtonState();
        if (localIsHost) {
            renderAdvancedLayoutPanelState();
        }
        await reapplyHostSpeakerSelectionToRemoteAudio();
        await syncHostLiveKitShareMedia();
        if (localIsHost) {
            await syncLiveRoomSettings().catch(() => {});
            await syncStageOutputWindowMedia().catch(() => {});
            recordRecordingTimelineEvent('host_share_started');
            refreshObsSceneForActiveOutputAfterShareChange();
        }
        if (state.hostLocalShareAudioById[selectedId]) {
            addDiagnosticEvent('source', t('broadcast_room.status_host_share_started_with_audio', 'Host yerel paylaşımı başladı: {name}. Kaynak sesi dahil ediliyor.', {
                name: selected?.name || t('broadcast_room.unknown_device', 'Bilinmeyen aygıt')
            }));
            setStatus(t('broadcast_room.status_host_share_started_with_audio', 'Host yerel paylaşımı başladı: {name}. Kaynak sesi dahil ediliyor.', {
                name: selected?.name || t('broadcast_room.unknown_device', 'Bilinmeyen aygıt')
            }));
        } else {
            addDiagnosticEvent('source', t('broadcast_room.status_host_share_started', 'Host yerel paylaşımı başladı: {name}', {
                name: selected?.name || t('broadcast_room.unknown_device', 'Bilinmeyen aygıt')
            }));
            setStatus(t('broadcast_room.status_host_share_started', 'Host yerel paylaşımı başladı: {name}', {
                name: selected?.name || t('broadcast_room.unknown_device', 'Bilinmeyen aygıt')
            }));
        }
        logBroadcastRoomDebug('host-share-start-done', { selectedId });
    } catch (error) {
        logBroadcastRoomDebug('host-share-start-failed', { error: error?.message || String(error || '') });
        state.activeLocalShareSourceIds = state.activeLocalShareSourceIds.filter((item) => item !== selectedId);
        delete state.hostLocalShareAudioById[selectedId];
        renderSources();
        if (localIsHost) {
            restoreHostShareAutoSceneSnapshot(selectedId);
        }
        updateHostShareButtonState();
        if (localIsHost) {
            renderAdvancedLayoutPanelState();
        }
        setStatus(t('broadcast_room.status_host_share_start_failed', 'Host yerel paylaşımı başlatılamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        }));
    }
}

async function stopHostLocalShareById(sourceId) {
    const selectedId = String(sourceId || '');
    if (!selectedId || !state.activeLocalShareSourceIds.includes(selectedId)) {
        setStatus(t('broadcast_room.status_host_share_not_active', 'Seçili yerel paylaşım zaten etkin değil.'));
        return;
    }

    state.activeLocalShareSourceIds = state.activeLocalShareSourceIds.filter((item) => item !== selectedId);
    delete state.hostLocalShareAudioById[selectedId];
    const selected = state.availableLocalShareSources.find((item) => item.id === selectedId);
    const localIsHost = isLocalRoomHost();
    renderSources();
    if (localIsHost) {
        restoreHostShareAutoSceneSnapshot(selectedId);
    }
    updateHostShareButtonState();
    if (localIsHost) {
        renderAdvancedLayoutPanelState();
    }
    await syncHostLiveKitShareMedia();
    await reapplyHostSpeakerSelectionToRemoteAudio();
    if (localIsHost) {
        await syncStageOutputWindowMedia().catch(() => {});
        syncLiveRoomSettings().catch(() => {});
        recordRecordingTimelineEvent('host_share_stopped');
        refreshObsSceneForActiveOutputAfterShareChange();
    }
    addDiagnosticEvent('source', t('broadcast_room.status_host_share_stopped', 'Host yerel paylaşımı durduruldu: {name}', {
        name: selected?.name || t('broadcast_room.unknown_device', 'Bilinmeyen aygıt')
    }));
    setStatus(t('broadcast_room.status_host_share_stopped', 'Host yerel paylaşımı durduruldu: {name}', {
        name: selected?.name || t('broadcast_room.unknown_device', 'Bilinmeyen aygıt')
    }));
}

function stopHostLocalShare() {
    stopHostLocalShareById(String(state.selectedHostShareSourceId || els.hostShareSourceSelect?.value || '')).catch((error) => {
        setStatus(t('broadcast_room.status_host_share_stop_failed', 'Host yerel paylaşımı durdurulamadı: {error}', {
            error: error?.message || error || 'unknown_error'
        }));
    });
}

