function closeSceneSlotContextMenu({ restoreFocus = false } = {}) {
    if (els.sceneSlotContextMenu) {
        els.sceneSlotContextMenu.classList.remove('open');
        els.sceneSlotContextMenu.style.display = 'none';
        els.sceneSlotContextMenu.setAttribute('aria-hidden', 'true');
    }
    if (restoreFocus) {
        els.sceneSlotSelect?.focus?.();
    }
}

function renderSceneSlotContextMenu() {
    if (!els.sceneSlotContextMenuItems) {
        return;
    }
    const preset = getActiveScenePreset();
    const slot = preset?.slots.find((item) => item.id === state.selectedSceneSlotId) || null;
    if (!slot) {
        els.sceneSlotContextMenuItems.innerHTML = '';
        return;
    }
    const assignedState = getAssignedSceneSourceState(slot.id, preset?.id || '');
    const sources = getCompatibleSceneSourcesForSlot(slot.id);
    if (els.sceneSlotContextMenuName) {
        els.sceneSlotContextMenuName.textContent = t('broadcast_room.scene_slot_assignment_menu_summary', '{slot}. Atanan kaynak: {source}.', {
            slot: slot.label,
            source: assignedState.label
        });
    }

    clearMediaElementContainer(els.sceneSlotContextMenuItems);
    if (!sources.length) {
        const emptyButton = document.createElement('button');
        emptyButton.type = 'button';
        emptyButton.className = 'secondary';
        emptyButton.disabled = true;
        emptyButton.textContent = t('broadcast_room.scene_slot_assignment_no_sources', 'Bu slot için uygun kaynak yok.');
        els.sceneSlotContextMenuItems.appendChild(emptyButton);
        return;
    }

    sources.forEach((source) => {
        const isAssigned = source.id === assignedState.assignedId;
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'secondary';
        button.setAttribute('role', 'menuitem');
        button.setAttribute('data-scene-slot-menu-item', 'true');
        button.dataset.sceneSourceId = source.id;
        const baseLabel = source.typeLabel ? `${source.label} - ${source.typeLabel}` : source.label;
        const label = isAssigned
            ? t('broadcast_room.scene_slot_assignment_item_assigned', '{source}. Atanmış.', { source: baseLabel })
            : baseLabel;
        button.textContent = label;
        button.setAttribute('aria-label', label);
        button.addEventListener('click', () => {
            const assigned = assignSelectedSourceToSelectedSlot(source.id);
            if (assigned) {
                closeSceneSlotContextMenu({ restoreFocus: true });
            }
        });
        els.sceneSlotContextMenuItems.appendChild(button);
    });
}

function openSceneSlotContextMenu() {
    if (!isLocalRoomHost()) return;
    const preset = getActiveScenePreset();
    const slot = preset?.slots.find((item) => item.id === state.selectedSceneSlotId) || null;
    if (!slot || !els.sceneSlotContextMenu || !els.sceneSlotContextMenuPanel) {
        return;
    }
    renderSceneSlotContextMenu();
    els.sceneSlotContextMenu.style.display = 'flex';
    els.sceneSlotContextMenu.classList.add('open');
    els.sceneSlotContextMenu.setAttribute('aria-hidden', 'false');
    focusSceneSlotContextMenuItem(0);
}

