    els.persistentRoomContextMenuPanel?.addEventListener('keydown', (event) => {
        const actionButtons = getPersistentRoomContextActionButtons();
        const currentIndex = actionButtons.findIndex((button) => button === document.activeElement);
        if (event.key === 'ArrowDown' && actionButtons.length) {
            event.preventDefault();
            const nextIndex = currentIndex >= 0 ? (currentIndex + 1) % actionButtons.length : 0;
            actionButtons[nextIndex]?.focus?.();
            return;
        }
        if (event.key === 'ArrowUp' && actionButtons.length) {
            event.preventDefault();
            const nextIndex = currentIndex >= 0
                ? (currentIndex - 1 + actionButtons.length) % actionButtons.length
                : actionButtons.length - 1;
            actionButtons[nextIndex]?.focus?.();
            return;
        }
        if (event.key === 'ArrowLeft' || event.key === 'Escape') {
            event.preventDefault();
            closePersistentRoomContextMenu();
            els.persistentRoomsList?.querySelector?.('[data-persistent-room-listbox]')?.focus?.();
        }
    });
