    els.sceneSlotContextMenuPanel?.addEventListener('keydown', (event) => {
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            moveSceneSlotContextMenuFocus(1);
            return;
        }
        if (event.key === 'ArrowUp') {
            event.preventDefault();
            moveSceneSlotContextMenuFocus(-1);
            return;
        }
        if (event.key === 'Tab') {
            event.preventDefault();
            moveSceneSlotContextMenuFocus(event.shiftKey ? -1 : 1);
            return;
        }
        if (event.key === 'ArrowLeft' || event.key === 'Escape') {
            event.preventDefault();
            closeSceneSlotContextMenu({ restoreFocus: true });
        }
    });
